//#archivo js/games/directa-inversa.js
// Directa, inversa o ninguna (lección 1.2): arrastrar cada situación a la caja de la relación que
// describe. Al bloquear, las mal clasificadas se mueven a su caja correcta.
// params = { items: [{ text, kind: 'directa'|'inversa'|'ninguna' }] }   state = { assigned: [kind | null] }

GAMES['directa-inversa'] = (() => {
  const KINDS = ['directa', 'inversa', 'ninguna'];
  const NAMES = { directa: 'Directa', inversa: 'Inversa', ninguna: 'Ninguna' };

  function grade(state, params) {
    const wrong = params.items.filter((it, i) => state.assigned[i] !== it.kind);
    if (!wrong.length) return { ok: true, solution: 'Todas las situaciones están bien clasificadas.' };
    return { ok: false, solution: wrong.map(it => `${it.text} → ${NAMES[it.kind]}`).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette;
    const assigned = params.items.map(() => null);
    let locked = false, boxes = {}, cards = [], drag = -1, grab = { x: 0, y: 0 }, W = 0, H = 0;
    const CARD_H = 44, COLORS = { directa: C.Q, inversa: C.N, ninguna: C.I };

    function layout(w, h) {
      W = w; H = h;
      const bw = (w - 32) / 3, by = 30, bh = h * 0.5;
      KINDS.forEach((k, i) => { boxes[k] = { x: 12 + i * (bw + 4), y: by, w: bw, h: bh }; });
      const cw = (w - 28) / 2;
      cards = params.items.map((it, i) => {
        const hx = 12 + (i % 2) * (cw + 4), hy = by + bh + 14 + Math.floor(i / 2) * (CARD_H + 6);
        return { ...it, i, w: cw, h: CARD_H, hw: cw, hx, hy, x: hx, y: hy, tx: hx, ty: hy };
      });
      arrange(c => assigned[c.i]);
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    // Las tarjetas colocadas se apilan dentro de su caja, más angostas; las demás vuelven a la bandeja.
    function arrange(where) {
      const n = {};
      cards.forEach(c => {
        const k = where(c);
        if (!k) { c.w = c.hw; c.tx = c.hx; c.ty = c.hy; return; }
        const b = boxes[k], slot = (n[k] = (n[k] || 0) + 1) - 1;
        c.w = b.w - 8; c.tx = b.x + 4; c.ty = b.y + 26 + slot * (CARD_H + 4);
      });
    }
    // Texto en hasta tres líneas que quepa en la tarjeta.
    function wrap(p, text, maxW) {
      const words = text.split(' '), lines = [''];
      words.forEach(w => { const t = (lines[lines.length - 1] + ' ' + w).trim(); if (p.textWidth(t) <= maxW || !lines[lines.length - 1]) lines[lines.length - 1] = t; else lines.push(w); });
      return lines.slice(0, 3);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => { layout(size.w, size.h); cards.forEach(c => { c.x = c.tx; c.y = c.ty; }); };

      function drawCard(c) {
        const k = locked ? c.kind : assigned[c.i];
        const border = locked ? (assigned[c.i] === c.kind ? C.ok : C.bad) : (c.i === drag ? C.brand : k ? COLORS[k] : C.line);
        p.stroke(border); p.strokeWeight(2); p.fill(C.card); p.rect(c.x, c.y, c.w, c.h, 9);
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
        p.textSize(c.w < 140 ? 9.5 : 11); const lh = c.w < 140 ? 11 : 12.5;
        const lines = wrap(p, c.text, c.w - 10);
        lines.forEach((ln, j) => p.text(ln, c.x + c.w / 2, c.y + c.h / 2 + (j - (lines.length - 1) / 2) * lh));
      }

      p.draw = () => {
        p.background(C.bg);
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(12);
        p.text('¿Cómo se relacionan las dos magnitudes?', W / 2, 8);
        KINDS.forEach(k => {
          const b = boxes[k], col = COLORS[k];
          p.stroke(col); p.strokeWeight(2); p.fill(p.red(p.color(col)), p.green(p.color(col)), p.blue(p.color(col)), 24); p.rect(b.x, b.y, b.w, b.h, 12);
          p.noStroke(); p.fill(col); p.textSize(13); p.textAlign(p.CENTER, p.TOP); p.text(NAMES[k], b.x + b.w / 2, b.y + 6);
        });
        cards.forEach(c => { if (c.i !== drag) { c.x = p.lerp(c.x, c.tx, 0.2); c.y = p.lerp(c.y, c.ty, 0.2); } });
        cards.filter(c => c.i !== drag).forEach(drawCard);
        if (drag >= 0) drawCard(cards[drag]);
      };

      p.mousePressed = () => {
        if (locked) return;
        for (let k = cards.length - 1; k >= 0; k--) {
          const c = cards[k];
          if (inside(c, p.mouseX, p.mouseY)) { drag = c.i; grab = { x: p.mouseX - c.x, y: p.mouseY - c.y }; api.sfx?.tap?.(); return false; }
        }
      };
      p.mouseDragged = () => {
        if (drag < 0) return;
        const c = cards[drag];
        c.x = p.constrain(p.mouseX - grab.x, 0, W - c.w); c.y = p.constrain(p.mouseY - grab.y, 0, H - c.h);
        return false;
      };
      p.mouseReleased = () => {
        if (drag < 0) return;
        assigned[drag] = KINDS.find(k => inside(boxes[k], p.mouseX, p.mouseY)) || null;
        drag = -1;
        arrange(c => assigned[c.i]);
        api.ready(assigned.every(Boolean));
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ assigned: [...assigned] }),
      lock() { locked = true; arrange(c => c.kind); },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/grafica-relacion.js
// Grafica la relación (lección 1.2): en una cuadrícula hay un punto dado fijo; se arrastran en
// vertical los puntos de otras x para que la relación sea directa (y = kx) o inversa (xy = k).
// Al bloquear se dibuja la recta o la hipérbola correcta.
// params = { kind: 'directa'|'inversa', k, given: [[x, y]], xs: number[], tol, xmax, ymax }
// state = { ys: [número | null] }  (altura del punto sobre cada x de xs)

GAMES['grafica-relacion'] = (() => {
  const f = (params, x) => (params.kind === 'directa' ? params.k * x : params.k / x);

  function grade(state, params) {
    const ok = params.xs.every((x, i) => state.ys?.[i] != null && Math.abs(state.ys[i] - f(params, x)) <= params.tol);
    const rule = params.kind === 'directa' ? `y = ${params.k}x` : `xy = ${params.k}`;
    return { ok, solution: `$${rule}$: ${params.xs.map(x => `$(${x}, ${+f(params, x).toFixed(2)})$`).join(', ')}` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const ys = params.xs.map(() => null);
    let locked = false, W = 0, H = 0, mx = null, my = null, drag = -1;
    const STEP = 0.25;

    function layout(w, h) {
      W = w; H = h;
      mx = lineMap(0, params.xmax, 40, w - 16);
      my = lineMap(0, params.ymax, h - 34, 44);
    }
    const px = (x, y) => [mx.toPx(x), my.toPx(y)];
    // Un punto sin colocar descansa en el eje x; así se ve dónde falta.
    const yOf = i => (ys[i] === null ? 0 : ys[i]);

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        drawKicker(p, C, params.kind === 'directa' ? 'Mueve los puntos: que sea directa' : 'Mueve los puntos: que sea inversa', W / 2, 14, { center: true });
        p.noStroke(); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.fill(C.ink); p.textSize(12);
        p.text(params.kind === 'directa' ? 'y/x constante · recta por el origen' : 'x·y constante · si x se duplica, y se reduce a la mitad', W / 2, 25);
        // Cuadrícula y ejes.
        for (let x = 0; x <= params.xmax; x++) { p.stroke(x ? C.line + '66' : C.mute); p.strokeWeight(x ? 1 : 2); p.line(...px(x, 0), ...px(x, params.ymax)); }
        for (let y = 0; y <= params.ymax; y++) { p.stroke(y ? C.line + '66' : C.mute); p.strokeWeight(y ? 1 : 2); p.line(...px(0, y), ...px(params.xmax, y)); }
        p.noStroke(); p.fill(C.mute); p.textSize(10); p.textAlign(p.CENTER, p.TOP);
        for (let x = 0; x <= params.xmax; x += 2) p.text(x, mx.toPx(x), my.toPx(0) + 5);
        p.textAlign(p.RIGHT, p.CENTER);
        for (let y = 0; y <= params.ymax; y += 2) p.text(y, mx.toPx(0) - 6, my.toPx(y));
        if (locked) {
          // Curva correcta.
          p.noFill(); p.stroke(C.ok); p.strokeWeight(2.5); p.beginShape();
          for (let x = params.kind === 'directa' ? 0 : params.k / params.ymax; x <= params.xmax; x += 0.05) { const y = f(params, x); if (y <= params.ymax) p.vertex(...px(x, y)); }
          p.endShape();
        }
        // Punto dado (fijo) y puntos movibles.
        params.given.forEach(([x, y]) => {
          drawDot(p, C, ...px(x, y), 14, C.sun);
          p.fill(C.ink); p.textSize(11); p.textAlign(p.LEFT, p.BOTTOM); p.text(`(${x}, ${y})`, mx.toPx(x) + 10, my.toPx(y) - 6);
        });
        params.xs.forEach((x, i) => {
          const [cx, cy] = px(x, yOf(i));
          const good = ys[i] !== null && Math.abs(ys[i] - f(params, x)) <= params.tol;
          const col = locked ? (good ? C.ok : C.bad) : (i === drag ? C.ink : ys[i] === null ? C.mute : C.brand);
          p.stroke(col); p.strokeWeight(1.5); p.line(cx, my.toPx(0), cx, cy);
          p.noStroke(); p.fill(col); p.circle(cx, cy, 18);
          p.fill(C.bg); p.textSize(10); p.textAlign(p.CENTER, p.CENTER); p.text(x, cx, cy + 1);
          if (ys[i] !== null) { p.fill(C.ink); p.textSize(11); p.textAlign(p.LEFT, p.BOTTOM); p.text(`(${x}, ${ys[i]})`, cx + 10, cy - 6); }
        });
      };

      p.mousePressed = () => {
        if (locked) return;
        drag = nearest(params.xs.map((x, i) => ({ x: mx.toPx(x), y: my.toPx(yOf(i)) })), p.mouseX, p.mouseY, 22);
        if (drag >= 0) { api.sfx?.tap?.(); return false; }
      };
      p.mouseDragged = () => {
        if (drag < 0) return;
        ys[drag] = Math.round(p.constrain(my.toVal(p.mouseY), 0, params.ymax) / STEP) * STEP;
        return false;
      };
      p.mouseReleased = () => {
        if (drag < 0) return;
        drag = -1;
        api.ready(ys.every(y => y !== null));
        return false;
      };
    }, 1.0);

    return {
      loaded: m.ready,
      getState: () => ({ ys: [...ys] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/reparto.js
// Reparto proporcional (lección 1.2): una barra representa el total; dos separadores arrastrables
// la parten en tres montos que se ven en vivo. Correcto si cada parte queda en la razón pedida.
// params = { total, parts: [p1, p2, p3], tol }   state = { cuts: [fracción, fracción] } (0–1, en cualquier orden)

GAMES['reparto'] = (() => {
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const shares = params => { const s = params.parts.reduce((a, b) => a + b, 0); return params.parts.map(p => p / s); };
  const amounts = (cuts, total) => { const [a, b] = [...cuts].sort((x, y) => x - y); return [a * total, (b - a) * total, (1 - b) * total]; };

  function grade(state, params) {
    const want = shares(params).map(s => s * params.total), got = amounts(state.cuts, params.total);
    const ok = got.every((g, i) => Math.abs(g - want[i]) <= params.tol * params.total);
    return { ok, solution: `${params.parts.join(' + ')} = ${params.parts.reduce((a, b) => a + b, 0)} partes; cada parte vale ${fmt(params.total / params.parts.reduce((a, b) => a + b, 0))}: ${want.map(fmt).join(' / ')}` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { cuts: [1 / 3, 2 / 3] };
    let locked = false, W = 0, H = 0, bar = null, drag = -1;
    const COLS = [C.Q, C.N, C.R];

    function layout(w, h) { W = w; H = h; bar = { x: 16, y: h * 0.42, w: w - 32, h: 44 }; }
    const cx = f => bar.x + f * bar.w;

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const cuts = [...st.cuts].sort((a, b) => a - b), got = amounts(st.cuts, params.total);
        const want = shares(params);
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        drawKicker(p, C, `Reparte ${fmt(params.total)} en la razón ${params.parts.join(' : ')}`, W / 2, 16, { center: true });
        p.noStroke(); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.fill(C.ink); p.textSize(12); p.text('Arrastra los separadores', W / 2, 30);
        // Barra en tres tramos.
        const edges = [0, ...cuts, 1];
        for (let i = 0; i < 3; i++) {
          const x0 = cx(edges[i]), x1 = cx(edges[i + 1]);
          const good = Math.abs(got[i] - want[i] * params.total) <= params.tol * params.total;
          p.noStroke(); p.fill(COLS[i]); p.rect(x0, bar.y, x1 - x0, bar.h, i === 0 ? 10 : 0, i === 2 ? 10 : 0, i === 2 ? 10 : 0, i === 0 ? 10 : 0);
          // Monto y porcentaje de cada tramo, debajo (alternando alturas si el tramo es angosto).
          p.fill(locked ? (good ? C.ok : C.bad) : C.ink); p.textAlign(p.CENTER, p.TOP); p.textSize(13);
          const ty = bar.y + bar.h + 10 + (i % 2) * 34;
          p.text(fmt(got[i]), (x0 + x1) / 2, ty);
          p.fill(C.mute); p.textSize(11); p.text(`${Math.round((edges[i + 1] - edges[i]) * 100)} %`, (x0 + x1) / 2, ty + 16);
        }
        if (locked) {
          // Cortes correctos marcados en verde.
          let acc = 0; want.slice(0, 2).forEach(s => { acc += s; p.stroke(C.ok); p.strokeWeight(3); p.line(cx(acc), bar.y - 14, cx(acc), bar.y + bar.h + 6); });
        }
        // Separadores.
        st.cuts.forEach((f, i) => {
          const x = cx(f);
          p.stroke(i === drag ? C.ink : C.brand); p.strokeWeight(4); p.line(x, bar.y - 8, x, bar.y + bar.h + 8);
          p.noStroke(); p.fill(i === drag ? C.ink : C.brand); p.circle(x, bar.y - 16, 22);
          p.fill(C.bg); p.textAlign(p.CENTER, p.CENTER); p.textSize(12); p.text('⇔', x, bar.y - 15);
        });
        // Marcas de referencia en la barra: décimos.
        p.stroke(C.bg); p.strokeWeight(1);
        for (let k = 1; k < 10; k++) p.line(cx(k / 10), bar.y + bar.h - 6, cx(k / 10), bar.y + bar.h);
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.TOP);
        p.text(`Partes: ${params.parts.join(' + ')} = ${params.parts.reduce((a, b) => a + b, 0)} · ¿cuánto vale una parte?`, W / 2, H - 22);
      };

      p.mousePressed = () => {
        if (locked) return;
        if (Math.abs(p.mouseY - (bar.y + bar.h / 2)) > 40) return;
        drag = st.cuts.map((f, i) => [Math.abs(p.mouseX - cx(f)), i]).sort((a, b) => a[0] - b[0])[0][1];
        api.sfx?.tap?.();
        return false;
      };
      p.mouseDragged = () => {
        if (drag < 0) return;
        // Ajuste fino al 0.5 % para que los montos salgan redondos.
        st.cuts[drag] = Math.round(p.constrain((p.mouseX - bar.x) / bar.w, 0, 1) * 200) / 200;
        return false;
      };
      p.mouseReleased = () => { if (drag >= 0) { drag = -1; api.ready(true); return false; } };
    }, 0.72);

    return {
      loaded: m.ready,
      getState: () => ({ cuts: [...st.cuts] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cuadrado-media.js
// Cuadrado de la media (lección 1.2): un rectángulo w × h a escala y un cuadrado que crece al
// arrastrar su esquina. Correcto cuando ambas áreas coinciden: el lado es la media proporcional √(w·h).
// params = { w, h, tol }   state = { side: número }

GAMES['cuadrado-media'] = (() => {
  function grade(state, params) {
    const side = Math.sqrt(params.w * params.h);
    const ok = Math.abs(state.side - side) <= params.tol;
    return { ok, solution: `$\\dfrac{${params.w}}{x} = \\dfrac{x}{${params.h}} \\Rightarrow x^2 = ${params.w * params.h} \\Rightarrow x = ${+side.toFixed(2)}$` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { side: Math.min(params.w, params.h) };
    let locked = false, W = 0, H = 0, scale = 1, rect = null, sq = null, drag = false;
    const target = Math.sqrt(params.w * params.h);

    function layout(w, h) {
      W = w; H = h;
      // Escala: el rectángulo (de pie) y el cuadrado máximo caben uno al lado del otro.
      const maxSide = Math.max(params.h, target * 1.3);
      scale = Math.min((h - 90) / maxSide, (w - 48) / (params.w + target * 1.3 + 24));
      rect = { x: 16, y: h - 36 };
      sq = { x: 16 + params.w * scale + 28, y: h - 36 };
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);
      const corner = () => ({ x: sq.x + st.side * scale, y: sq.y - st.side * scale });

      p.draw = () => {
        p.background(C.bg);
        const area = st.side * st.side, want = params.w * params.h;
        const good = Math.abs(st.side - target) <= params.tol;
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        drawKicker(p, C, 'Iguala el área con un cuadrado', W / 2, 14, { center: true });
        p.noStroke(); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.fill(C.ink); p.textSize(18); p.text(`${params.w}/x = x/${params.h}`, W / 2, 26);
        // Rectángulo w × h.
        p.noStroke(); p.fill(C.sky);   // el rectángulo, relleno
        p.rect(rect.x, rect.y - params.h * scale, params.w * scale, params.h * scale, 4);
        p.noStroke(); p.fill(C.R); p.textSize(12); p.textAlign(p.CENTER, p.TOP);
        p.text(`${params.w} × ${params.h}`, rect.x + params.w * scale / 2, rect.y + 6);
        p.text(`área ${want}`, rect.x + params.w * scale / 2, rect.y + 20);
        // Cuadrado x × x.
        const col = locked ? (good ? C.ok : C.bad) : good ? C.ok : C.brand;
        p.stroke(col); p.strokeWeight(2.5); p.fill(p.red(p.color(col)), p.green(p.color(col)), p.blue(p.color(col)), 120);
        p.rect(sq.x, sq.y - st.side * scale, st.side * scale, st.side * scale, 4);
        if (locked) { p.noFill(); p.stroke(C.ok); p.strokeWeight(2); p.drawingContext.setLineDash([5, 4]); p.rect(sq.x, sq.y - target * scale, target * scale, target * scale, 4); p.drawingContext.setLineDash([]); }
        const c = corner();
        drawDot(p, C, c.x, c.y, 20, drag ? C.ink : col);
        p.fill(C.bg); p.textAlign(p.CENTER, p.CENTER); p.textSize(12); p.text('⤡', c.x, c.y);
        p.fill(col); p.textSize(12); p.textAlign(p.CENTER, p.TOP);
        p.text(`x = ${st.side.toFixed(1)}`, sq.x + Math.max(st.side * scale / 2, 30), sq.y + 6);
        p.text(`área ${area.toFixed(1)}`, sq.x + Math.max(st.side * scale / 2, 30), sq.y + 20);
        p.textAlign(p.CENTER, p.CENTER); p.textSize(14); p.fill(col);
        drawPill(p, C, good ? '¡Las áreas coinciden!' : area < want ? 'Al cuadrado le falta área' : 'Al cuadrado le sobra área', W / 2, 62, col, 13);
      };

      p.mousePressed = () => {
        if (locked) return;
        const c = corner();
        if (Math.hypot(p.mouseX - c.x, p.mouseY - c.y) < 26 || (p.mouseX > sq.x && p.mouseX < c.x && p.mouseY < sq.y && p.mouseY > c.y)) { drag = true; api.sfx?.tap?.(); return false; }
      };
      p.mouseDragged = () => {
        if (!drag) return;
        // El lado sigue a la esquina (promedio de ambas direcciones) con pasos de 0.1.
        const s = ((p.mouseX - sq.x) + (sq.y - p.mouseY)) / 2 / scale;
        st.side = Math.round(p.constrain(s, 1, (H - 90) / scale) * 10) / 10;
        return false;
      };
      p.mouseReleased = () => { if (drag) { drag = false; api.ready(true); return false; } };
    }, 0.95);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/arma-regla.js
// Arma la regla (lección 1.2): para cada problema se arrastran los cuatro datos a una tabla de
// dos filas (misma magnitud por columna, misma situación por fila) y se elige el tipo de flechas:
// paralelas (directa) o cruzadas (inversa). Al bloquear se escribe la proporción que queda armada.
// params = { problems: [{ text, kind: 'directa'|'inversa', chips: [{ label, mag, row }] }] }
// state = { problems: [{ cells: [[i, i], [i, i]], arrow: 'directa'|'inversa'|null }] }

GAMES['arma-regla'] = (() => {
  const ARROWS = { directa: 'paralelas', inversa: 'cruzadas' };

  // La tabla está bien si cada columna tiene una sola magnitud (en cualquier orden de columnas)
  // y cada fila una sola situación (en cualquier orden de filas).
  function tableOk(p, cells) {
    const idx = cells.flat();
    if (idx.some(i => i == null) || new Set(idx).size !== 4) return false;
    const mag = (r, c) => p.chips[cells[r][c]].mag, row = (r, c) => p.chips[cells[r][c]].row;
    return mag(0, 0) === mag(1, 0) && mag(0, 1) === mag(1, 1) && mag(0, 0) !== mag(0, 1) &&
      row(0, 0) === row(0, 1) && row(1, 0) === row(1, 1) && row(0, 0) !== row(1, 0);
  }

  function grade(state, params) {
    const wrong = params.problems.map((p, k) => {
      const s = state.problems[k];
      const table = tableOk(p, s.cells), arrow = s.arrow === p.kind;
      if (table && arrow) return null;
      return `Problema ${k + 1}: ${table ? '' : 'cada columna lleva una sola magnitud y cada fila una situación; '}flechas ${ARROWS[p.kind]} (${p.kind})`;
    }).filter(Boolean);
    return { ok: !wrong.length, solution: wrong.length ? wrong.join(' · ') : 'Las dos reglas están bien armadas.' };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = params.problems.map(() => ({ cells: [[null, null], [null, null]], arrow: null }));
    let locked = false, cur = 0, W = 0, H = 0, tabs = [], cells = [], arrowBtns = [], chips = [], drag = -1, grab = { x: 0, y: 0 };
    const CH = 36;

    function layout(w, h) {
      W = w; H = h;
      tabs = params.problems.map((_, k) => ({ x: w / 2 + (k - (params.problems.length - 1) / 2) * 70 - 30, y: 8, w: 60, h: 26 }));
      // Hueco ancho entre columnas: ahí se dibujan las flechas paralelas o cruzadas.
      const cw = (w - 84) / 2, ty = 108;
      cells = [0, 1].map(r => [0, 1].map(c => ({ x: 20 + c * (cw + 44), y: ty + r * 50, w: cw, h: CH + 4 })));
      arrowBtns = ['directa', 'inversa'].map((k, i) => ({ k, x: 12 + i * ((w - 32) / 2 + 8), y: ty + 118, w: (w - 32) / 2, h: 34 }));
      const hw = (w - 36) / 2;
      chips = params.problems.map(p => p.chips.map((c, i) => ({ ...c, i, w: hw, h: CH, hx: 12 + (i % 2) * (hw + 12), hy: ty + 196 + Math.floor(i / 2) * (CH + 10), x: 0, y: 0 })));
      chips.forEach((list, k) => list.forEach(c => { const pos = cellOf(k, c.i); c.x = pos ? pos.x + 2 : c.hx; c.y = pos ? pos.y + 2 : c.hy; }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    function cellOf(k, i) {
      for (let r = 0; r < 2; r++) for (let c = 0; c < 2; c++) if (st[k].cells[r][c] === i) return cells[r][c];
      return null;
    }
    function place(k, c) { const pos = cellOf(k, c.i); c.tx = pos ? pos.x + 2 : c.hx; c.ty = pos ? pos.y + 2 : c.hy; }
    const ready = () => api.ready(st.every(s => s.arrow && s.cells.flat().every(i => i != null)));
    function wrap(p, text, maxW) {
      const lines = [''];
      text.split(' ').forEach(w => { const t = (lines[lines.length - 1] + ' ' + w).trim(); if (p.textWidth(t) <= maxW || !lines[lines.length - 1]) lines[lines.length - 1] = t; else lines.push(w); });
      return lines;
    }
    const num = label => label.split(' ')[0];

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); chips.forEach(l => l.forEach(c => place(0, c))); chips.forEach((l, k) => l.forEach(c => { place(k, c); c.x = c.tx; c.y = c.ty; })); };
      p.onResize = () => { layout(size.w, size.h); chips.forEach((l, k) => l.forEach(c => { place(k, c); c.x = c.tx; c.y = c.ty; })); };

      function arrows(kind, col) {
        const a = cells[0][0], b = cells[0][1], c2 = cells[1][0], d = cells[1][1];
        p.stroke(col); p.strokeWeight(3); p.noFill();
        const L = (x1, y1, x2, y2) => { p.line(x1, y1, x2, y2); const ang = Math.atan2(y2 - y1, x2 - x1); p.line(x2, y2, x2 - 9 * Math.cos(ang - 0.5), y2 - 9 * Math.sin(ang - 0.5)); p.line(x2, y2, x2 - 9 * Math.cos(ang + 0.5), y2 - 9 * Math.sin(ang + 0.5)); };
        if (kind === 'directa') { L(a.x + a.w + 2, a.y + a.h / 2, b.x - 2, b.y + b.h / 2); L(c2.x + c2.w + 2, c2.y + c2.h / 2, d.x - 2, d.y + d.h / 2); }
        else { L(a.x + a.w + 2, a.y + a.h - 4, d.x - 2, d.y + 4); L(c2.x + c2.w + 2, c2.y + 4, b.x - 2, b.y + b.h - 4); }
      }

      p.draw = () => {
        p.background(C.bg);
        const prob = params.problems[cur], s = st[cur];
        const good = locked && tableOk(prob, s.cells) && s.arrow === prob.kind;
        tabs.forEach((t, k) => {
          const done = st[k].arrow && st[k].cells.flat().every(i => i != null);
          if (k === cur) { p.noFill(); p.stroke(C.sun); p.strokeWeight(2.5); p.rect(t.x - 3, t.y - 3, t.w + 6, t.h + 6, 16); }
          p.noStroke(); p.fill(k === cur ? C.brand : C.card); p.rect(t.x, t.y, t.w, t.h, 13);
          p.fill(k === cur ? inkOn(C.brand, C.ink) : C.mute); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(12);
          p.text(`${k + 1}${done ? ' ✓' : ''}`, t.x + t.w / 2, t.y + t.h / 2 + 1);
        });
        p.noStroke(); p.fill(C.ink); p.textAlign(p.CENTER, p.TOP); p.textSize(13); p.textStyle(p.BOLD);
        wrap(p, prob.text, W - 24).slice(0, 3).forEach((ln, i) => p.text(ln, W / 2, 44 + i * 17));
        // Tabla.
        cells.forEach(row => row.forEach(cell => { p.stroke(C.mute); p.strokeWeight(2); p.drawingContext.setLineDash([6, 5]); p.noFill(); p.rect(cell.x, cell.y, cell.w, cell.h, 10); p.drawingContext.setLineDash([]); }));
        if (s.arrow) arrows(s.arrow, locked ? (s.arrow === prob.kind ? C.ok : C.bad) : C.brand);
        arrowBtns.forEach(b => {
          const on = s.arrow === b.k;
          drawTile(p, C, b, b.k === 'directa' ? '⇉ paralelas' : '⤧ cruzadas', { fill: on ? C.sun : C.cream, size: 13, lift: on ? 1 : 3 });
        });
        if (locked) {
          const ch = s.cells, lab = (r, c) => (ch[r][c] == null ? '?' : num(prob.chips[ch[r][c]].label));
          const prop = prob.kind === 'directa' ? `${lab(0, 0)}/${lab(1, 0)} = ${lab(0, 1)}/${lab(1, 1)}` : `${lab(0, 0)}/${lab(1, 0)} = ${lab(1, 1)}/${lab(0, 1)}`;
          p.noStroke(); p.fill(good ? C.ok : C.bad); p.textSize(16); p.textAlign(p.CENTER, p.CENTER);
          p.text(`${prop}  ·  flechas ${ARROWS[prob.kind]}`, W / 2, arrowBtns[0].y + 58);
        } else { p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.text('Arrastra los datos a la tabla y elige las flechas', W / 2, arrowBtns[0].y + 58); }
        // Fichas del problema actual.
        chips[cur].forEach(c => {
          if (c.i !== drag) { c.x = p.lerp(c.x, c.tx, 0.25); c.y = p.lerp(c.y, c.ty, 0.25); }
          // Dentro de una celda la ficha toma el ancho de la celda; en la bandeja, el suyo.
          const inCell = cellOf(cur, c.i), cw = inCell && c.i !== drag ? inCell.w - 4 : c.w;
          // Ficha crema; color sol al arrastrarla o ya puesta en la tabla; al calificar, del color del resultado.
          const tcol = inCell && locked ? (good ? C.ok : C.bad) : inCell || c.i === drag ? C.sun : C.cream;
          drawTile(p, C, { x: c.x, y: c.y, w: cw, h: c.h }, c.label, { fill: tcol, r: 9, lift: 2, size: Math.min(14, cw / 8) });
        });
      };

      p.mousePressed = () => {
        const t = tabs.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; api.sfx?.tap?.(); return false; }
        if (locked) return;
        const b = arrowBtns.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { st[cur].arrow = b.k; api.sfx?.tap?.(); ready(); return false; }
        for (let k = chips[cur].length - 1; k >= 0; k--) {
          const c = chips[cur][k];
          if (inside({ x: c.x, y: c.y, w: c.w, h: c.h }, p.mouseX, p.mouseY)) { drag = c.i; grab = { x: p.mouseX - c.x, y: p.mouseY - c.y }; api.sfx?.tap?.(); return false; }
        }
      };
      p.mouseDragged = () => {
        if (drag < 0) return;
        const c = chips[cur][drag];
        c.x = p.constrain(p.mouseX - grab.x, 0, W - c.w); c.y = p.constrain(p.mouseY - grab.y, 0, H - c.h);
        return false;
      };
      p.mouseReleased = () => {
        if (drag < 0) return;
        const s = st[cur], from = (() => { for (let r = 0; r < 2; r++) for (let c = 0; c < 2; c++) if (s.cells[r][c] === drag) return [r, c]; return null; })();
        let target = null;
        for (let r = 0; r < 2; r++) for (let c = 0; c < 2; c++) if (inside(cells[r][c], p.mouseX, p.mouseY)) target = [r, c];
        if (from) s.cells[from[0]][from[1]] = null;
        if (target) {
          // Soltar sobre un hueco ocupado intercambia las dos fichas.
          const other = s.cells[target[0]][target[1]];
          if (other != null && from) s.cells[from[0]][from[1]] = other;
          s.cells[target[0]][target[1]] = drag;
        }
        drag = -1;
        chips[cur].forEach(c => place(cur, c));
        ready();
        return false;
      };
    }, 1.3);

    return {
      loaded: m.ready,
      getState: () => ({ problems: st.map(s => ({ cells: s.cells.map(r => [...r]), arrow: s.arrow })) }),
      lock() { locked = true; const bad = params.problems.findIndex((p, k) => !(tableOk(p, st[k].cells) && st[k].arrow === p.kind)); if (bad >= 0) cur = bad; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/bascula.js
// La báscula del mercado (lección 1.2): se conoce el precio de unos kilos y hay que fijar, con una
// rueda de precio, lo que cuestan otros kilos (regla de tres simple directa).
// params = { knownKg, knownPrice, askKg, max, step, tol }   state = { price: número | null }

GAMES['bascula'] = (() => {
  const answerOf = p => (p.knownPrice * p.askKg) / p.knownKg;
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const texNum = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');

  function grade(state, params) {
    const ans = answerOf(params);
    const ok = state.price !== null && Math.abs(state.price - ans) <= params.tol;
    return { ok, solution: `$\\dfrac{${texNum(params.knownPrice)}}{${params.knownKg}} \\cdot ${params.askKg} = ${texNum(ans)}$ pesos` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { price: null };
    let locked = false, W = 0, H = 0, wheel = null, buttons = [], drag = null, shown = 0;
    const APPLE = '#E8453C', LEAF = '#5FBF5F';

    function layout(w, h) {
      W = w; H = h;
      wheel = { x: w * 0.62, y: h * 0.5, w: w * 0.3, h: h * 0.3 };
      buttons = [
        { d: -params.step, x: wheel.x, y: wheel.y + wheel.h + 8, w: wheel.w / 2 - 3, h: 32, t: '−' },
        { d: params.step, x: wheel.x + wheel.w / 2 + 3, y: wheel.y + wheel.h + 8, w: wheel.w / 2 - 3, h: 32, t: '+' },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const shownPrice = () => (st.price === null ? 0 : st.price);
    function setPrice(v) {
      st.price = Math.max(0, Math.min(params.max, Math.round(v / params.step) * params.step));
      api.ready(true);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function apple(x, y, r) {
        p.noStroke(); p.fill(APPLE); p.circle(x, y, r * 2);
        p.fill('#fff6'); p.circle(x - r * 0.3, y - r * 0.3, r * 0.5);
        p.stroke('#7a4a2a'); p.strokeWeight(2); p.line(x, y - r, x + 2, y - r - 6);
        p.noStroke(); p.fill(LEAF); p.ellipse(x + 6, y - r - 4, 9, 5);
      }

      // Báscula: plato con las manzanas pedidas y pantalla con el precio fijado.
      function scale(cx, cy, kg, price, col) {
        const sink = 6 + kg * 2;
        p.stroke(C.mute); p.strokeWeight(4); p.line(cx, cy + 10, cx, cy + 60);
        p.noStroke(); p.fill(C.mute); p.rect(cx - 34, cy + 58, 68, 8, 4);
        p.stroke(C.ink); p.strokeWeight(3); p.noFill(); p.arc(cx, cy + sink, 90, 24, 0, p.PI);
        for (let i = 0; i < kg; i++) apple(cx - 28 + (i % 4) * 19, cy + sink - 10 - Math.floor(i / 4) * 16, 9);
        p.fill(C.card); p.stroke(col); p.strokeWeight(2); p.rect(cx - 44, cy + 70, 88, 30, 8);
        p.noStroke(); p.fill(col); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(14);
        p.text(price === null ? '— — —' : `$ ${fmt(price)}`, cx, cy + 85);
        p.fill(C.mute); p.textSize(11); p.text(`${kg} kg`, cx, cy + 112);
      }

      p.draw = () => {
        p.background(C.bg);
        shown = p.lerp(shown, shownPrice(), 0.3);
        const ans = answerOf(params), good = st.price !== null && Math.abs(st.price - ans) <= params.tol;
        // Dato conocido.
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(12);
        drawKicker(p, C, 'En el mercado', W / 2, 14, { center: true });
        p.noStroke(); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.fill(C.ink); p.textSize(18); p.text(`${params.knownKg} kg de manzanas → $ ${fmt(params.knownPrice)}`, W / 2, 24);
        p.fill(C.N); p.textSize(14); p.text(`¿Cuánto cuestan ${params.askKg} kg?`, W / 2, 50);
        for (let i = 0; i < params.knownKg; i++) apple(W / 2 - (params.knownKg - 1) * 11 + i * 22, 86, 9);
        // Báscula con el pedido y rueda de precio.
        const col = locked ? (good ? C.ok : C.bad) : st.price !== null && good ? C.ok : C.brand;
        scale(W * 0.27, H * 0.42, params.askKg, locked && !good ? ans : st.price, col);
        p.stroke(drag ? C.brand : C.line); p.strokeWeight(2.5); p.fill(C.card); p.rect(wheel.x, wheel.y, wheel.w, wheel.h, 14);
        p.noStroke(); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD);
        const v = shownPrice(), cy = wheel.y + wheel.h / 2;
        p.fill(C.mute + '66'); p.textSize(13);
        if (v + params.step <= params.max) p.text(fmt(v + params.step), wheel.x + wheel.w / 2, cy - wheel.h * 0.3);
        if (v - params.step >= 0) p.text(fmt(v - params.step), wheel.x + wheel.w / 2, cy + wheel.h * 0.3);
        p.fill(C.ink); p.textSize(Math.min(20, wheel.w / 4.6)); p.text(st.price === null ? '0' : fmt(v), wheel.x + wheel.w / 2, cy);
        p.fill(C.mute); p.textSize(11); p.text('precio', wheel.x + wheel.w / 2, wheel.y - 10);
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: C.sky, r: 8, lift: 2, size: 18 });
        });
        p.fill(C.mute); p.textSize(11); p.text('arrastra la rueda o toca ±', wheel.x + wheel.w / 2, buttons[0].y + 46);
        if (locked && !good) { p.fill(C.bad); p.textSize(13); p.text(`Debía ser $ ${fmt(ans)}`, W * 0.27, H * 0.42 + 134); }
      };

      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { setPrice(shownPrice() + b.d); api.sfx?.tap?.(); return false; }
        if (inside(wheel, p.mouseX, p.mouseY)) { drag = { y: p.mouseY, v: shownPrice() }; return false; }
      };
      // Arrastrar hacia arriba sube el precio; cuanto más lejos, más rápido.
      p.mouseDragged = () => {
        if (!drag) return;
        const dy = drag.y - p.mouseY;
        setPrice(drag.v + Math.sign(dy) * Math.pow(Math.abs(dy) / 6, 1.6) * params.step);
        return false;
      };
      p.mouseReleased = () => { if (drag) { drag = null; return false; } };
    }, 1.1);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/la-obra.js
// La obra (lección 1.2): se sabe cuántos obreros tardan cuántos días; se arrastran obreros de la
// banca a la obra (o se usan ±) y un calendario muestra los días que tardarían (producto constante,
// regla de tres inversa). Hay que dejar los obreros justos para terminar en los días pedidos.
// params = { workers, days, askDays, max }   state = { workers }

GAMES['la-obra'] = (() => {
  const answerOf = p => Math.round((p.workers * p.days) / p.askDays);
  const daysFor = (p, w) => (p.workers * p.days) / w;

  function grade(state, params) {
    const ans = answerOf(params);
    return { ok: state.workers === ans, solution: `$${params.workers} \\cdot ${params.days} = ${params.workers * params.days} = x \\cdot ${params.askDays} \\Rightarrow x = ${ans}$ obreros` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { workers: params.workers };
    let locked = false, W = 0, H = 0, bench = null, site = null, buttons = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      bench = { x: 12, y: h * 0.3, w: w * 0.34, h: h * 0.5 };
      site = { x: w * 0.34 + 28, y: h * 0.3, w: w - (w * 0.34 + 28) - 12, h: h * 0.5 };
      buttons = [
        { d: -1, x: site.x, y: site.y + site.h + 10, w: 44, h: 32, t: '−' },
        { d: 1, x: site.x + site.w - 44, y: site.y + site.h + 10, w: 44, h: 32, t: '+' },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    function setWorkers(n) {
      st.workers = Math.max(1, Math.min(params.max, n));
      api.ready(st.workers !== params.workers);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function worker(x, y, s, col) {
        p.noStroke(); p.fill(col); p.circle(x, y - s * 0.45, s * 0.45);
        p.rect(x - s * 0.3, y - s * 0.2, s * 0.6, s * 0.75, s * 0.12);
        p.fill(C.sun); p.arc(x, y - s * 0.5, s * 0.55, s * 0.4, p.PI, p.TWO_PI); // casco
      }
      // Obreros en cuadrícula dentro de una caja.
      function crowd(box, n, col, cols) {
        const s = Math.min(26, (box.w - 12) / cols / 1.1, (box.h - 30) / Math.ceil(Math.max(n, 1) / cols) / 1.3);
        for (let i = 0; i < n; i++) worker(box.x + 10 + (i % cols) * (box.w - 16) / cols + s * 0.5, box.y + 30 + Math.floor(i / cols) * s * 1.3 + s * 0.5, s, col);
      }

      p.draw = () => {
        p.background(C.bg);
        const ans = answerOf(params), good = st.workers === ans;
        const days = daysFor(params, st.workers);
        // Calendario.
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(12);
        p.text(`${params.workers} obreros × ${params.days} días = ${params.workers * params.days} obreros·día`, W / 2, 6);
        p.fill(C.N); p.textSize(14); p.text(`¿Cuántos obreros para terminar en ${params.askDays} días?`, W / 2, 24);
        const col = locked ? (good ? C.ok : C.bad) : Math.round(days) === params.askDays ? C.ok : C.brand;
        p.stroke(col); p.strokeWeight(2.5); p.fill(C.card); p.rect(W / 2 - 70, 48, 140, 50, 12);
        p.noStroke(); p.fill(col); p.rect(W / 2 - 70, 48, 140, 14, 12, 12, 0, 0);
        p.fill(C.ink); p.textSize(22); p.textAlign(p.CENTER, p.CENTER); p.text(`${Math.round(days)} días`, W / 2, 80);
        p.fill(C.mute); p.textSize(10); p.textAlign(p.CENTER, p.TOP); p.text('calendario', W / 2, 100);
        // Banca y obra.
        [['Banca', bench], ['Obra', site]].forEach(([name, box]) => {
          p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.rect(box.x, box.y, box.w, box.h, 12);
          p.noStroke(); p.fill(C.mute); p.textSize(12); p.textAlign(p.CENTER, p.TOP); p.text(name, box.x + box.w / 2, box.y + 8);
        });
        crowd(bench, Math.max(0, params.max - st.workers), C.mute, 4);
        crowd(site, st.workers, col, 5);
        p.noStroke(); p.fill(C.ink); p.textSize(16); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD);
        // Entre los botones − y +: si el hueco es angosto queda solo el número.
        const gap = site.w - 104;
        fitText(p, gap < 64 ? String(st.workers) : `${st.workers} obrero${st.workers === 1 ? '' : 's'}`, site.x + site.w / 2, buttons[0].y + 16, Math.max(24, gap), 16);
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: C.sky, r: 8, lift: 2, size: 18 });
        });
        p.fill(C.mute); p.textSize(11); p.text(locked && !good ? `Debían ser ${ans} obreros para ${params.askDays} días` : 'Arrastra obreros a la obra o toca ±', W / 2, H - 12);
        if (drag) worker(p.mouseX, p.mouseY, 30, C.brand);
      };

      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { setWorkers(st.workers + b.d); api.sfx?.tap?.(); return false; }
        if (inside(bench, p.mouseX, p.mouseY) && st.workers < params.max) { drag = 'bench'; return false; }
        if (inside(site, p.mouseX, p.mouseY) && st.workers > 1) { drag = 'site'; return false; }
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        if (drag === 'bench' && inside(site, p.mouseX, p.mouseY)) { setWorkers(st.workers + 1); api.sfx?.tap?.(); }
        if (drag === 'site' && inside(bench, p.mouseX, p.mouseY)) { setWorkers(st.workers - 1); api.sfx?.tap?.(); }
        drag = null;
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cadena-razones.js
// Cadena de razones (lección 1.2): la regla de tres compuesta como producto de razones. Cada
// tarjeta muestra una fracción que se voltea al tocarla (9/7 ⇄ 7/9); el resultado se calcula en
// vivo con un medidor «sube/baja» respecto al valor conocido.
// params = { base, unit, factors: [{ label, a, b, inverse }], answer }   state = { flipped: boolean[] }
// Una tarjeta sin voltear muestra a/b; la orientación correcta es a/b si la magnitud es inversa
// (la razón va «al revés» del cambio) y b/a si es directa.

GAMES['cadena-razones'] = (() => {
  const shownFrac = (f, flipped) => (flipped ? [f.b, f.a] : [f.a, f.b]);
  const result = (params, flipped) => params.factors.reduce((v, f, i) => { const [n, d] = shownFrac(f, flipped[i]); return (v * n) / d; }, params.base);
  const correct = f => !f.inverse;   // flipped debe ser true solo en las magnitudes directas

  function grade(state, params) {
    const ok = params.factors.every((f, i) => state.flipped[i] === correct(f));
    const chain = params.factors.map(f => { const [n, d] = shownFrac(f, correct(f)); return `\\tfrac{${n}}{${d}}`; }).join(' \\cdot ');
    return { ok, solution: `$x = ${params.base} \\cdot ${chain} = ${params.answer}$ ${params.unit}` };
  }

  function create(host, params, api) {
    const C = api.palette;
    // Arranca en la orientación ingenua (la razón «sigue» el cambio): el alumno debe voltear las inversas.
    const st = { flipped: params.factors.map(f => f.inverse) };
    let locked = false, W = 0, H = 0, cards = [], anim = params.factors.map(() => 0);

    function layout(w, h) {
      W = w; H = h;
      const n = params.factors.length, cw = 62, gap = 34, total = 92 + n * cw + (n - 1) * gap;
      const x0 = (w - total) / 2 + 92;
      cards = params.factors.map((_, i) => ({ x: x0 + i * (cw + gap), y: h * 0.42, w: cw, h: 70 }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); api.ready(true); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const x = result(params, st.flipped), good = params.factors.every((f, i) => st.flipped[i] === correct(f));
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(12);
        drawKicker(p, C, 'Regla de tres compuesta', W / 2, 14, { center: true });
        p.noStroke(); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.fill(C.ink); p.textSize(13);
        [`9 hombres hacen una obra en ${params.base} ${params.unit} a 6 h/día.`, '¿Cuántos días tardan 7 hombres a 8 h/día?'].forEach((ln, i) => p.text(ln, W / 2, 26 + i * 17));
        p.fill(C.N); p.textSize(12); p.text('Toca una tarjeta para voltear su razón', W / 2, 66);
        // Cadena: x = base × [a/b] × [a/b] = resultado
        const cy = cards[0].y + cards[0].h / 2;
        p.fill(C.ink); p.textSize(20); p.textAlign(p.RIGHT, p.CENTER); p.text(`x = ${params.base} ×`, cards[0].x - 8, cy);
        cards.forEach((c, i) => {
          const f = params.factors[i];
          anim[i] = Math.max(0, anim[i] - 0.1);
          const sx = Math.abs(1 - 2 * anim[i]);           // volteo: se estrecha y se vuelve a abrir
          const [n, d] = shownFrac(f, anim[i] > 0.5 ? !st.flipped[i] : st.flipped[i]);
          const col = locked ? (st.flipped[i] === correct(f) ? C.ok : C.bad) : C.brand;
          p.push(); p.translate(c.x + c.w / 2, cy); p.scale(sx, 1);
          // Tarjeta crema con relieve y borde del color del estado.
          p.noStroke(); p.fill(C.creamD); p.rect(-c.w / 2, -c.h / 2 + 4, c.w, c.h, 12);
          p.stroke(col); p.strokeWeight(2.5); p.fill(C.cream); p.rect(-c.w / 2, -c.h / 2, c.w, c.h, 12);
          p.noStroke(); p.fill(inkOn(C.cream, C.ink)); p.textAlign(p.CENTER, p.CENTER); p.textSize(20);
          p.text(n, 0, -16); p.text(d, 0, 18);
          p.stroke(inkOn(C.cream, C.ink)); p.strokeWeight(2); p.line(-16, 0, 16, 0);
          p.pop();
          if (i < cards.length - 1) { p.noStroke(); p.fill(C.ink); p.textSize(20); p.textAlign(p.CENTER, p.CENTER); p.text('×', c.x + c.w + 17, cy); }
          p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.TOP); p.text(f.label, c.x + c.w / 2, c.y + c.h + 6);
          if (locked) { p.fill(st.flipped[i] === correct(f) ? C.ok : C.bad); p.textSize(10); p.text(f.inverse ? 'inversa: al revés' : 'directa: igual', c.x + c.w / 2, c.y + c.h + 20); }
        });
        // Resultado y medidor sube/baja.
        const rcol = locked ? (good ? C.ok : C.bad) : C.ink;
        p.noStroke(); p.fill(rcol); p.textAlign(p.CENTER, p.CENTER); p.textSize(26);
        p.text(`= ${Number.isInteger(x) ? x : x.toFixed(1)} ${params.unit}`, W / 2, H * 0.72);
        const up = x > params.base, same = Math.abs(x - params.base) < 1e-9;
        p.fill(same ? C.mute : up ? C.ok : C.I); p.textSize(14);
        p.text(same ? `= igual que ${params.base}` : `${up ? '▲ sube' : '▼ baja'} respecto a ${params.base} ${params.unit}`, W / 2, H * 0.82);
        if (locked && !good) { p.fill(C.bad); p.textSize(13); p.text(`Debía dar ${params.answer} ${params.unit}`, W / 2, H * 0.92); }
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = cards.findIndex(c => inside(c, p.mouseX, p.mouseY));
        if (i < 0) return;
        st.flipped[i] = !st.flipped[i]; anim[i] = 1; api.sfx?.tap?.();
        return false;
      };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ flipped: [...st.flipped] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cuadricula-cien.js
// Pinta el porcentaje (lección 1.3): una cuadrícula de 10 × 10 que se pinta arrastrando el dedo.
// Tres rondas («35 %», «3/4», «0,08»): hay que dejar pintadas exactamente las casillas que pide
// cada una (por ciento = de cada 100).
// params = { rounds: [{ ask, count }] }   state = { counts: (número | null)[] }

GAMES['cuadricula-cien'] = (() => {
  function grade(state, params) {
    const ok = params.rounds.every((r, i) => state.counts[i] === r.count);
    const asks = params.rounds.map(r => r.ask), counts = params.rounds.map(r => r.count);
    const list = a => a.slice(0, -1).join(', ') + ' y ' + a[a.length - 1];
    return { ok, solution: `${list(asks)} son ${list(counts)} casillas de 100` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const N = params.rounds.length;
    const cells = params.rounds.map(() => new Array(100).fill(false));
    const st = { counts: params.rounds.map(() => null) };
    let locked = false, W = 0, H = 0, round = 0, paint = null, grid = null, tabs = [], nextBtn = null;

    function layout(w, h) {
      W = w; H = h;
      const size = Math.min(w - 24, h - 130);
      grid = { x: (w - size) / 2, y: 60, s: size, c: size / 10 };
      tabs = params.rounds.map((_, i) => ({ x: 12 + i * ((w - 24) / N), y: 8, w: (w - 24) / N - 6, h: 40 }));
      nextBtn = { x: grid.x + grid.s - 150, y: grid.y + grid.s + 12, w: 150, h: 34 };
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const cellAt = (x, y) => {
      const i = Math.floor((x - grid.x) / grid.c), j = Math.floor((y - grid.y) / grid.c);
      return i >= 0 && i < 10 && j >= 0 && j < 10 ? j * 10 + i : -1;
    };
    const count = k => cells[k].filter(Boolean).length;
    function setCell(idx, v) {
      if (idx < 0 || cells[round][idx] === v) return;
      cells[round][idx] = v;
      st.counts[round] = count(round);
      api.ready(st.counts.every(c => c !== null));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function mini(k, x, y, s) {
        for (let i = 0; i < 100; i++) {
          p.fill(cells[k][i] ? C.N : C.line); p.noStroke();   // C.N: en el tema claro el sol casi no se distingue de lo vacío
          p.rect(x + (i % 10) * s, y + Math.floor(i / 10) * s, s - 0.6, s - 0.6);
        }
      }

      p.draw = () => {
        p.background(C.bg);
        // Pestañas de ronda (con miniatura de las rondas ya tocadas).
        tabs.forEach((t, i) => {
          const good = st.counts[i] === params.rounds[i].count;
          const col = locked ? (good ? C.ok : C.bad) : i === round ? C.brand : C.line;
          p.stroke(col); p.strokeWeight(i === round ? 2.5 : 1.5); p.fill(C.card); p.rect(t.x, t.y, t.w, t.h, 10);
          p.noStroke(); p.fill(i === round || locked ? C.ink : C.mute); p.textAlign(p.LEFT, p.CENTER); p.textStyle(p.BOLD); p.textSize(14);
          p.text(params.rounds[i].ask, t.x + 10, t.y + t.h / 2);
          if (st.counts[i] !== null) mini(i, t.x + t.w - 34, t.y + 5, 3);
        });
        // Cuadrícula.
        const g = cells[round];
        for (let i = 0; i < 100; i++) {
          const x = grid.x + (i % 10) * grid.c, y = grid.y + Math.floor(i / 10) * grid.c;
          p.stroke(C.line); p.strokeWeight(1); p.fill(g[i] ? C.sun : C.card);
          p.rect(x, y, grid.c, grid.c, 3);
        }
        const n = count(round), good = n === params.rounds[round].count;
        const col = locked ? (good ? C.ok : C.bad) : C.N;
        p.noStroke(); p.fill(col); p.textAlign(p.LEFT, p.CENTER); p.textStyle(p.BOLD); p.textSize(18);
        p.text(`${n} de 100`, grid.x + 2, nextBtn.y + nextBtn.h / 2);
        if (!locked && round < N - 1) {
          drawTile(p, C, nextBtn, 'Siguiente ronda →', { fill: C.sky, size: 14 });
        }
        p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.NORMAL);
        p.text(locked && !good ? `Eran ${params.rounds[round].count} casillas` : 'Arrastra el dedo para pintar; vuelve a pasar para borrar', W / 2, H - 12);
      };

      p.mousePressed = () => {
        if (locked) return;
        const t = tabs.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (t >= 0) { round = t; api.sfx?.tap?.(); return false; }
        if (round < N - 1 && inside(nextBtn, p.mouseX, p.mouseY)) { round++; api.sfx?.tap?.(); return false; }
        const idx = cellAt(p.mouseX, p.mouseY);
        if (idx < 0) return;
        paint = !cells[round][idx];
        setCell(idx, paint);
        return false;
      };
      p.mouseDragged = () => {
        if (locked || paint === null) return;
        setCell(cellAt(p.mouseX, p.mouseY), paint);
        return false;
      };
      p.mouseReleased = () => {
        if (paint === null) return;
        paint = null;
        api.sfx?.tap?.();
        return false;
      };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ counts: [...st.counts] }),
      lock() { locked = true; paint = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cruz-porcentaje.js
// La cruz del porcentaje (lección 1.3): la regla de tres del tanto por ciento, 100 → C y p → B.
// Tres problemas; en cada uno se arrastran las fichas (los datos y la «?» de la incógnita) a las
// casillas p, C y B de la cruz. Una ficha con cell = null es un distractor.
// params = { problems: [{ text, chips: [{ label, cell }] }] }   state = { problems: [{ cells: { p, C, B } }] }

GAMES['cruz-porcentaje'] = (() => {
  const CELLS = ['p', 'C', 'B'];
  const NAMES = { p: 'porcentaje', C: 'base', B: 'parte' };

  function grade(state, params) {
    const ok = params.problems.every((pr, k) => CELLS.every(c => {
      const i = state.problems[k]?.cells?.[c];
      return i != null && pr.chips[i]?.cell === c;
    }));
    const solution = params.problems.map(pr => CELLS.map(c => `${c} = ${pr.chips.find(ch => ch.cell === c).label}`).join(', ')).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette;
    const N = params.problems.length;
    const st = { problems: params.problems.map(() => ({ cells: { p: null, C: null, B: null } })) };
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], slots = {}, tray = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      tabs = params.problems.map((_, i) => ({ x: 12 + i * 52, y: 8, w: 44, h: 30 }));
      const cw = Math.min(118, (w - 60) / 2), ch = 44, cx = w / 2, cy = h * 0.47;
      slots = {
        // 24 px entre las dos filas: ahí va el rótulo de la casilla de arriba.
        100: { x: cx - cw - 8, y: cy - ch - 12, w: cw, h: ch },
        p: { x: cx + 8, y: cy - ch - 12, w: cw, h: ch },
        C: { x: cx - cw - 8, y: cy + 12, w: cw, h: ch },
        B: { x: cx + 8, y: cy + 12, w: cw, h: ch },
      };
      tray = [];
      const chips = params.problems[cur].chips, tw = 70, gap = 8;
      const x0 = (w - chips.length * tw - (chips.length - 1) * gap) / 2;
      chips.forEach((_, i) => tray.push({ x: x0 + i * (tw + gap), y: h - 78, w: tw, h: 36 }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const cellsOf = () => st.problems[cur].cells;
    const placedAt = i => CELLS.find(c => cellsOf()[c] === i);
    const ready = () => api.ready(st.problems.every(pr => CELLS.every(c => pr.cells[c] !== null)));

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function chip(x, y, w, h, label, col, fill) {
        // Casilla vacía: solo el borde (el punteado lo pone quien llama). Ficha: crema en la bandeja, color sol ya puesta.
        if (label === '') { p.stroke(col === C.line ? C.mute : col); p.strokeWeight(1.5); p.noFill(); p.rect(x, y, w, h, 10); return; }
        const f = col === C.ok || col === C.bad ? col : col === C.brand ? C.sun : C.cream;
        drawTile(p, C, { x, y, w, h }, label, { fill: f, lift: 2, size: 15 });
      }

      p.draw = () => {
        p.background(C.bg);
        const pr = params.problems[cur], cells = cellsOf();
        tabs.forEach((t, i) => {
          const done = CELLS.every(c => st.problems[i].cells[c] !== null);
          const good = CELLS.every(c => params.problems[i].chips[st.problems[i].cells[c]]?.cell === c);
          const col = locked ? (good ? C.ok : C.bad) : i === cur ? C.brand : done ? C.Z : C.line;   // respondida (no «correcta»): azul, no verde
          const plain = col === C.line;   // ficha de ronda, como las de drawTabs
          drawTile(p, C, t, i + 1, { fill: plain ? C.card : col, ink: plain ? C.mute : undefined, r: 8, lift: 0, size: 14, ring: i === cur ? C.sun : null });
        });
        p.noStroke(); p.fill(C.N); p.textAlign(p.LEFT, p.CENTER); p.textSize(14); p.textStyle(p.BOLD);
        p.text(pr.text, 12, 62, W - 24, 44);
        // Cruz: 100 fijo y tres casillas.
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.BOTTOM);
        p.text('de cada 100  →  del total C', W / 2, slots[100].y - 10);
        chip(slots[100].x, slots[100].y, slots[100].w, slots[100].h, '100', C.mute, C.card);
        CELLS.forEach(c => {
          const s = slots[c], i = cells[c];
          const good = i !== null && pr.chips[i].cell === c;
          const col = locked ? (good ? C.ok : C.bad) : i !== null ? C.brand : C.line;
          if (i === null) { p.drawingContext.setLineDash([5, 4]); chip(s.x, s.y, s.w, s.h, '', col, C.bg); p.drawingContext.setLineDash([]); }
          else chip(s.x, s.y, s.w, s.h, pr.chips[i].label, col, C.card);
          p.noStroke(); p.fill(i === null ? C.mute : col); p.textSize(11); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.NORMAL);
          p.text(`${c} · ${NAMES[c]}`, s.x + s.w / 2, s.y + s.h + 3);
        });
        p.stroke(C.line); p.strokeWeight(1.5);
        p.line(W / 2, slots[100].y - 2, W / 2, slots.B.y + slots.B.h + 2);
        // Bandeja.
        pr.chips.forEach((ch, i) => {
          if (placedAt(i) !== undefined || (drag && drag.i === i)) return;
          chip(tray[i].x, tray[i].y, tray[i].w, tray[i].h, ch.label, C.Z, C.card);
        });
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.NORMAL);
        p.text(locked ? grade(st, params).ok ? '¡Cruz armada!' : 'Mira la solución' : 'Arrastra cada ficha a su casilla; la «?» va en la incógnita', W / 2, H - 12);
        if (drag) chip(p.mouseX - 35, p.mouseY - 18, 70, 36, pr.chips[drag.i].label, C.brand, C.card);
      };

      p.mousePressed = () => {
        if (locked) return;
        const t = tabs.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; layout(W, H); api.sfx?.tap?.(); return false; }
        const cells = cellsOf();
        for (const c of CELLS) if (cells[c] !== null && inside(slots[c], p.mouseX, p.mouseY)) { drag = { i: cells[c] }; cells[c] = null; ready(); return false; }
        const i = tray.findIndex((b, i) => placedAt(i) === undefined && inside(b, p.mouseX, p.mouseY));
        if (i >= 0) { drag = { i }; return false; }
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const cells = cellsOf();
        const c = CELLS.find(c => inside(slots[c], p.mouseX, p.mouseY));
        if (c) { cells[c] = drag.i; api.sfx?.tap?.(); }  // la ficha que estaba vuelve sola a la bandeja
        drag = null;
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ problems: st.problems.map(pr => ({ cells: { ...pr.cells } })) }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/mezcla.js
// El químico (lección 1.3): un vaso con 40 g de alcohol al que se le añade agua con un grifo
// (de 10 en 10 g); un medidor muestra el % de alcohol de la mezcla en vivo. Hay que dejar la
// mezcla con el porcentaje pedido (ejercicio 1.12 del texto guía).
// params = { solute, target, step, max }   state = { water }

GAMES['mezcla'] = (() => {
  const pctOf = (p, water) => (p.solute / (p.solute + water)) * 100;
  const answerOf = p => (100 * p.solute) / p.target - p.solute;

  function grade(state, params) {
    const ok = Math.abs(pctOf(params, state.water) - params.target) < 1e-9;
    const total = (100 * params.solute) / params.target;
    return { ok, solution: `$\\dfrac{100 \\cdot ${params.solute}}{${params.target}} = ${total}$ g de mezcla, así que ${answerOf(params)} g de agua` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { water: 0 };
    let locked = false, W = 0, H = 0, beaker = null, gauge = null, buttons = [], timer = null;
    const WATER = '#5FB8FF', ALCOHOL = C.R;

    function layout(w, h) {
      W = w; H = h;
      beaker = { x: w * 0.1, y: 56, w: w * 0.42, h: h * 0.56 };
      gauge = { x: w * 0.68, y: 56, w: 26, h: h * 0.56 };
      buttons = [
        { d: params.step, x: beaker.x, y: beaker.y + beaker.h + 42, w: beaker.w / 2 - 4, h: 36, t: `+ ${params.step} g` },
        { d: -params.step, x: beaker.x + beaker.w / 2 + 4, y: beaker.y + beaker.h + 42, w: beaker.w / 2 - 4, h: 36, t: `− ${params.step} g` },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    function add(d) {
      st.water = Math.max(0, Math.min(params.max, st.water + d));
      api.ready(st.water > 0);
    }
    const stop = () => { if (timer) { clearInterval(timer); timer = null; } };

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const pct = pctOf(params, st.water), good = Math.abs(pct - params.target) < 1e-9;
        const col = locked ? (good ? C.ok : C.bad) : good ? C.ok : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`${params.solute} g de alcohol. Añade agua hasta que sea el ${params.target} % de la mezcla`, 12, 8, W - 24, 40);
        // Vaso: capa de alcohol y capa de agua (escala: max + solute = vaso lleno).
        const full = params.max + params.solute, unit = beaker.h / full;
        const hA = params.solute * unit, hW = st.water * unit, bottom = beaker.y + beaker.h;
        p.noStroke(); p.fill(ALCOHOL); p.rect(beaker.x, bottom - hA, beaker.w, hA);
        p.fill(WATER); p.rect(beaker.x, bottom - hA - hW, beaker.w, hW);
        p.stroke(C.ink); p.strokeWeight(3); p.noFill(); p.rect(beaker.x, beaker.y, beaker.w, beaker.h, 0, 0, 14, 14);
        for (let g = 100; g < full; g += 100) { const y = bottom - g * unit; p.strokeWeight(1); p.line(beaker.x, y, beaker.x + 10, y); }
        p.noStroke(); p.fill(C.ink); p.textSize(12); p.textAlign(p.LEFT, p.CENTER); p.textStyle(p.BOLD);
        p.text(`alcohol ${params.solute} g`, beaker.x + 14, bottom - hA / 2);
        if (st.water > 0) p.text(`agua ${st.water} g`, beaker.x + 14, bottom - hA - hW / 2);
        p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.NORMAL); p.textSize(11);
        p.text(`mezcla: ${params.solute + st.water} g`, beaker.x + beaker.w / 2, bottom + 8);
        // Grifo sobre el vaso.
        p.stroke(C.mute); p.strokeWeight(6); p.line(beaker.x + beaker.w / 2, beaker.y - 22, beaker.x + beaker.w / 2, beaker.y - 6);
        if (timer) { p.stroke(WATER); p.strokeWeight(4); p.line(beaker.x + beaker.w / 2, beaker.y - 4, beaker.x + beaker.w / 2, bottom - hA - hW); }
        // Medidor de % de alcohol.
        p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.rect(gauge.x, gauge.y, gauge.w, gauge.h, 8);
        const yOf = v => gauge.y + gauge.h - (v / 100) * gauge.h;
        p.noStroke(); p.fill(col); p.rect(gauge.x + 3, yOf(pct), gauge.w - 6, gauge.y + gauge.h - yOf(pct) - 3, 4);
        p.stroke(C.ok); p.strokeWeight(2); p.line(gauge.x - 8, yOf(params.target), gauge.x + gauge.w + 8, yOf(params.target));
        p.noStroke(); p.fill(C.ok); p.textSize(11); p.textAlign(p.LEFT, p.CENTER);
        // Si «meta 20 %» no cabe a la derecha del medidor, queda solo el número.
        const meta = `meta ${params.target} %`;
        p.text(gauge.x + gauge.w + 12 + p.textWidth(meta) > W - 4 ? `${params.target} %` : meta, gauge.x + gauge.w + 12, yOf(params.target));
        p.fill(col); p.textSize(20); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD);
        p.text(`${pct.toFixed(1)} %`, gauge.x + gauge.w / 2, gauge.y + gauge.h + 8);
        p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.text('de alcohol', gauge.x + gauge.w / 2, gauge.y + gauge.h + 32);
        [0, 50, 100].forEach(v => { p.fill(C.mute); p.textSize(10); p.textAlign(p.RIGHT, p.CENTER); p.text(v, gauge.x - 4, yOf(v)); });
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: locked ? C.card : C.sky, ink: locked ? C.mute : undefined, size: 14 });
        });
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `Hacían falta ${answerOf(params)} g de agua` : 'Toca o mantén el grifo para añadir agua', W / 2, H - 12);
      };

      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (!b) return;
        add(b.d); api.sfx?.tap?.();
        stop(); timer = setInterval(() => add(b.d), 140);
        return false;
      };
      p.mouseReleased = () => { if (!timer) return; stop(); return false; };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; stop(); },
      destroy: () => { stop(); m.remove(); },
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/rueda-porcentaje.js
// La rueda del porcentaje (lección 1.3): un pastel marcado en unidades del total (170, 180, 240)
// y una aguja que se gira; el sector sombreado dice cuántas unidades cubre y hay que dejarlo
// justo en la parte pedida para leer qué porcentaje es (ejercicios 1.9, 1.13 y 1.16).
// params = { rounds: [{ part, whole }], tol }   state = { pct: (número | null)[] }

GAMES['rueda-porcentaje'] = (() => {
  const answerOf = r => (100 * r.part) / r.whole;
  const fmt = n => String(+n.toFixed(1));

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => state.pct[i] !== null && Math.abs(state.pct[i] - answerOf(r)) <= params.tol);
    return { ok, solution: params.rounds.map(r => `${fmt(r.part)} de ${r.whole} = ${fmt(answerOf(r))} %`).join(', ') };
  }

  function create(host, params, api) {
    const C = api.palette;
    const N = params.rounds.length;
    const st = { pct: params.rounds.map(() => null) };
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], cx = 0, cy = 0, R = 0, drag = false;

    function layout(w, h) {
      W = w; H = h;
      tabs = params.rounds.map((_, i) => ({ x: 12 + i * ((w - 24) / N), y: 8, w: (w - 24) / N - 6, h: 34 }));
      R = Math.min(w, h) * 0.3; cx = w / 2; cy = 60 + R + 24;
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const angOf = pct => -Math.PI / 2 + (pct / 100) * Math.PI * 2;  // desde las 12, sentido horario
    function setFromPointer(x, y) {
      let a = Math.atan2(y - cy, x - cx) + Math.PI / 2;
      if (a < 0) a += Math.PI * 2;
      st.pct[cur] = Math.round((a / (Math.PI * 2)) * 1000) / 10;
      api.ready(st.pct.every(v => v !== null));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = params.rounds[cur], pct = st.pct[cur], ans = answerOf(r);
        tabs.forEach((t, i) => {
          const v = st.pct[i], good = v !== null && Math.abs(v - answerOf(params.rounds[i])) <= params.tol;
          const col = locked ? (good ? C.ok : C.bad) : i === cur ? C.brand : v !== null ? C.ok : C.line;
          p.stroke(col); p.strokeWeight(i === cur ? 2.5 : 1.5); p.fill(C.card); p.rect(t.x, t.y, t.w, t.h, 8);
          p.noStroke(); p.fill(C.ink); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(12);
          p.text(`${fmt(params.rounds[i].part)} de ${params.rounds[i].whole}`, t.x + t.w / 2, t.y + t.h / 2);
        });
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textSize(14); p.textStyle(p.BOLD);
        p.text(`¿Qué porcentaje es ${fmt(r.part)} de ${r.whole}?`, W / 2, 50);
        // Pastel y sector.
        p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.circle(cx, cy, R * 2);
        const good = pct !== null && Math.abs(pct - ans) <= params.tol;
        const col = locked ? (good ? C.ok : C.bad) : C.brand;
        if (pct !== null && pct > 0) {
          p.noStroke(); p.fill(locked ? col : C.sun);   // la parte cubierta, rellena
          p.arc(cx, cy, R * 2, R * 2, angOf(0), angOf(pct), p.PIE);
        }
        // Marcas en unidades (cada décimo del total) y anillo exterior en % (20 marcas, sin números).
        for (let k = 0; k < 10; k++) {
          const a = angOf(k * 10), x1 = cx + Math.cos(a) * (R - 8), y1 = cy + Math.sin(a) * (R - 8);
          p.stroke(C.mute); p.strokeWeight(1.5); p.line(x1, y1, cx + Math.cos(a) * R, cy + Math.sin(a) * R);
          p.noStroke(); p.fill(pct !== null && k * 10 < pct - 3 ? inkOn(locked ? col : C.sun, C.ink) : C.mute); p.textSize(10); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
          p.text(fmt((k * r.whole) / 10), cx + Math.cos(a) * (R - 22), cy + Math.sin(a) * (R - 22));
        }
        for (let k = 0; k < 20; k++) {
          const a = angOf(k * 5);
          p.stroke(locked ? col : C.line); p.strokeWeight(k % 2 ? 1 : 2);
          p.line(cx + Math.cos(a) * (R + 6), cy + Math.sin(a) * (R + 6), cx + Math.cos(a) * (R + (k % 2 ? 10 : 14)), cy + Math.sin(a) * (R + (k % 2 ? 10 : 14)));
          if (locked && k % 4 === 0) { p.noStroke(); p.fill(col); p.textSize(10); p.text(`${k * 5} %`, cx + Math.cos(a) * (R + 26), cy + Math.sin(a) * (R + 26)); }
        }
        // Aguja.
        const a = angOf(pct ?? 0);
        p.stroke(col); p.strokeWeight(4); p.line(cx, cy, cx + Math.cos(a) * (R + 2), cy + Math.sin(a) * (R + 2));
        p.noStroke(); p.fill(col); p.circle(cx + Math.cos(a) * (R + 2), cy + Math.sin(a) * (R + 2), 22); p.fill(C.ink); p.circle(cx, cy, 10);
        // Lectura: unidades cubiertas y, al bloquear, el porcentaje.
        p.fill(col); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(18);
        const units = pct === null ? null : (pct / 100) * r.whole;
        p.text(units === null ? 'gira la aguja' : `${fmt(units)} de ${r.whole}`, W / 2, cy + R + 30);
        if (locked) { p.textSize(14); p.text(`${fmt(pct ?? 0)} %  ·  correcto: ${fmt(ans)} %`, W / 2, cy + R + 56); }
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? 'El anillo exterior marca el porcentaje' : 'Arrastra la aguja hasta cubrir la parte pedida', W / 2, H - 12);
      };

      p.mousePressed = () => {
        if (locked) return;
        const t = tabs.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; api.sfx?.tap?.(); return false; }
        if (Math.hypot(p.mouseX - cx, p.mouseY - cy) <= R + 24) { drag = true; setFromPointer(p.mouseX, p.mouseY); return false; }
      };
      p.mouseDragged = () => { if (!drag) return; setFromPointer(p.mouseX, p.mouseY); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = false; api.sfx?.tap?.(); return false; };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ pct: [...st.pct] }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/bodegas.js
// Las bodegas de azúcar (lección 1.3, ejercicio 1.14): 2.000 sacos repartidos entre A y B con un
// divisor; al soltarlo, el 20 % de A viaja a B. Hay que repartirlos de modo que después del viaje
// las dos bodegas queden iguales.
// params = { total, move, step }   state = { a }

GAMES['bodegas'] = (() => {
  const after = (p, a) => ({ a: a - (a * p.move) / 100, b: p.total - a + (a * p.move) / 100 });
  const answerOf = p => p.total / (2 - (2 * p.move) / 100);
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const texNum = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');

  function grade(state, params) {
    const r = after(params, state.a);
    const ok = Math.abs(r.a - r.b) < 1e-9;
    const m = params.move / 100;
    return { ok, solution: `$x - ${m}x = ${texNum(params.total)} - x + ${m}x \\Rightarrow x = ${texNum(answerOf(params))}$ sacos en A` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { a: params.total / 2 };
    let locked = false, W = 0, H = 0, bar = null, boxA = null, boxB = null, drag = false, anim = 0, animFrom = 0;

    function layout(w, h) {
      W = w; H = h;
      bar = { x: 24, y: 64, w: w - 48, h: 28 };
      boxA = { x: 16, y: 130, w: w / 2 - 28, h: h * 0.42 };
      boxB = { x: w / 2 + 12, y: 130, w: w / 2 - 28, h: h * 0.42 };
    }
    const snap = v => Math.max(0, Math.min(params.total, Math.round(v / params.step) * params.step));
    function setA(v) {
      st.a = snap(v);
      api.ready(st.a !== params.total / 2);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function sack(x, y, s, col) {
        p.noStroke(); p.fill(col); p.rect(x, y, s, s * 0.9, s * 0.2);
        p.fill(C.bg + '55'); p.rect(x + s * 0.25, y - s * 0.12, s * 0.5, s * 0.18, s * 0.08);
      }
      // Pila de sacos: uno por cada 100 (y uno pequeño por el resto).
      function pile(box, n, col, name) {
        p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.rect(box.x, box.y, box.w, box.h, 12);
        p.noStroke(); p.fill(C.mute); p.textSize(12); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.TOP); p.text(name, box.x + box.w / 2, box.y + 8);
        const cols = 4, s = Math.min(22, (box.w - 16) / cols - 4);
        const full = Math.floor(n / 100), rest = n % 100;
        for (let i = 0; i < full; i++) sack(box.x + 8 + (i % cols) * (s + 4), box.y + box.h - 10 - s - Math.floor(i / cols) * (s + 3), s, col);
        if (rest > 0) sack(box.x + 8 + (full % cols) * (s + 4), box.y + box.h - 10 - s * (rest / 100) - Math.floor(full / cols) * (s + 3), s * Math.max(0.5, rest / 100), col + 'AA');
        p.fill(C.ink); p.textSize(14); p.textAlign(p.CENTER, p.TOP); p.text(`${fmt(n)} sacos`, box.x + box.w / 2, box.y + 26);
      }

      p.draw = () => {
        p.background(C.bg);
        const r = after(params, st.a), good = Math.abs(r.a - r.b) < 1e-9;
        const col = locked ? (good ? C.ok : C.bad) : good ? C.ok : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        p.text(`${fmt(params.total)} sacos. Si de A se lleva el ${params.move} % a B, quedan iguales. ¿Cuántos había en cada una?`, 12, 6, W - 24, 50);
        // Barra divisoria.
        const xOf = v => bar.x + (v / params.total) * bar.w;
        p.noStroke(); p.fill(C.sun); p.rect(bar.x, bar.y, xOf(st.a) - bar.x, bar.h, 8, 0, 0, 8);
        p.fill(C.sky); p.rect(xOf(st.a), bar.y, bar.x + bar.w - xOf(st.a), bar.h, 0, 8, 8, 0);
        p.stroke(C.ink); p.strokeWeight(3); p.line(xOf(st.a), bar.y - 6, xOf(st.a), bar.y + bar.h + 6);
        p.fill(C.cream); p.stroke(C.creamD); p.strokeWeight(3); p.circle(xOf(st.a), bar.y + bar.h / 2, 26);
        p.noStroke(); p.fill(C.ink); p.textSize(11); p.textAlign(p.LEFT, p.CENTER); p.textStyle(p.BOLD); p.text(`A: ${fmt(st.a)}`, bar.x + 6, bar.y + bar.h + 16);
        p.textAlign(p.RIGHT, p.CENTER); p.text(`B: ${fmt(params.total - st.a)}`, bar.x + bar.w - 6, bar.y + bar.h + 16);
        // Bodegas con el reparto actual; sacos viajando durante la animación.
        const t = anim > 0 ? 1 - anim / 36 : 1;
        const moving = (st.a * params.move) / 100;
        pile(boxA, Math.round(st.a - moving * t), C.sun, 'Bodega A');
        pile(boxB, Math.round(params.total - st.a + moving * t), C.sky, 'Bodega B');
        if (anim > 0) {
          anim--;
          for (let i = 0; i < 3; i++) {
            const k = Math.min(1, Math.max(0, t * 1.4 - i * 0.15));
            sack(boxA.x + boxA.w - 10 + (boxB.x + 10 - boxA.x - boxA.w + 10) * k, boxA.y + boxA.h * 0.5 - Math.sin(k * Math.PI) * 40 + i * 14, 14, C.sun);
          }
        }
        p.stroke(C.mute); p.strokeWeight(2); p.line(boxA.x + boxA.w + 4, boxA.y + boxA.h * 0.5, boxB.x - 4, boxA.y + boxA.h * 0.5);
        p.noStroke(); p.fill(C.mute); p.textSize(10); p.textAlign(p.CENTER, p.BOTTOM); p.text(`${params.move} %`, W / 2, boxA.y + boxA.h * 0.5 - 4);
        // Totales después del viaje.
        const y0 = boxA.y + boxA.h + 16;
        p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.NORMAL); p.text('después del viaje', W / 2, y0);
        p.fill(col); p.textSize(18); p.textStyle(p.BOLD);
        drawPill(p, C, `A ${fmt(r.a)}   ${good ? '=' : '≠'}   B ${fmt(r.b)}`, W / 2, y0 + 28, col, 16);
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `Debían ser ${fmt(answerOf(params))} en A y ${fmt(params.total - answerOf(params))} en B` : 'Arrastra el divisor y suelta para ver el viaje', W / 2, H - 12);
      };

      p.mousePressed = () => {
        if (locked) return;
        if (p.mouseY >= bar.y - 16 && p.mouseY <= bar.y + bar.h + 16) { drag = true; setA(((p.mouseX - bar.x) / bar.w) * params.total); return false; }
      };
      p.mouseDragged = () => { if (!drag) return; setA(((p.mouseX - bar.x) / bar.w) * params.total); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = false; anim = 36; api.sfx?.tap?.(); return false; };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cascada.js
// Descuentos en cascada (lección 1.3, ejercicio 1.10): una etiqueta de precio a la que se le pegan
// stickers de descuento en cualquier orden (el precio cae con cada uno) y un deslizador para fijar
// el descuento único equivalente: los descuentos sucesivos se multiplican, no se suman.
// params = { price, changes, step }   state = { applied: índices[], single: % | null }

GAMES['cascada'] = (() => {
  const factor = p => p.changes.reduce((f, c) => f * (1 + c / 100), 1);
  const answerOf = p => Math.round(100 * (1 - factor(p)));
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const dec = n => String(+n.toFixed(2));

  function grade(state, params) {
    const all = params.changes.every((_, i) => state.applied.filter(j => j === i).length === 1) && state.applied.length === params.changes.length;
    const ok = all && state.single === answerOf(params);
    const prod = params.changes.map(c => dec(1 + c / 100)).join(' \\cdot ');
    const sum = -params.changes.reduce((s, c) => s + c, 0);   // lo que daría sumar los cambios con su signo
    return { ok, solution: `$${prod} = ${dec(factor(params))} \\Rightarrow ${answerOf(params)}\\%$ (no ${sum} %)` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const COLS = [C.I, C.N, C.Q, C.R];
    const st = { applied: [], single: null };
    let locked = false, W = 0, H = 0, tag = null, tray = [], slider = null, drag = null, shown = params.price;

    function layout(w, h) {
      W = w; H = h;
      tag = { x: w * 0.16, y: 48, w: w * 0.68, h: h * 0.3 };
      tray = params.changes.map((_, i) => ({ x: w / 2 - 36 + (i - (params.changes.length - 1) / 2) * 90, y: tag.y + tag.h + 20, w: 72, h: 72 }));
      slider = { x: 32, y: h - 70, w: w - 64 };
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const priceNow = () => st.applied.reduce((v, i) => v * (1 + params.changes[i] / 100), params.price);
    const ready = () => api.ready(st.applied.length === params.changes.length && st.single !== null);
    function setSingle(x) {
      st.single = Math.max(0, Math.min(100, Math.round(((x - slider.x) / slider.w) * 100 / params.step) * params.step));
      ready();
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function sticker(x, y, s, i) {
        p.stroke(C.card); p.strokeWeight(3); p.fill(COLS[i % COLS.length]); p.circle(x, y, s);
        p.noStroke(); p.fill(inkOn(COLS[i % COLS.length])); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(s * 0.26);
        p.text(`${params.changes[i] > 0 ? '+' : '−'}${Math.abs(params.changes[i])} %`, x, y);
      }

      p.draw = () => {
        p.background(C.bg);
        const target = priceNow();
        shown += (target - shown) * 0.12;   // el precio cae contando hacia abajo
        if (Math.abs(target - shown) < 1) shown = target;
        const ans = answerOf(params), good = st.single === ans;
        const col = locked ? (good && st.applied.length === params.changes.length ? C.ok : C.bad) : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(params.changes.every(c => c < 0) ? 'Pega los dos descuentos y halla el descuento único' : 'Pega los dos cambios y halla el descuento único', 12, 8, W - 24, 40);
        // Etiqueta.
        p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.rect(tag.x, tag.y, tag.w, tag.h, 16);
        p.noStroke(); p.fill(C.line); p.circle(tag.x + tag.w / 2, tag.y + 14, 12);
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.text('precio', tag.x + tag.w / 2, tag.y + 26);
        let y = tag.y + 44;
        let v = params.price;
        st.applied.forEach(i => {
          p.fill(C.mute); p.textSize(13); p.textAlign(p.CENTER, p.TOP); p.text(`$ ${fmt(v)}`, tag.x + tag.w / 2, y);
          p.stroke(C.bad); p.strokeWeight(1.5); p.line(tag.x + tag.w / 2 - 34, y + 8, tag.x + tag.w / 2 + 34, y + 8); p.noStroke();
          v *= 1 + params.changes[i] / 100; y += 18;
        });
        p.fill(C.ink); p.textSize(26); p.textStyle(p.BOLD); p.text(`$ ${fmt(shown)}`, tag.x + tag.w / 2, y + 4);
        st.applied.forEach((i, k) => sticker(tag.x + 24 + k * 34, tag.y + 24, 40, i));
        // Bandeja de stickers.
        params.changes.forEach((_, i) => {
          if (st.applied.includes(i) || drag?.i === i) return;
          sticker(tray[i].x + tray[i].w / 2, tray[i].y + tray[i].h / 2, 64, i);
        });
        // Deslizador del descuento único.
        const xOf = s => slider.x + (s / 100) * slider.w;
        p.fill(C.mute); p.textSize(12); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.BOTTOM); p.text('descuento único', slider.x, slider.y - 14);
        p.textAlign(p.RIGHT, p.BOTTOM); p.fill(col); p.textSize(16);
        p.text(st.single === null ? '— %' : `${st.single} %  →  $ ${fmt(params.price * (1 - st.single / 100))}`, slider.x + slider.w, slider.y - 12);
        p.stroke(C.mute); p.strokeWeight(6); p.line(slider.x, slider.y, slider.x + slider.w, slider.y);
        if (st.single !== null) { p.stroke(col); p.line(slider.x, slider.y, xOf(st.single), slider.y); }
        p.fill(C.cream); p.stroke(col); p.strokeWeight(3); p.circle(xOf(st.single ?? 0), slider.y, 26);
        if (locked) { p.noStroke(); p.fill(C.ok); p.textSize(11); p.textAlign(p.CENTER, p.TOP); p.text(`${ans} %`, xOf(ans), slider.y + 16); p.stroke(C.ok); p.strokeWeight(2); p.line(xOf(ans), slider.y - 10, xOf(ans), slider.y + 10); }
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `El descuento único era ${ans} %` : 'Arrastra los stickers a la etiqueta; luego el deslizador', W / 2, H - 12);
        if (drag && !drag.slider) sticker(p.mouseX, p.mouseY, 64, drag.i);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = tray.findIndex((b, i) => !st.applied.includes(i) && inside(b, p.mouseX, p.mouseY));
        if (i >= 0) { drag = { i }; return false; }
        if (Math.abs(p.mouseY - slider.y) <= 22 && p.mouseX >= slider.x - 16 && p.mouseX <= slider.x + slider.w + 16) { drag = { slider: true }; setSingle(p.mouseX); return false; }
      };
      p.mouseDragged = () => { if (!drag) return; if (drag.slider) setSingle(p.mouseX); return false; };
      p.mouseReleased = () => {
        if (!drag) return;
        if (!drag.slider && inside(tag, p.mouseX, p.mouseY)) { st.applied.push(drag.i); api.sfx?.tap?.(); ready(); }
        drag = null;
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ applied: [...st.applied], single: st.single }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/rebote.js
// Sube y baja (lección 1.3, ejercicio 1.6): un precio baja un 10 %; se arrastra el «% de subida»
// y la barra responde en vivo. Hay que volver exactamente al precio original: la subida se calcula
// sobre el precio rebajado, así que no basta con un 10 %.
// params = { base, drop, max, step, tol }   state = { up: % | null }

GAMES['rebote'] = (() => {
  const answerOf = p => (100 * p.drop) / (100 - p.drop);
  const fmt1 = n => String(+n.toFixed(1));
  const tex1 = n => String(+n.toFixed(1));
  // Pasos exactos de `step` (los botones ±): con la manija sola, 0,83 px por paso no garantiza 11,1.
  const stepUp = (v, d, p) => +Math.max(0, Math.min(p.max, Math.round(((v ?? 0) + d * p.step) / p.step) * p.step)).toFixed(1);

  function grade(state, params) {
    const ok = state.up !== null && Math.abs(state.up - answerOf(params)) <= params.tol;
    return { ok, solution: `$\\dfrac{${params.drop}}{${100 - params.drop}} = ${tex1(answerOf(params))}\\%$: se sube sobre ${100 - params.drop}, no sobre ${params.base}` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { up: null };
    const low = params.base * (1 - params.drop / 100);
    let locked = false, W = 0, H = 0, bars = [], rail = null, buttons = [], drag = false;

    function layout(w, h) {
      W = w; H = h;
      const bw = Math.min(64, (w * 0.6) / 3 - 10), x0 = 24;
      bars = [0, 1, 2].map(i => ({ x: x0 + i * (bw + 14), w: bw }));
      rail = { x: w - 56, y: 90, h: h * 0.5 };   // deja sitio a los botones y a la ayuda de dos renglones
      buttons = [
        { d: -1, x: w - 100, y: rail.y + rail.h + 22, w: 40, h: 32, t: '−' },
        { d: 1, x: w - 54, y: rail.y + rail.h + 22, w: 40, h: 32, t: '+' },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const top = 90, floor = () => top + rail.h;
    const yOf = v => floor() - (v / (params.base * 1.15)) * rail.h;
    const upOf = () => (st.up === null ? 0 : st.up);
    function setUp(y) {
      const v = ((rail.y + rail.h - y) / rail.h) * params.max;
      st.up = Math.max(0, Math.min(params.max, Math.round(v / params.step) * params.step));
      st.up = +st.up.toFixed(1);
      api.ready(true);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function bar(b, v, col, name, extra) {
        p.noStroke(); p.fill(col); p.rect(b.x, yOf(v), b.w, floor() - yOf(v), 6, 6, 0, 0);
        p.fill(C.ink); p.textAlign(p.CENTER, p.BOTTOM); p.textStyle(p.BOLD); p.textSize(13); p.text(fmt1(v), b.x + b.w / 2, yOf(v) - 4);
        p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textSize(10); p.textStyle(p.NORMAL); p.text(name, b.x + b.w / 2, floor() + 6);
        if (extra) p.text(extra, b.x + b.w / 2, floor() + 19);
      }

      p.draw = () => {
        p.background(C.bg);
        const now = low * (1 + upOf() / 100), ans = answerOf(params);
        const good = st.up !== null && Math.abs(st.up - ans) <= params.tol;
        const col = locked ? (good ? C.ok : C.bad) : good ? C.ok : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`El precio bajó ${params.drop} %. ¿Qué % hay que subirlo para volver al original?`, 12, 8, W - 24, 44);
        p.stroke(C.line); p.strokeWeight(1); p.line(16, floor(), rail.x - 24, floor());
        // Línea del precio original cruzando las tres barras.
        p.drawingContext.setLineDash([5, 4]); p.stroke(C.ok); p.strokeWeight(1.5); p.line(16, yOf(params.base), rail.x - 24, yOf(params.base)); p.drawingContext.setLineDash([]);
        bar(bars[0], params.base, C.mute, 'original');
        bar(bars[1], low, C.coral, 'rebajado', `−${params.drop} %`);
        bar(bars[2], now, col, 'nuevo', st.up === null ? '' : `+${fmt1(st.up)} %`);
        // Manija vertical del % de subida.
        p.stroke(C.mute); p.strokeWeight(6); p.line(rail.x, rail.y, rail.x, rail.y + rail.h);
        const hy = rail.y + rail.h - (upOf() / params.max) * rail.h;
        if (st.up !== null) { p.stroke(col); p.line(rail.x, hy, rail.x, rail.y + rail.h); }
        p.fill(C.cream); p.stroke(col); p.strokeWeight(3); p.circle(rail.x, hy, 28);
        p.noStroke(); p.fill(col); p.textAlign(p.CENTER, p.BOTTOM); p.textStyle(p.BOLD); p.textSize(15);
        p.text(st.up === null ? '— %' : `${fmt1(st.up)} %`, rail.x, rail.y - 8);
        p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.text(`% de subida (0 a ${params.max})`, rail.x, rail.y - 26);
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: locked ? C.card : C.sky, ink: locked ? C.mute : undefined, r: 8, lift: 2, size: 18 });
        });
        if (locked) { const ay = rail.y + rail.h - (ans / params.max) * rail.h; p.stroke(C.ok); p.strokeWeight(2); p.line(rail.x - 14, ay, rail.x + 14, ay); }
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `Hacía falta subir ${fmt1(ans)} %` : 'Arrastra la manija o toca ± hasta que «nuevo» llegue a la línea', 12, H - 30, W - 24, 28);
      };

      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { st.up = stepUp(st.up, b.d, params); api.ready(true); api.sfx?.tap?.(); return false; }
        if (Math.abs(p.mouseX - rail.x) <= 30 && p.mouseY >= rail.y - 20 && p.mouseY <= rail.y + rail.h + 20) { drag = true; setUp(p.mouseY); return false; }
      };
      p.mouseDragged = () => { if (!drag) return; setUp(p.mouseY); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = false; api.sfx?.tap?.(); return false; };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, stepUp };
})();
;
//#archivo js/games/dos-etapas.js
// La máquina de dos etapas (lección 1.3, ejercicio 1.19): una cantidad entra, sube un 30 % y luego
// baja un 20 %; la salida es conocida. Con una perilla se fija la entrada y la máquina recalcula
// las etapas en vivo. Hay que dar con la entrada que produce exactamente esa salida.
// params = { changes, output, max, step }   state = { input: número | null }

GAMES['dos-etapas'] = (() => {
  const factor = p => p.changes.reduce((f, c) => f * (1 + c / 100), 1);
  const answerOf = p => Math.round(p.output / factor(p));
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const texNum = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');
  const dec = n => String(+n.toFixed(2));
  // Salto corto entre dos ángulos de atan2 (en (−π, π]), para acumular vueltas sin saltos de 2π.
  const turnDelta = (a0, a1) => Math.atan2(Math.sin(a1 - a0), Math.cos(a1 - a0));

  function grade(state, params) {
    const ok = state.input !== null && Math.round(state.input * factor(params)) === params.output;
    const prod = params.changes.map(c => dec(1 + c / 100)).join(' \\cdot ');
    return { ok, solution: `$${prod} = ${dec(factor(params))} \\Rightarrow x = \\dfrac{${texNum(params.output)}}{${dec(factor(params))}} = ${texNum(answerOf(params))}$` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { input: null };
    const TURN = 2000;   // una vuelta completa de la perilla
    let locked = false, W = 0, H = 0, knob = null, boxes = [], buttons = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      knob = { x: w * 0.26, y: h * 0.5, r: Math.min(w * 0.17, 60) };
      const bx = w * 0.52, bw = w * 0.44, bh = 44, gap = 22;
      const names = ['entrada', ...params.changes.map(c => `${c > 0 ? '+' : '−'}${Math.abs(c)} %`), 'salida'];
      boxes = names.map((t, i) => ({ t, x: bx, y: 64 + i * (bh + gap), w: bw, h: bh }));
      buttons = [
        { d: -params.step, x: knob.x - knob.r - 4, y: knob.y + knob.r + 16, w: knob.r - 2, h: 32, t: `−${params.step}` },
        { d: params.step, x: knob.x + 6, y: knob.y + knob.r + 16, w: knob.r - 2, h: 32, t: `+${params.step}` },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const valueOf = () => (st.input === null ? 0 : st.input);
    function setInput(v) {
      st.input = Math.max(0, Math.min(params.max, Math.round(v / params.step) * params.step));
      api.ready(true);
    }
    const stages = () => {
      const out = [valueOf()];
      params.changes.forEach(c => out.push(out[out.length - 1] * (1 + c / 100)));
      return out;
    };

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const vals = stages(), out = vals[vals.length - 1];
        const good = st.input !== null && Math.round(out) === params.output;
        const col = locked ? (good ? C.ok : C.bad) : good ? C.ok : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        p.text(`Subió ${params.changes[0]} % y luego bajó ${Math.abs(params.changes[1])} %; terminó en ${fmt(params.output)}. ¿Cuánto valía al principio?`, 12, 6, W - 24, 50);
        // Perilla.
        const ang = (valueOf() / TURN) * Math.PI * 2 - Math.PI / 2;
        // Perilla: disco color sol con relieve y aguja azul noche.
        p.noStroke(); p.fill(shade(C.sun, 0.74)); p.circle(knob.x, knob.y + 4, knob.r * 2); p.fill(C.sun); p.circle(knob.x, knob.y, knob.r * 2);
        for (let k = 0; k < 12; k++) { const a = (k / 12) * Math.PI * 2; p.stroke(C.mute); p.strokeWeight(1.5); p.line(knob.x + Math.cos(a) * (knob.r + 4), knob.y + Math.sin(a) * (knob.r + 4), knob.x + Math.cos(a) * (knob.r + 9), knob.y + Math.sin(a) * (knob.r + 9)); }
        p.stroke(C.night); p.strokeWeight(5); p.line(knob.x, knob.y, knob.x + Math.cos(ang) * (knob.r - 10), knob.y + Math.sin(ang) * (knob.r - 10));
        p.noStroke(); p.fill(C.night); p.circle(knob.x, knob.y, 10);
        p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.TOP); p.text(`una vuelta = ${fmt(TURN)}`, knob.x, knob.y - knob.r - 22);
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: C.sky, r: 8, lift: 2, size: 12 });
        });
        // Máquina: cajas en columna con flechas.
        boxes.forEach((b, i) => {
          const last = i === boxes.length - 1;
          const bc = last ? col : i === 0 ? C.brand : C.line;
          p.stroke(bc); p.strokeWeight(2); p.fill(C.card); p.rect(b.x, b.y, b.w, b.h, 10);
          p.noStroke(); p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.textAlign(p.LEFT, p.TOP); p.text(b.t, b.x + 8, b.y + 4);
          p.fill(C.ink); p.textSize(15); p.textStyle(p.BOLD); p.textAlign(p.RIGHT, p.BOTTOM);
          const v = last ? params.output : vals[i];
          p.text(st.input === null && i < boxes.length - 1 ? '—' : fmt(v), b.x + b.w - 8, b.y + b.h - 4);
          if (!last) { p.stroke(C.mute); p.strokeWeight(2); p.line(b.x + b.w / 2, b.y + b.h + 2, b.x + b.w / 2, b.y + b.h + 18); p.line(b.x + b.w / 2 - 5, b.y + b.h + 12, b.x + b.w / 2, b.y + b.h + 18); p.line(b.x + b.w / 2 + 5, b.y + b.h + 12, b.x + b.w / 2, b.y + b.h + 18); }
        });
        // Semáforo: la salida calculada frente a la esperada.
        const sb = boxes[boxes.length - 1];
        p.noStroke(); p.fill(col); p.circle(sb.x + sb.w - 10, sb.y - 8, 14);
        p.fill(col); p.textSize(11); p.textStyle(p.BOLD); p.textAlign(p.RIGHT, p.BOTTOM);
        p.text(st.input === null ? '' : good ? '¡coincide!' : `sale ${fmt(out)}`, sb.x + sb.w - 20, sb.y - 2);
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `La entrada era ${fmt(answerOf(params))}` : 'Gira la perilla (o toca ±) hasta que la salida coincida', W / 2, H - 12);
      };

      const angleAt = (x, y) => Math.atan2(y - knob.y, x - knob.x);
      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { setInput(valueOf() + b.d); api.sfx?.tap?.(); return false; }
        if (Math.hypot(p.mouseX - knob.x, p.mouseY - knob.y) <= knob.r + 14) { drag = { a: angleAt(p.mouseX, p.mouseY), v: valueOf() }; return false; }
      };
      p.mouseDragged = () => {
        if (!drag) return;
        const a = angleAt(p.mouseX, p.mouseY), d = turnDelta(drag.a, a);
        drag.a = a; drag.v += (d / (Math.PI * 2)) * TURN;
        drag.v = Math.max(0, Math.min(params.max, drag.v));
        setInput(drag.v);
        return false;
      };
      p.mouseReleased = () => { if (!drag) return; drag = null; api.sfx?.tap?.(); return false; };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, turnDelta };
})();
;
//#archivo js/games/carrera-interes.js
// La carrera del interés (lección 1.3): dos corredores, uno con interés simple y otro con
// compuesto, parten del mismo capital; un deslizador de tiempo los mueve y un medidor muestra la
// ventaja del compuesto. Hay que encontrar el primer mes en que esa ventaja supera la brecha.
// params = { capital, rate, months, gap }   state = { month: número | null }

GAMES['carrera-interes'] = (() => {
  const simple = (p, n) => p.capital * (1 + p.rate * n);
  const compound = (p, n) => p.capital * (1 + p.rate) ** n;
  const gapAt = (p, n) => compound(p, n) - simple(p, n);
  const firstMonth = p => { for (let n = 1; n <= p.months; n++) if (gapAt(p, n) > p.gap) return n; return null; };
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const texNum = n => String(Math.round(n / 100) * 100).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');

  function grade(state, params) {
    const ans = firstMonth(params);
    const ok = state.month !== null && state.month === ans;
    return { ok, solution: `En el mes ${ans} la ventaja es $\\approx ${texNum(gapAt(params, ans))}$ (en el ${ans - 1}, $\\approx ${texNum(gapAt(params, ans - 1))}$)` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { month: null };
    let locked = false, W = 0, H = 0, track = null, slider = null, drag = false;

    function layout(w, h) {
      W = w; H = h;
      track = { x: 24, y: 96, w: w - 48, lane: 54 };
      slider = { x: 32, y: h - 64, w: w - 64 };
    }
    const month = () => (st.month === null ? 0 : st.month);
    function setMonth(x) {
      st.month = Math.max(0, Math.min(params.months, Math.round(((x - slider.x) / slider.w) * params.months)));
      api.ready(st.month > 0);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function runner(x, y, col, lean) {
        p.noStroke(); p.fill(col); p.circle(x, y - 18, 12);
        p.stroke(col); p.strokeWeight(4); p.line(x, y - 12, x + lean * 2, y + 2);
        p.line(x + lean * 2, y + 2, x - 6, y + 14); p.line(x + lean * 2, y + 2, x + 8, y + 12);
        p.line(x - 2, y - 6, x - 10 - lean * 2, y); p.line(x - 2, y - 6, x + 10, y - 10 + lean);
      }

      p.draw = () => {
        p.background(C.bg);
        const n = month(), ans = firstMonth(params);
        const s = simple(params, n), c = compound(params, n), gap = c - s;
        const beyond = gap > params.gap;
        const good = st.month === ans;
        const col = locked ? (good ? C.ok : C.bad) : beyond ? C.ok : C.brand;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        p.text(`$ ${fmt(params.capital)} al ${(params.rate * 100).toLocaleString('es-CO')} % mensual. ¿Desde qué mes el compuesto le saca más de $ ${fmt(params.gap)} al simple?`, 12, 6, W - 24, 50);
        // Pista: dos carriles; la posición es el monto entre el capital y el máximo del compuesto.
        const maxV = compound(params, params.months);
        const mx = lineMap(params.capital, maxV, track.x + 10, track.x + track.w - 20);
        [['simple', s, C.N, 0], ['compuesto', c, C.Q, 1]].forEach(([name, v, color, k]) => {
          const y = track.y + k * track.lane;
          p.stroke(C.line); p.strokeWeight(1.5); p.line(track.x, y + 20, track.x + track.w, y + 20);
          p.drawingContext.setLineDash([3, 5]); p.stroke(C.line); p.line(track.x, y - 22, track.x + track.w, y - 22); p.drawingContext.setLineDash([]);
          runner(mx.toPx(v), y + 4, color, Math.min(6, n / 3));
          p.noStroke(); p.fill(color); p.textAlign(p.LEFT, p.BOTTOM); p.textSize(11); p.textStyle(p.BOLD); p.text(name, track.x + 2, y - 24);
          p.fill(C.ink); p.textAlign(p.RIGHT, p.BOTTOM); p.text(`$ ${fmt(v)}`, track.x + track.w - 2, y - 24);
        });
        p.stroke(C.mute); p.strokeWeight(2); p.line(track.x + track.w - 8, track.y - 26, track.x + track.w - 8, track.y + track.lane + 22);
        // Medidor de la ventaja.
        const gy = track.y + track.lane * 2 + 10, gh = 28;
        p.noStroke(); p.fill(C.mute); p.textAlign(p.LEFT, p.BOTTOM); p.textSize(11); p.textStyle(p.NORMAL); p.text('ventaja del compuesto', track.x, gy - 4);
        p.fill(col); p.textAlign(p.RIGHT, p.BOTTOM); p.textStyle(p.BOLD); p.textSize(14); p.text(`$ ${fmt(gap)}`, track.x + track.w, gy - 2);
        p.stroke(C.line); p.strokeWeight(2); p.fill(C.card); p.rect(track.x, gy, track.w, gh, 8);
        const gmax = params.gap * 2.4, gx = lineMap(0, gmax, track.x + 3, track.x + track.w - 3);
        p.noStroke(); p.fill(col); p.rect(track.x + 3, gy + 3, Math.max(0, gx.toPx(Math.min(gap, gmax)) - track.x - 3), gh - 6, 6);
        p.stroke(C.ok); p.strokeWeight(2); p.line(gx.toPx(params.gap), gy - 6, gx.toPx(params.gap), gy + gh + 6);
        p.noStroke(); p.fill(C.ok); p.textSize(10); p.textAlign(p.CENTER, p.TOP); p.text(`$ ${fmt(params.gap)}`, gx.toPx(params.gap), gy + gh + 8);
        // Deslizador de meses.
        const xOf = k => slider.x + (k / params.months) * slider.w;
        p.stroke(C.line); p.strokeWeight(6); p.line(slider.x, slider.y, slider.x + slider.w, slider.y);
        p.stroke(col); p.line(slider.x, slider.y, xOf(n), slider.y);
        for (let k = 0; k <= params.months; k += 6) { p.stroke(C.mute); p.strokeWeight(1.5); p.line(xOf(k), slider.y + 8, xOf(k), slider.y + 14); p.noStroke(); p.fill(C.mute); p.textSize(10); p.textAlign(p.CENTER, p.TOP); p.text(k, xOf(k), slider.y + 16); }
        if (locked) { p.stroke(C.ok); p.strokeWeight(2); p.line(xOf(ans), slider.y - 12, xOf(ans), slider.y + 12); }
        p.fill(C.card); p.stroke(col); p.strokeWeight(3); p.circle(xOf(n), slider.y, 26);
        p.noStroke(); p.fill(col); p.textSize(16); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.BOTTOM);
        p.text(st.month === null ? 'mes —' : `mes ${st.month}`, W / 2, slider.y - 16);
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked && !good ? `Era el mes ${ans}` : 'Desliza el tiempo y deja el primer mes que supere la brecha', W / 2, H - 12);
      };

      p.mousePressed = () => {
        if (locked) return;
        if (Math.abs(p.mouseY - slider.y) <= 24 && p.mouseX >= slider.x - 16 && p.mouseX <= slider.x + slider.w + 16) { drag = true; setMonth(p.mouseX); return false; }
      };
      p.mouseDragged = () => { if (!drag) return; setMonth(p.mouseX); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = false; api.sfx?.tap?.(); return false; };
    }, 1.15);

    return {
      loaded: m.ready,
      getState: () => ({ ...st }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/une-factor.js
// Une cada cambio con su factor (lección 1.3): a la izquierda, cambios porcentuales (+25 %, −5 %…);
// a la derecha, factores multiplicativos (×1.25, ×0.95…) con algún distractor. Se arrastra desde
// un cambio hasta un factor para tender la cuerda; un factor solo puede tener una cuerda (la nueva
// le quita la vieja al otro cambio) y arrastrar desde un cambio ya unido lo suelta.
// params = { changes: [%], factors: [número] }   state = { links: [índice de factor | null] }

GAMES['une-factor'] = (() => {
  const factorOf = c => 1 + c / 100;
  const same = (a, b) => Math.abs(a - b) < 1e-9;
  const pct = c => `${c > 0 ? '+' : '−'}${Math.abs(c)} %`;
  const fac = f => `×${f}`;

  function grade(state, params) {
    const ok = params.changes.every((c, i) => {
      const j = state.links[i];
      return j != null && params.factors[j] !== undefined && same(params.factors[j], factorOf(c));
    });
    const solution = params.changes.map(c => `${pct(c)} → ${fac(factorOf(c))}`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette;
    const COLS = [C.N, C.Z, C.Q, C.I, C.R, C.brand];
    const st = { links: params.changes.map(() => null) };
    let locked = false, W = 0, H = 0, left = [], right = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      const n = Math.max(params.changes.length, params.factors.length);
      const top = 50, rowH = (h - top - 36) / n, ph = Math.min(40, rowH - 10), pw = Math.min(118, w * 0.34);
      const rowY = (k, count) => top + (k + 0.5) * rowH + ((n - count) * rowH) / 2 - ph / 2;
      left = params.changes.map((_, i) => ({ x: 14, y: rowY(i, params.changes.length), w: pw, h: ph }));
      right = params.factors.map((_, j) => ({ x: w - 14 - pw, y: rowY(j, params.factors.length), w: pw, h: ph }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const ready = () => api.ready(st.links.every(j => j !== null));
    const linkedBy = j => st.links.indexOf(j);

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function pill(b, label, col, strong) {
        p.stroke(col); p.strokeWeight(strong ? 2.5 : 1.5); p.fill(C.card); p.rect(b.x, b.y, b.w, b.h, b.h / 2);
        p.noStroke(); p.fill(C.ink); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(15);
        p.text(label, b.x + b.w / 2, b.y + b.h / 2);
      }
      function rope(x0, y0, x1, y1, col) {
        p.stroke(col); p.strokeWeight(3); p.noFill();
        p.bezier(x0, y0, x0 + (x1 - x0) * 0.45, y0, x1 - (x1 - x0) * 0.45, y1, x1, y1);
        p.noStroke(); p.fill(col); p.circle(x0, y0, 9); p.circle(x1, y1, 9);
      }

      p.draw = () => {
        p.background(C.bg);
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text('Une cada cambio con el factor por el que multiplica', 12, 8, W - 24, 40);
        // Cuerdas tendidas.
        st.links.forEach((j, i) => {
          if (j === null) return;
          const good = same(params.factors[j], factorOf(params.changes[i]));
          const col = locked ? (good ? C.ok : C.bad) : COLS[i % COLS.length];
          rope(left[i].x + left[i].w, left[i].y + left[i].h / 2, right[j].x, right[j].y + right[j].h / 2, col);
        });
        if (locked) st.links.forEach((j, i) => {   // la cuerda que faltaba o estaba mal, en verde punteado
          const k = params.factors.findIndex(f => same(f, factorOf(params.changes[i])));
          if (k < 0 || (j !== null && same(params.factors[j], factorOf(params.changes[i])))) return;
          p.drawingContext.setLineDash([6, 5]);
          rope(left[i].x + left[i].w, left[i].y + left[i].h / 2, right[k].x, right[k].y + right[k].h / 2, C.ok);
          p.drawingContext.setLineDash([]);
        });
        if (drag) rope(left[drag.i].x + left[drag.i].w, left[drag.i].y + left[drag.i].h / 2, p.mouseX, p.mouseY, COLS[drag.i % COLS.length]);
        // Pastillas.
        params.changes.forEach((c, i) => {
          const j = st.links[i], good = j !== null && same(params.factors[j], factorOf(c));
          const col = locked ? (good ? C.ok : C.bad) : j !== null || (drag && drag.i === i) ? COLS[i % COLS.length] : C.line;
          pill(left[i], pct(c), col, j !== null);
        });
        params.factors.forEach((f, j) => {
          const i = linkedBy(j);
          const col = i >= 0 ? (locked ? (same(f, factorOf(params.changes[i])) ? C.ok : C.bad) : COLS[i % COLS.length]) : C.line;
          pill(right[j], fac(f), col, i >= 0);
        });
        const extra = params.factors.length - params.changes.length;
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? (grade(st, params).ok ? '¡Todas las cuerdas en su sitio!' : 'Mira las cuerdas verdes') : `Arrastra desde un cambio hasta su factor${extra > 0 ? ` · sobra${extra > 1 ? 'n' : ''} ${extra}` : ''}`, 12, H - 30, W - 24, 28);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = left.findIndex(b => inside(b, p.mouseX, p.mouseY));
        if (i < 0) return;
        st.links[i] = null;   // arrastrar desde un cambio ya unido lo suelta
        drag = { i };
        ready();
        return false;
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const j = right.findIndex(b => inside(b, p.mouseX, p.mouseY));
        if (j >= 0) {
          const other = linkedBy(j);
          if (other >= 0) st.links[other] = null;   // el factor solo aguanta una cuerda
          st.links[drag.i] = j;
          api.sfx?.tap?.();
        }
        drag = null;
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ links: [...st.links] }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/etiqueta-rebaja.js
// Etiquetas de rebaja (lección 1.3): tres productos con su precio de lista y un cambio (−20 %,
// +30 %…) y una bandeja de stickers con precios; se arrastra a cada etiqueta el sticker del precio
// final. Entre los stickers hay trampas típicas: el descuento en pesos en vez del precio final y
// restar cuando el cambio era un aumento.
// params = { items: [{ name, price, change }], stickers: [precio] }   state = { placed: [índice de sticker | null] }

GAMES['etiqueta-rebaja'] = (() => {
  const finalOf = it => Math.round(it.price * (1 + it.change / 100));
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const dec = n => String(+n.toFixed(4));
  const pct = c => `${c > 0 ? '+' : '−'}${Math.abs(c)} %`;

  function grade(state, params) {
    const ok = params.items.every((it, i) => {
      const j = state.placed[i];
      return j != null && params.stickers[j] === finalOf(it);
    });
    const solution = params.items.map(it => `${it.name}: ${fmt(it.price)} × ${dec(1 + it.change / 100)} = ${fmt(finalOf(it))}`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { placed: params.items.map(() => null) };
    let locked = false, W = 0, H = 0, tags = [], slots = [], tray = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      // Bandeja compacta anclada al pie (dos filas de 34 px) y las etiquetas reparten lo que queda.
      const n = params.items.length, rows = Math.ceil(params.stickers.length / 3), top = 48;
      const trayY = h - 22 - rows * 40, bottom = trayY - 6, rowH = (bottom - top) / n;
      tags = params.items.map((_, i) => ({ x: 12, y: top + i * rowH + 4, w: w - 24, h: rowH - 8 }));
      const sw = Math.min(92, (w - 24 - 8 * 2) / 3), gap = (w - 24 - 3 * sw) / 2, slotH = Math.min(38, rowH - 16);
      slots = tags.map(t => ({ x: t.x + t.w - sw - 8, y: t.y + (t.h - slotH) / 2, w: sw, h: slotH }));
      tray = params.stickers.map((_, j) => ({ x: 12 + (j % 3) * (sw + gap), y: trayY + Math.floor(j / 3) * 40, w: sw, h: 34 }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const placedAt = j => st.placed.indexOf(j);
    const ready = () => api.ready(st.placed.every(j => j !== null));

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function sticker(b, label, col) {
        // Hueco vacío: solo el borde (el punteado lo pone quien llama). Sticker: crema en la bandeja, color sol ya pegado.
        if (label === '') { p.stroke(col === C.line ? C.mute : col); p.strokeWeight(1.5); p.noFill(); p.rect(b.x, b.y, b.w, b.h, 8); return; }
        const f = col === C.ok || col === C.bad ? col : col === C.brand ? C.sun : C.cream;
        drawTile(p, C, b, label, { fill: f, r: 8, lift: 2, size: b.w < 80 ? 12 : 14 });
      }

      p.draw = () => {
        p.background(C.bg);
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text('Pega en cada etiqueta el sticker del precio final', 12, 8, W - 24, 40);
        params.items.forEach((it, i) => {
          const t = tags[i], s = slots[i], j = st.placed[i];
          const good = j !== null && params.stickers[j] === finalOf(it);
          const col = locked ? (good ? C.ok : C.bad) : j !== null ? C.brand : C.line;
          // Etiqueta con agujero y cordel.
          p.stroke(col); p.strokeWeight(2); p.fill(C.card);
          p.beginShape(); p.vertex(t.x + 18, t.y); p.vertex(t.x + t.w, t.y); p.vertex(t.x + t.w, t.y + t.h); p.vertex(t.x + 18, t.y + t.h); p.vertex(t.x, t.y + t.h / 2); p.endShape(p.CLOSE);
          p.fill(C.bg); p.circle(t.x + 16, t.y + t.h / 2, 7);
          // Dos líneas: «Tenis  −20 %» y «Lista: $ 45.000» (al bloquear, el precio correcto si falló).
          const small = t.h < 52, y1 = t.y + t.h / 2 - (small ? 15 : 17), y2 = t.y + t.h / 2 + (small ? 2 : 3);
          p.noStroke(); p.fill(C.ink); p.textAlign(p.LEFT, p.TOP); p.textStyle(p.BOLD); p.textSize(small ? 13 : 14);
          p.text(it.name, t.x + 28, y1);
          const nameW = p.textWidth(it.name);
          p.fill(it.change < 0 ? C.I : C.Q); p.textSize(small ? 12 : 13);
          p.text(pct(it.change), t.x + 28 + nameW + 8, y1 + 1);
          if (locked && !good) { p.fill(C.ok); p.textStyle(p.BOLD); p.textSize(12); p.text(`→ $ ${fmt(finalOf(it))}`, t.x + 28, y2); }
          else { p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(12); p.text(`Lista: $ ${fmt(it.price)}`, t.x + 28, y2); }
          // Casilla del precio final.
          if (j === null) {
            p.drawingContext.setLineDash([5, 4]); sticker(s, '', col); p.drawingContext.setLineDash([]);
            p.noStroke(); p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER); p.text('precio final', s.x + s.w / 2, s.y + s.h / 2);
          } else sticker(s, `$ ${fmt(params.stickers[j])}`, col);
        });
        params.stickers.forEach((v, j) => {
          if (placedAt(j) >= 0 || (drag && drag.j === j)) return;
          sticker(tray[j], `$ ${fmt(v)}`, C.Z);
        });
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        const extra = params.stickers.length - params.items.length;
        p.text(locked ? (grade(st, params).ok ? '¡Precios bien pegados!' : 'Mira los precios en verde') : extra > 0 ? `Sobra${extra > 1 ? 'n' : ''} ${extra} sticker${extra > 1 ? 's' : ''}: ${extra > 1 ? 'son trampas' : 'es trampa'}` : 'Arrastra cada sticker a su etiqueta', W / 2, H - 10);
        if (drag) sticker({ x: p.mouseX - tray[0].w / 2, y: p.mouseY - 17, w: tray[0].w, h: 34 }, `$ ${fmt(params.stickers[drag.j])}`, C.brand);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = slots.findIndex((s, i) => st.placed[i] !== null && inside(s, p.mouseX, p.mouseY));
        if (i >= 0) { drag = { j: st.placed[i] }; st.placed[i] = null; ready(); return false; }
        const j = tray.findIndex((b, j) => placedAt(j) < 0 && inside(b, p.mouseX, p.mouseY));
        if (j >= 0) { drag = { j }; return false; }
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const i = tags.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (i >= 0) { st.placed[i] = drag.j; api.sfx?.tap?.(); }   // el sticker que estaba vuelve a la bandeja
        drag = null;
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ placed: [...st.placed] }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/mejor-oferta.js
// ¿Cuál conviene? (lección 1.3): en cada ronda, dos vitrinas con el mismo producto y ofertas
// distintas (descuentos sucesivos contra uno solo, subir y bajar el mismo porcentaje contra el
// precio de lista, un porcentaje contra una rebaja fija). Se arrastra el carrito a la vitrina más
// barata; los precios finales solo se revelan al comprobar.
// params = { rounds: [{ price, a: oferta, b: oferta }] }, oferta = { label, changes?: [%], off?: pesos }
// state = { picks: ['a' | 'b' | null] }

GAMES['mejor-oferta'] = (() => {
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const finalPrice = (price, offer) => Math.round((offer.changes || []).reduce((v, c) => v * (1 + c / 100), price) - (offer.off || 0));
  // La opción que conviene: la más barata (tiendas) o, con prefer: 'high', la que deja más (bancos).
  const cheaper = (r, p = {}) => {
    const a = finalPrice(r.price, r.a), b = finalPrice(r.price, r.b);
    if (a === b) return null;
    return (a < b) === (p.prefer !== 'high') ? 'a' : 'b';
  };

  function grade(state, params) {
    const ok = params.rounds.every((r, k) => {
      const best = cheaper(r, params);
      return state.picks[k] != null && (best === null || state.picks[k] === best);
    });
    const solution = params.rounds.map((r, k) => {
      const best = cheaper(r, params);
      return `Ronda ${k + 1}: A ${fmt(finalPrice(r.price, r.a))} · B ${fmt(finalPrice(r.price, r.b))} → ${best === null ? 'igual' : best.toUpperCase()}`;
    }).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette;
    const N = params.rounds.length;
    const st = { picks: params.rounds.map(() => null) };
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], shops = {}, home = null, drag = null;

    function layout(w, h) {
      W = w; H = h;
      tabs = params.rounds.map((_, i) => ({ x: 12 + i * 52, y: 8, w: 44, h: 30 }));
      // El carrito en casa se ancla al pie (pista a H − 14) y las vitrinas ocupan lo que queda.
      const sw = (w - 36) / 2, sy = 88;
      home = { x: w / 2, y: h - 46 };
      const sh = Math.min(h * 0.52, home.y - 30 - sy);
      shops = { a: { x: 12, y: sy, w: sw, h: sh }, b: { x: 24 + sw, y: sy, w: sw, h: sh } };
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const ready = () => api.ready(st.picks.every(v => v !== null));

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function cart(x, y, col) {
        p.stroke(col); p.strokeWeight(3); p.noFill();
        p.line(x - 26, y - 14, x - 18, y - 14); p.line(x - 18, y - 14, x - 12, y + 8); p.line(x - 12, y + 8, x + 18, y + 8);
        p.line(x + 18, y + 8, x + 24, y - 8); p.line(x + 24, y - 8, x - 16, y - 8);
        p.noStroke(); p.fill(col); p.circle(x - 6, y + 17, 8); p.circle(x + 14, y + 17, 8);
      }
      function shop(key, r) {
        const b = shops[key], off = r[key], pick = st.picks[cur] === key;
        const best = cheaper(r, params), good = best === null || key === best;
        const col = locked ? (pick ? (good ? C.ok : C.bad) : good ? C.ok : C.line) : pick ? C.brand : C.line;
        // Toldo y vitrina.
        p.noStroke(); p.fill(key === 'a' ? C.N : C.Q);
        for (let i = 0; i < 6; i++) { p.fill(i % 2 ? C.cream : key === 'a' ? C.coral : C.sky); p.rect(b.x + (i * b.w) / 6, b.y, b.w / 6, 14); }
        p.stroke(col); p.strokeWeight(pick ? 2.5 : 1.5); p.fill(C.card); p.rect(b.x, b.y + 14, b.w, b.h - 14, 0, 0, 12, 12);
        p.noStroke(); p.fill(C.ink); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        p.text(`${params.noun || 'Tienda'} ${key.toUpperCase()}`, b.x + 4, b.y + 22, b.w - 8, 20);
        // La oferta ocupa la franja entre el nombre y la zona del carrito / precio final.
        p.fill(C.N); p.textStyle(p.BOLD); p.textSize(b.w < 130 ? 11 : 14);
        p.text(off.label, b.x + 6, b.y + 44, b.w - 12, b.h - 44 - 40);
        if (locked) {
          p.fill(good ? C.ok : C.bad); p.textSize(15);
          p.text(`$ ${fmt(finalPrice(r.price, off))}`, b.x + 4, b.y + b.h - 34, b.w - 8, 20);
        } else if (pick) cart(b.x + b.w / 2, b.y + b.h - 24, C.brand);
      }

      p.draw = () => {
        p.background(C.bg);
        const r = params.rounds[cur];
        tabs.forEach((t, i) => {
          const best = cheaper(params.rounds[i], params), v = st.picks[i];
          const col = locked ? (v !== null && (best === null || v === best) ? C.ok : C.bad) : i === cur ? C.brand : v !== null ? C.Z : C.line;   // respondida (no «correcta»): azul, no verde
          const plain = col === C.line;   // ficha de ronda, como las de drawTabs
          drawTile(p, C, t, i + 1, { fill: plain ? C.card : col, ink: plain ? C.mute : undefined, r: 8, lift: 0, size: 14, ring: i === cur ? C.sun : null });
        });
        p.noStroke(); p.fill(C.N); p.textAlign(p.LEFT, p.CENTER); p.textStyle(p.BOLD); p.textSize(13);
        p.text(params.prefer === 'high' ? `$ ${fmt(r.price)} en los dos: ¿dónde queda más dinero?` : `Precio de lista $ ${fmt(r.price)} en las dos: ¿dónde sale más barato?`, 12, 44, W - 24, 42);
        shop('a', r); shop('b', r);
        if (!locked && st.picks[cur] === null && !drag) cart(home.x, home.y, C.mute);
        if (drag) cart(p.mouseX, p.mouseY, C.brand);
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? (grade(st, params).ok ? '¡Compras bien hechas!' : 'En verde, la opción que convenía') : params.prefer === 'high' ? 'Arrastra el carrito al banco que deja más dinero' : 'Arrastra el carrito a la vitrina más barata', W / 2, H - 14);
      };

      p.mousePressed = () => {
        const t = tabs.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; api.sfx?.tap?.(); return false; }   // las rondas se pueden repasar aun bloqueado
        if (locked) return;
        const key = st.picks[cur];
        const at = key === null ? Math.hypot(p.mouseX - home.x, p.mouseY - home.y) < 34 : inside(shops[key], p.mouseX, p.mouseY);
        if (!at) return;
        st.picks[cur] = null;   // el carrito sale de la vitrina y se puede llevar a la otra
        drag = true;
        ready();
        return false;
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const key = ['a', 'b'].find(k => inside(shops[k], p.mouseX, p.mouseY));
        drag = false;
        if (key) {
          st.picks[cur] = key; api.sfx?.tap?.();
          const next = st.picks.findIndex(v => v === null);
          if (next >= 0) cur = next;   // pasa sola a la siguiente ronda pendiente
        }
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ picks: [...st.picks] }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, finalPrice };
})();
;
//#archivo js/games/clasifica-cartas.js
// Clasifica las cartas (varias lecciones): un mazo como el de «verdadero-falso», pero con dos
// categorías libres: la tarjeta de arriba se desliza a la izquierda (`left`) o a la derecha
// (`right`), o se usan los botones. Al bloquear se muestran todas con su veredicto.
// params = { left, right, cards: [{ text, side: 'left' | 'right', why }] }   state = { answers: [side | null] }

GAMES['clasifica-cartas'] = (() => {
  function grade(state, params) {
    const wrong = params.cards.filter((c, i) => state.answers[i] !== c.side);
    if (!wrong.length) return { ok: true, solution: 'Todas las cartas están en su categoría.' };
    return { ok: false, solution: wrong.map(c => `«${c.text}» es ${params[c.side]}: ${c.why}`).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette;
    const answers = params.cards.map(() => null);
    const COL = { left: C.N, right: C.Z };
    let locked = false, W = 0, H = 0, cur = 0, drag = null, dx = 0, flying = null, buttons = [];
    const CARD = { w: 0, h: 0, y: 0 };

    function layout(w, h) {
      W = w; H = h;
      CARD.w = w - 56; CARD.h = h * 0.44; CARD.y = h * 0.15;
      const bw = (w - 36) / 2, by = CARD.y + CARD.h + 26;
      buttons = [
        { v: 'left', x: 12, y: by, w: bw, h: 44, t: `← ${params.left}`, col: COL.left },
        { v: 'right', x: 24 + bw, y: by, w: bw, h: 44, t: `${params.right} →`, col: COL.right },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const THRESH = () => W * 0.22;

    function answer(v) {
      if (cur >= params.cards.length) return;
      answers[cur] = v;
      flying = { i: cur, x: dx, vx: (v === 'right' ? 1 : -1) * Math.max(26, Math.abs(dx) / 4) };
      cur += 1; dx = 0; drag = null;
      api.sfx?.tap?.();
      api.ready(answers.every(a => a !== null));
    }

    function wrap(p, text, maxW) {
      const lines = [''];
      text.split(' ').forEach(w => { const t = (lines[lines.length - 1] + ' ' + w).trim(); if (p.textWidth(t) <= maxW || !lines[lines.length - 1]) lines[lines.length - 1] = t; else lines.push(w); });
      return lines;
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function card(i, x, rot, color = C.line) {
        const c = params.cards[i];
        p.push(); p.translate(W / 2 + x, CARD.y + CARD.h / 2); p.rotate(rot);
        // Carta crema con relieve (como las fichas de los videos); la tinta es azul noche en los dos temas.
        p.noStroke(); p.fill(C.creamD); p.rect(-CARD.w / 2, -CARD.h / 2 + 5, CARD.w, CARD.h, 18);
        p.stroke(color); p.strokeWeight(2.5); p.fill(C.cream); p.rect(-CARD.w / 2, -CARD.h / 2, CARD.w, CARD.h, 18);
        p.noStroke(); p.fill(shade(C.night, 1.45)); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(12);
        p.text(`${i + 1} / ${params.cards.length}`, 0, -CARD.h / 2 + 12);
        p.fill(C.night); p.textSize(20); p.textAlign(p.CENTER, p.CENTER);
        const lines = wrap(p, c.text, CARD.w - 40);
        lines.forEach((ln, k) => p.text(ln, 0, (k - (lines.length - 1) / 2) * 26 + 6));
        if (Math.abs(x) > 12 && i === cur) {   // sello según hacia dónde se arrastra
          const r = x > 0; p.fill(shade(r ? COL.right : COL.left, 0.6)); p.textSize(22); p.textAlign(r ? p.LEFT : p.RIGHT, p.TOP);
          p.text((r ? params.right : params.left).toUpperCase(), r ? -CARD.w / 2 + 16 : CARD.w / 2 - 16, -CARD.h / 2 + 30);
        }
        p.pop();
      }

      p.draw = () => {
        p.background(C.bg);
        if (locked) {
          p.noStroke(); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.TOP);
          let y = 12;
          params.cards.forEach((c, i) => {
            const good = answers[i] === c.side, col = good ? C.ok : C.bad;
            p.fill(col); p.textSize(14); p.text(good ? '✔' : '✘', 12, y);
            p.fill(C.ink); p.textSize(13);
            const lines = wrap(p, `${c.text} — ${params[c.side]}`, W - 44);
            lines.forEach((ln, k) => p.text(ln, 32, y + k * 16));
            y += lines.length * 16;
            if (!good) { p.fill(C.mute); p.textSize(12); const why = wrap(p, c.why, W - 44); why.forEach((ln, k) => p.text(ln, 32, y + k * 15)); y += why.length * 15; }
            y += 10;
          });
          return;
        }
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(13);
        p.text(`Desliza: ← ${params.left} · ${params.right} →`, 12, 10, W - 24, 36);
        for (let k = Math.min(cur + 2, params.cards.length - 1); k > cur; k--) card(k, 0, 0.03 * (k - cur), C.line + '88');
        if (cur < params.cards.length) card(cur, dx, dx / W * 0.5, drag ? C.brand : C.line);
        else { p.fill(C.ok); p.textSize(18); p.textAlign(p.CENTER, p.CENTER); p.text('¡Listo! Pulsa Comprobar', W / 2, CARD.y + CARD.h / 2); }
        if (flying) {
          flying.x += flying.vx; flying.vx *= 1.08;
          card(flying.i, flying.x, flying.x / W * 0.6, flying.x > 0 ? COL.right : COL.left);
          if (Math.abs(flying.x) > W) flying = null;
        }
        buttons.forEach(b => {
          const dim = cur >= params.cards.length;
          drawTile(p, C, b, b.t, { fill: dim ? C.card : b.col, ink: dim ? C.mute : undefined, r: 12, size: 14, lift: dim ? 1 : 3 });
        });
      };

      p.mousePressed = () => {
        if (locked || cur >= params.cards.length) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { answer(b.v); return false; }
        const top = { x: W / 2 - CARD.w / 2, y: CARD.y, w: CARD.w, h: CARD.h };
        if (inside(top, p.mouseX, p.mouseY)) { drag = { x0: p.mouseX }; dx = 0; return false; }
      };
      p.mouseDragged = () => { if (!drag) return; dx = p.mouseX - drag.x0; return false; };
      p.mouseReleased = () => {
        if (!drag) return;
        if (Math.abs(dx) > THRESH()) answer(dx > 0 ? 'right' : 'left');
        else { drag = null; dx = 0; }
        return false;
      };
    }, 1.0);

    return {
      loaded: m.ready,
      getState: () => ({ answers: [...answers] }),
      lock() { locked = true; drag = null; dx = 0; flying = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cobra-intereses.js
// Cobra los intereses (lección 1.3b): una línea de meses; tocar el siguiente mes «cobra» la
// moneda del interés simple (capital × tasa, siempre igual) y el acumulado sube. Tocar el último
// mes cobrado lo devuelve. Meta: acumular exactamente el interés pedido.
// params = { capital, rate, target, months }   state = { paid: meses cobrados }

GAMES['cobra-intereses'] = (() => {
  const coinOf = p => Math.round(p.capital * p.rate);
  const answerOf = p => Math.round(p.target / coinOf(p));
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const tex = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');

  function grade(state, params) {
    const coin = coinOf(params), ans = answerOf(params);
    const ok = state.paid > 0 && state.paid * coin === params.target;
    return { ok, solution: `Cada mes paga $${tex(params.capital)} \\cdot ${params.rate} = ${tex(coin)}$; $${tex(params.target)} / ${tex(coin)} = ${ans}$ meses` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { paid: 0 };
    const coin = coinOf(params);
    let locked = false, W = 0, H = 0, cells = [], pile = null, pop = [];

    function layout(w, h) {
      W = w; H = h;
      // Pila y acumulado arriba; la cuadrícula de meses (6 columnas) se ancla al pie y nunca sube
      // por encima del acumulado.
      pile = { x: w / 2, y: 70, r: Math.min(36, w * 0.1) };
      const cols = 6, rows = Math.ceil(params.months / cols), cw = (w - 24 - (cols - 1) * 6) / cols, ch = 38;
      const top = Math.max(h - 30 - rows * (ch + 6), pile.y + pile.r + 72);
      cells = Array.from({ length: params.months }, (_, i) => ({ x: 12 + (i % cols) * (cw + 6), y: top + Math.floor(i / cols) * (ch + 6), w: cw, h: ch }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const ready = () => api.ready(st.paid > 0);

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function coinAt(x, y, r, alpha = 255) {
        p.stroke(C.card); p.strokeWeight(2); p.fill(p.color(C.N)); p.circle(x, y, r * 2);
        p.noStroke(); p.fill(60, 40, 0, alpha); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(r * 0.42);
        p.text(fmt(coin), x, y);
      }

      p.draw = () => {
        p.background(C.bg);
        const total = st.paid * coin, good = total === params.target;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`$ ${fmt(params.capital)} al ${+(params.rate * 100).toFixed(4)} % mensual simple`, 12, 8, W - 24, 30);
        // La pila de monedas cobradas (hasta 6 visibles, apiladas) y el acumulado.
        const shown = Math.min(st.paid, 6);
        for (let k = 0; k < shown; k++) coinAt(pile.x, pile.y + 12 - k * 5, pile.r);
        if (!st.paid) { p.noFill(); p.stroke(C.line); p.strokeWeight(2); p.drawingContext.setLineDash([5, 4]); p.circle(pile.x, pile.y + 12, pile.r * 2); p.drawingContext.setLineDash([]); }
        pop.forEach(c => { c.t += 0.1; coinAt(c.x + (pile.x - c.x) * c.t, c.y + (pile.y - c.y) * c.t, pile.r * 0.6); });
        pop = pop.filter(c => c.t < 1);
        p.noStroke(); p.fill(locked ? (good ? C.ok : C.bad) : C.ink); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(22);
        p.text(`$ ${fmt(total)}`, W / 2, pile.y + pile.r + 18);
        p.fill(C.mute); p.textSize(12); p.textStyle(p.NORMAL);
        p.text(`interés acumulado · meta $ ${fmt(params.target)}`, 12, pile.y + pile.r + 44, W - 24, 20);
        cells.forEach((c, i) => {
          const paid = i < st.paid;
          const col = locked ? (paid ? (good ? C.ok : C.bad) : C.line) : paid ? C.N : C.line;
          p.stroke(col); p.strokeWeight(paid ? 2.5 : 1.5); p.fill(paid ? C.card : C.bg); p.rect(c.x, c.y, c.w, c.h, 8);
          p.noStroke(); p.fill(paid ? C.N : C.mute); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(14);
          p.text(i + 1, c.x + c.w / 2, c.y + c.h / 2);   // número del mes; la moneda ya aparece en la pila
        });
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? (good ? '¡Justo la meta!' : `Eran ${answerOf(params)} meses`) : `Toca los meses en orden para cobrar $ ${fmt(coin)}; toca el último para devolverlo`, 12, H - 26, W - 24, 24);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = cells.findIndex(c => inside(c, p.mouseX, p.mouseY));
        if (i < 0) return;
        if (i === st.paid) { st.paid += 1; pop.push({ x: cells[i].x + cells[i].w / 2, y: cells[i].y + cells[i].h / 2, t: 0 }); api.sfx?.tap?.(); }
        else if (i === st.paid - 1) st.paid -= 1;
        else return;
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ paid: st.paid }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/ajusta-capital.js
// Ajusta el capital (lección 1.3b): una pila de billetes cuya altura se arrastra para fijar el
// capital; a la derecha, el monto compuesto tras los periodos pedidos se calcula en vivo.
// Meta: que el monto sea exactamente el pedido.
// params = { rate, periods, target, step, max, tol }   state = { capital: número | null }

GAMES['ajusta-capital'] = (() => {
  const amount = (c, p) => c * (1 + p.rate) ** p.periods;
  const answerOf = p => Math.round(p.target / (1 + p.rate) ** p.periods / p.step) * p.step;
  const fmt = n => Math.round(n).toLocaleString('es-CO');
  const tex = n => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\\,');

  function grade(state, params) {
    const ok = state.capital != null && Math.abs(amount(state.capital, params) - params.target) <= params.tol;
    const ans = answerOf(params);
    return { ok, solution: `$C = \\dfrac{${tex(params.target)}}{(1 + ${params.rate})^{${params.periods}}} = ${tex(ans)}$` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { capital: null };
    let locked = false, W = 0, H = 0, rail = null, drag = false;

    function layout(w, h) {
      W = w; H = h;
      rail = { x: 24, w: Math.min(150, w * 0.42), top: 96, bottom: h - 70 };
    }
    const toPx = v => rail.bottom - (v / params.max) * (rail.bottom - rail.top);
    const toVal = y => Math.max(0, Math.min(params.max, Math.round(((rail.bottom - y) / (rail.bottom - rail.top)) * params.max / params.step) * params.step));
    const ready = () => api.ready(st.capital !== null && st.capital > 0);

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const cap = st.capital ?? 0, m = amount(cap, params), good = Math.abs(m - params.target) <= params.tol;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`${+(params.rate * 100).toFixed(4)} % por periodo compuesto, ${params.periods} periodos · meta $ ${fmt(params.target)}`, 12, 8, W - 24, 40);
        // Riel y pila de billetes.
        p.stroke(C.line); p.strokeWeight(1.5); p.noFill(); p.rect(rail.x, rail.top, rail.w, rail.bottom - rail.top, 8);
        const top = toPx(cap), nBills = Math.round(cap / params.step);
        for (let k = 0; k < nBills; k++) {
          const y = rail.bottom - (k + 1) * ((rail.bottom - top) / nBills);
          p.stroke(C.bg); p.strokeWeight(1); p.fill(k % 2 ? C.Q : '#2BB383'); p.rect(rail.x + 6, y, rail.w - 12, (rail.bottom - top) / nBills, 2);
        }
        const col = locked ? (good ? C.ok : C.bad) : C.brand;
        p.stroke(col); p.strokeWeight(3); p.fill(C.card); p.rect(rail.x - 6, top - 10, rail.w + 12, 20, 6);
        p.noStroke(); p.fill(col); p.textSize(11); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); p.text('▲ ▼', rail.x + rail.w / 2, top);
        p.fill(C.ink); p.textSize(16); p.textAlign(p.CENTER, p.BOTTOM); p.text(`C = $ ${fmt(cap)}`, rail.x + rail.w / 2, rail.top - 10);
        // El monto, a la derecha: capital × (1 + r)^n.
        const rx = rail.x + rail.w + 16, rw = W - rx - 12, ry = rail.top + 20;
        p.textAlign(p.LEFT, p.TOP); p.fill(C.mute); p.textSize(12); p.textStyle(p.NORMAL);
        p.text(`× (1 + ${params.rate})^${params.periods} = × ${((1 + params.rate) ** params.periods).toFixed(4)}`, rx, ry, rw, 40);
        p.fill(locked ? col : C.ink); p.textSize(20); p.textStyle(p.BOLD);
        p.text(`M = $ ${fmt(m)}`, rx, ry + 50, rw, 60);
        const diff = m - params.target;
        p.fill(Math.abs(diff) <= params.tol ? C.ok : C.mute); p.textSize(12); p.textStyle(p.NORMAL);
        p.text(Math.abs(diff) <= params.tol ? '¡justo en la meta!' : diff > 0 ? `sobran $ ${fmt(diff)}` : `faltan $ ${fmt(-diff)}`, rx, ry + 100, rw, 40);
        if (locked && !good) { p.fill(C.ok); p.textStyle(p.BOLD); p.textSize(14); p.text(`Era C = $ ${fmt(answerOf(params))}`, rx, ry + 140, rw, 40); }
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text('Arrastra la pila para fijar el capital', 12, H - 30, W - 24, 28);
      };

      p.mousePressed = () => {
        if (locked) return;
        if (p.mouseX >= rail.x - 10 && p.mouseX <= rail.x + rail.w + 10 && p.mouseY >= rail.top - 16 && p.mouseY <= rail.bottom + 10) {
          drag = true; st.capital = toVal(p.mouseY); ready(); return false;
        }
      };
      p.mouseDragged = () => { if (!drag) return; st.capital = toVal(p.mouseY); ready(); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = false; api.sfx?.tap?.(); return false; };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ capital: st.capital }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, amount };
})();
;
//#archivo js/games/escalera-aritmetica.js
// La escalera aritmética (lección 1.4): n peldaños; el primero mide a1 y se arrastra el segundo
// hacia arriba o abajo para fijar la diferencia d; toda la escalera se reacomoda. Meta: que el
// último peldaño mida `target`.
// params = { a1, n, target, step, max }   state = { d: número | null }

GAMES['escalera-aritmetica'] = (() => {
  const termAt = (p, d, k) => p.a1 + (k - 1) * d;
  const answerOf = p => (p.target - p.a1) / (p.n - 1);

  function grade(state, params) {
    const ok = state.d != null && termAt(params, state.d, params.n) === params.target;
    const d = answerOf(params);
    return { ok, solution: `$a_{${params.n}} = ${params.a1} + ${params.n - 1}d = ${params.target} \\Rightarrow d = ${d}$` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { d: null };
    let locked = false, W = 0, H = 0, base = 0, unit = 0, stepW = 0, left = 0, drag = null, buttons = [];
    const PX_PER_D = 14;   // el arrastre cuenta 14 px por unidad de d, aunque el peldaño mida menos

    function layout(w, h) {
      W = w; H = h;
      base = h - 92; left = 16; stepW = (w - 32) / params.n;
      unit = (base - 70) / Math.max(params.target, params.a1 + (params.n - 1) * params.max);   // px por unidad
      const bw = (w - 36) / 2;
      buttons = [
        { v: -params.step, x: 12, y: h - 78, w: bw, h: 40, t: `d − ${params.step}`, col: C.I },
        { v: params.step, x: 24 + bw, y: h - 78, w: bw, h: 40, t: `d + ${params.step}`, col: C.Q },
      ];
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const d = () => st.d ?? 0;
    const topOf = k => base - termAt(params, d(), k) * unit;
    const ready = () => api.ready(st.d !== null);
    const setD = v => { st.d = Math.max(-params.max, Math.min(params.max, Math.round(v / params.step) * params.step)); ready(); };

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const last = termAt(params, d(), params.n), good = last === params.target;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`Primer peldaño ${params.a1}; el peldaño ${params.n} debe medir ${params.target}`, 12, 8, W - 24, 36);
        for (let k = 1; k <= params.n; k++) {
          const x = left + (k - 1) * stepW, y = topOf(k), hgt = base - y;
          const isKnob = k === 2 && !locked;
          const col = k === params.n ? (locked ? (good ? C.ok : C.bad) : C.brand) : isKnob ? C.N : C.line;
          // Peldaños rellenos: azules, el que se arrastra color sol y el último con el color del resultado.
          const sc = k === params.n ? col : isKnob ? C.sun : C.sky;
          p.noStroke(); p.fill(sc); p.rect(x + 2, y, stepW - 4, Math.max(2, hgt), 5, 5, 0, 0);
          p.noStroke(); p.fill(k === 2 ? C.N : C.ink); p.textAlign(p.CENTER, p.BOTTOM); p.textStyle(p.BOLD); p.textSize(stepW < 34 ? 10 : 12);
          p.text(termAt(params, d(), k), x + stepW / 2, y - 3);
          p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(10); p.textAlign(p.CENTER, p.TOP); p.text(k, x + stepW / 2, base + 4);
          if (isKnob) { p.fill(inkOn(C.sun, C.ink)); p.textSize(12); p.textAlign(p.CENTER, p.CENTER); p.text('▲▼', x + stepW / 2, y + Math.min(18, hgt / 2)); }
        }
        p.stroke(C.mute); p.strokeWeight(2); p.line(12, base, W - 12, base);
        p.noStroke(); p.fill(st.d === null ? C.mute : C.ink); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(16);
        p.text(st.d === null ? 'd = ?' : `d = ${st.d}`, W / 2, 56);
        buttons.forEach(b => {
          drawTile(p, C, b, b.t, { fill: locked ? C.card : b.col, ink: locked ? C.mute : undefined, r: 12, size: 14, lift: locked ? 1 : 3 });
        });
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL);
        p.text(locked ? (good ? '¡Escalera perfecta!' : `Era d = ${answerOf(params)}`) : 'Arrastra el segundo peldaño o usa los botones: fija la diferencia d', 12, H - 30, W - 24, 28);
      };

      const onKnob = () => p.mouseX >= left + stepW && p.mouseX <= left + 2 * stepW && p.mouseY >= Math.min(topOf(2), base) - 24 && p.mouseY <= base + 4;
      p.mousePressed = () => {
        if (locked) return;
        const b = buttons.find(b => inside(b, p.mouseX, p.mouseY));
        if (b) { setD(d() + b.v); api.sfx?.tap?.(); return false; }
        if (!onKnob()) return;
        drag = { y0: p.mouseY, d0: st.d ?? Math.round((params.target - params.a1) / (params.n - 1) / 2) };   // arranca a medio camino si no hay d
        if (st.d === null) setD(drag.d0);
        return false;
      };
      p.mouseDragged = () => { if (!drag) return; setD(drag.d0 + (drag.y0 - p.mouseY) / PX_PER_D); return false; };
      p.mouseReleased = () => { if (!drag) return; drag = null; api.sfx?.tap?.(); return false; };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ d: st.d }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/parejas-gauss.js
// Las parejas de Gauss (lección 1.4): fichas con los términos de una progresión aritmética; se
// unen con cuerdas por parejas que sumen lo mismo que los extremos (primero + último). Con un
// número impar de términos, el del medio queda solo. Tocar una ficha unida deshace su pareja.
// params = { terms: [números] }   state = { pairs: [[i, j]] }

GAMES['parejas-gauss'] = (() => {
  const pairSum = p => p.terms[0] + p.terms[p.terms.length - 1];
  const totalOf = p => p.terms.reduce((s, v) => s + v, 0);

  function grade(state, params) {
    const n = params.terms.length, need = Math.floor(n / 2), sum = pairSum(params);
    const used = new Set();
    let ok = state.pairs.length === need;
    for (const [i, j] of state.pairs) {
      if (i === j || used.has(i) || used.has(j) || params.terms[i] === undefined || params.terms[j] === undefined) ok = false;
      used.add(i); used.add(j);
      if (params.terms[i] + params.terms[j] !== sum) ok = false;
    }
    const solution = `Cada pareja suma $${params.terms[0]} + ${params.terms[n - 1]} = ${sum}$; ${need} parejas${n % 2 ? ` y el ${params.terms[(n - 1) / 2]} del centro` : ''}: $S = ${totalOf(params)}$`;
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette;
    const COLS = [C.N, C.Z, C.Q, C.I, C.R, C.brand];
    const st = { pairs: [] };
    let locked = false, W = 0, H = 0, tiles = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      const n = params.terms.length, cols = Math.min(n, 6), rows = Math.ceil(n / cols);
      const tw = (w - 24 - (cols - 1) * 8) / cols, th = 40, top = 60 + (h - 60 - 50 - rows * (th + 26)) / 2;
      tiles = params.terms.map((_, i) => ({ x: 12 + (i % cols) * (tw + 8), y: top + Math.floor(i / cols) * (th + 26), w: tw, h: th }));
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const center = t => ({ x: t.x + t.w / 2, y: t.y + t.h / 2 });
    const pairOf = i => st.pairs.findIndex(pr => pr.includes(i));
    const need = Math.floor(params.terms.length / 2);
    const ready = () => api.ready(st.pairs.length === need);

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      // Las parejas de extremos comparten el punto medio: cada cuerda sube un poco más que la
      // anterior (k) para que sus rótulos no se pisen.
      const liftOf = k => 22 + k * 15;
      function rope(a, b, col, k) {
        const ca = center(a), cb = center(b), lift = liftOf(k);
        p.stroke(col); p.strokeWeight(3); p.noFill();
        p.bezier(ca.x, a.y, ca.x, a.y - lift, cb.x, b.y - lift, cb.x, b.y);
        return { x: (ca.x + cb.x) / 2, y: (4 * a.y + 4 * b.y - 6 * lift) / 8 };   // punto medio de la curva
      }

      p.draw = () => {
        p.background(C.bg);
        const sum = pairSum(params);
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`Une las parejas que suman lo mismo que los extremos (${params.terms[0]} + ${params.terms[params.terms.length - 1]})`, 12, 8, W - 24, 40);
        st.pairs.forEach(([i, j], k) => {
          const good = params.terms[i] + params.terms[j] === sum;
          const col = locked ? (good ? C.ok : C.bad) : COLS[k % COLS.length];
          const mid = rope(tiles[i], tiles[j], col, k);
          // Rótulo bajo (13 px), relleno con el color de la cuerda: las cuerdas quedan a 11 px unas de otras y una píldora normal las taparía.
          p.noStroke(); p.fill(col); p.rect(mid.x - 15, mid.y - 6.5, 30, 13, 6.5);
          p.fill(inkOn(col, C.ink)); p.textSize(10); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
          p.text(params.terms[i] + params.terms[j], mid.x, mid.y + 0.5);
        });
        if (drag) { const c = center(tiles[drag.i]); p.stroke(C.brand); p.strokeWeight(3); p.line(c.x, tiles[drag.i].y, p.mouseX, p.mouseY); }
        params.terms.forEach((v, i) => {
          const k = pairOf(i), paired = k >= 0;
          const col = locked ? (paired ? (params.terms[st.pairs[k][0]] + params.terms[st.pairs[k][1]] === sum ? C.ok : C.bad) : (params.terms.length % 2 && i === (params.terms.length - 1) / 2 ? C.ok : C.bad)) : paired ? COLS[k % COLS.length] : drag && drag.i === i ? C.brand : C.line;
          // Ficha crema; al emparejarla toma el color de su cuerda.
          drawTile(p, C, tiles[i], v, { fill: col === C.line ? C.cream : col === C.brand ? C.sun : col, size: 15 });
        });
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? (grade(st, params).ok ? `¡${need} parejas de ${sum}!` : 'En verde, lo que estaba bien') : `${st.pairs.length} de ${need} parejas · arrastra de una ficha a otra${params.terms.length % 2 ? ' · una queda sola' : ''}`, 12, H - 26, W - 24, 24);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = tiles.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (i < 0) return;
        const k = pairOf(i);
        if (k >= 0) st.pairs.splice(k, 1);   // deshace la pareja y permite rehacerla
        drag = { i };
        ready();
        return false;
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const j = tiles.findIndex(t => inside(t, p.mouseX, p.mouseY));
        if (j >= 0 && j !== drag.i) {
          const k = pairOf(j);
          if (k >= 0) st.pairs.splice(k, 1);
          st.pairs.push([drag.i, j]);
          api.sfx?.tap?.();
        }
        drag = null;
        ready();
        return false;
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ pairs: st.pairs.map(pr => [...pr]) }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/rellena-medios.js
// Rellena los medios (lección 1.4): una recta con el primer y el último término fijos y k huecos
// entre ellos; se arrastran fichas (con distractores) a los huecos. Sirve para medios aritméticos
// (sumar d) y geométricos (multiplicar por r).
// params = { first, last, k, kind: 'aritmetica' | 'geometrica', chips: [números] }   state = { slots: [índice | null] }

GAMES['rellena-medios'] = (() => {
  const ratioOf = p => Math.round(Math.pow(p.last / p.first, 1 / (p.k + 1)) * 1e6) / 1e6;
  const diffOf = p => (p.last - p.first) / (p.k + 1);
  const means = p => Array.from({ length: p.k }, (_, i) => (p.kind === 'geometrica'
    ? Math.round(p.first * ratioOf(p) ** (i + 1) * 1e6) / 1e6
    : p.first + (i + 1) * diffOf(p)));
  const fmt = n => String(+n.toFixed(4));

  function grade(state, params) {
    const want = means(params);
    const ok = want.every((v, i) => state.slots[i] != null && params.chips[state.slots[i]] === v);
    const key = params.kind === 'geometrica' ? `r = ${fmt(ratioOf(params))}` : `d = ${fmt(diffOf(params))}`;
    return { ok, solution: `${params.k} medios entre ${params.first} y ${params.last}: ${key}; ${[params.first, ...want, params.last].map(fmt).join(', ')}` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const geo = params.kind === 'geometrica';
    const st = { slots: params.chips.map(() => null).slice(0, params.k) };
    let locked = false, W = 0, H = 0, slots = [], ends = [], tray = [], drag = null;

    function layout(w, h) {
      W = w; H = h;
      const cols = Math.min(params.chips.length, 3), cw = Math.min(84, (w - 24 - (cols - 1) * 8) / cols), cgap = (w - 24 - cols * cw) / Math.max(1, cols - 1);
      const trayTop = h - 36 - Math.ceil(params.chips.length / cols) * 44;
      tray = params.chips.map((_, j) => ({ x: 12 + (j % cols) * (cw + cgap), y: trayTop + Math.floor(j / cols) * 44, w: cw, h: 36 }));
      // Las casillas quedan por encima de la bandeja con sitio para la corrección «→ valor» (locked).
      const n = params.k + 2, bw = Math.min(64, (w - 24 - (n - 1) * 6) / n), gap = (w - 24 - n * bw) / (n - 1), y = Math.min(h * 0.36, trayTop - 82);
      const all = Array.from({ length: n }, (_, i) => ({ x: 12 + i * (bw + gap), y, w: bw, h: 44 }));
      ends = [all[0], all[n - 1]]; slots = all.slice(1, n - 1);
    }
    const inside = (b, x, y) => x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h;
    const placedAt = j => st.slots.indexOf(j);
    const ready = () => api.ready(st.slots.every(j => j !== null));

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function chip(b, label, col, fill = C.card, dashed = false) {
        // Hueco: casilla punteada con «?». Ficha: con relieve y relleno (crema en la bandeja, color sol ya puesta).
        if (dashed) {
          drawSlot(p, C, b, 9, col === C.line ? C.mute : col);
          p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(14); p.text(label, b.x + b.w / 2, b.y + b.h / 2);
          return;
        }
        drawTile(p, C, b, label, { fill: fill === C.card ? C.cream : fill, r: 9, lift: 2, size: b.w < 60 ? 12 : 14 });
      }

      p.draw = () => {
        p.background(C.bg);
        const want = means(params);
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        p.text(`${params.k} medios ${geo ? 'geométricos' : 'aritméticos'} entre ${params.first} y ${params.last}`, 12, 8, W - 24, 36);
        p.stroke(C.mute); p.strokeWeight(2); p.line(ends[0].x + ends[0].w / 2, ends[0].y + ends[0].h + 10, ends[1].x + ends[1].w / 2, ends[0].y + ends[0].h + 10);
        chip(ends[0], params.first, C.mute, C.sky); chip(ends[1], params.last, C.mute, C.sky);   // los extremos, fijos, en azul
        slots.forEach((s, i) => {
          const j = st.slots[i], good = j !== null && params.chips[j] === want[i];
          const col = locked ? (good ? C.ok : C.bad) : j !== null ? C.brand : C.line;
          if (j === null) chip(s, '?', col, C.bg, true); else chip(s, params.chips[j], col, locked ? col : C.sun);
          if (locked && !good) { p.noStroke(); p.fill(C.ok); p.textSize(11); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.TOP); p.text(`→ ${fmt(want[i])}`, s.x + s.w / 2, s.y + s.h + 16); }
        });
        // Saltos entre casillas: «+ d» o «× r», pista visual sin el valor.
        p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.BOTTOM);
        const all = [ends[0], ...slots, ends[1]];
        for (let i = 0; i < all.length - 1; i++) p.text(geo ? '× r' : '+ d', (all[i].x + all[i].w + all[i + 1].x) / 2, all[i].y - 4);
        if (!locked) params.chips.forEach((v, j) => { if (placedAt(j) < 0 && !(drag && drag.j === j)) chip(tray[j], v, C.Z); });   // bloqueado, la bandeja sobra
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        p.text(locked ? (grade(st, params).ok ? '¡Huecos bien rellenos!' : 'Mira los valores en verde') : `Arrastra las fichas a los huecos · sobran ${params.chips.length - params.k}`, 12, H - 26, W - 24, 24);
        if (drag) chip({ x: p.mouseX - tray[0].w / 2, y: p.mouseY - 18, w: tray[0].w, h: 36 }, params.chips[drag.j], C.brand, C.sun);
      };

      p.mousePressed = () => {
        if (locked) return;
        const i = slots.findIndex((s, i) => st.slots[i] !== null && inside(s, p.mouseX, p.mouseY));
        if (i >= 0) { drag = { j: st.slots[i] }; st.slots[i] = null; ready(); return false; }
        const j = tray.findIndex((b, j) => placedAt(j) < 0 && inside(b, p.mouseX, p.mouseY));
        if (j >= 0) { drag = { j }; return false; }
      };
      p.mouseDragged = () => (drag ? false : undefined);
      p.mouseReleased = () => {
        if (!drag) return;
        const i = slots.findIndex(s => inside({ x: s.x - 6, y: s.y - 10, w: s.w + 12, h: s.h + 20 }, p.mouseX, p.mouseY));
        if (i >= 0) { st.slots[i] = drag.j; api.sfx?.tap?.(); }
        drag = null;
        ready();
        return false;
      };
    }, 1.0);

    return {
      loaded: m.ready,
      getState: () => ({ slots: [...st.slots] }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, means };
})();
;
//#archivo js/games/suma-filas.js
// Suma de filas (lecciones 1.4 y 1.5): tocar «+ fila» añade una fila de puntos (la primera tiene
// `first`, cada una `d` más) y el contador muestra el total; «− fila» quita la última.
// Meta: que el total sea exactamente `target`. Sirve para el teatro (8, 10, 12…) y la pirámide (1, 2, 3…).
// params = { first, d, target, max, item }   state = { rows }

GAMES['suma-filas'] = (() => {
  const total = (rows, p) => (rows * (2 * p.first + (rows - 1) * p.d)) / 2;
  const answerOf = p => { for (let n = 1; n <= p.max; n++) if (total(n, p) === p.target) return n; return null; };

  function grade(state, params) {
    const ok = state.rows > 0 && total(state.rows, params) === params.target;
    const n = answerOf(params);
    return { ok, solution: n === null ? `Ninguna cantidad de filas da ${params.target}` : `$S_{${n}} = \\dfrac{${n}\\,(2 \\cdot ${params.first} + ${n - 1} \\cdot ${params.d})}{2} = ${params.target}$: ${n} filas` };
  }

  function create(host, params, api) {
    const C = api.palette;
    const st = { rows: 0 };
    let locked = false, W = 0, H = 0, area = null, rail, drag = false;

    function layout(w, h) {
      W = w; H = h;
      area = { x: 12, y: 68, w: w - 64, h: h - 143 };
      rail = lineMap(0, params.max, area.y, area.y + area.h);
    }
    const ready = () => api.ready(st.rows > 0);
    const handle = () => ({ x: W - 26, y: rail.toPx(st.rows) });

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const sum = total(st.rows, params), good = sum === params.target;
        p.noStroke(); p.fill(C.N); p.textAlign(p.CENTER, p.TOP); p.textStyle(p.BOLD); p.textSize(14);
        const one = params.item.replace(/s$/, '');
        p.text(`Fila 1: ${params.first} ${params.first === 1 ? one : params.item} · cada fila ${params.d} más · meta ${params.target}`, 12, 8, W - 24, 36);
        // Filas de puntos, de arriba abajo, centradas; el tamaño baja si hay muchas.
        const rowH = area.h / Math.max(params.max, 1);
        for (let k = 0; k < st.rows; k++) {
          const n = params.first + k * params.d, y = area.y + (k + 0.5) * rowH;
          const dotW = Math.min(rowH * 0.7, (area.w - 40) / n), x0 = area.x + area.w / 2 - ((n - 1) * dotW) / 2;
          p.noStroke(); p.fill(k === st.rows - 1 ? C.coral : C.sky);   // coral: el sol casi no se ve sobre el papel del tema claro
          for (let i = 0; i < n; i++) p.circle(x0 + i * dotW, y, Math.max(3, dotW * 0.72));
          if (rowH >= 11) { p.fill(C.mute); p.textSize(10); p.textStyle(p.NORMAL); p.textAlign(p.RIGHT, p.CENTER); p.text(n, area.x + area.w, y); }
        }
        p.fill(locked ? (good ? C.ok : C.bad) : C.ink); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(18);
        p.text(`${st.rows} fila${st.rows === 1 ? '' : 's'} · ${sum} ${params.item}`, W / 2, H - 44);
        const { x, y } = handle();
        p.stroke(C.line); p.strokeWeight(3); p.line(x, rail.toPx(0), x, rail.toPx(params.max));
        p.stroke(C.brand); p.strokeWeight(2); p.fill(C.card); p.circle(x, y, 21);
        p.noStroke(); p.fill(C.ink); p.textSize(12); p.text(st.rows, x, y);
        p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL); p.textAlign(p.CENTER, p.CENTER);
        const ans = answerOf(params);
        p.text(locked ? (good ? '¡Justo la meta!' : ans === null ? `Ninguna cantidad de filas da ${params.target}` : `Eran ${ans} filas`) : 'Arrastra la manija para desplegar las filas', 12, H - 23, W - 24, 24);
      };

      const move = () => {
        const next = Math.max(0, Math.min(params.max, Math.round(rail.toVal(p.mouseY))));
        if (next !== st.rows) { st.rows = next; api.sfx?.tap?.(); ready(); }
      };
      p.mousePressed = () => {
        if (locked || !inCanvas(p) || Math.abs(p.mouseX - handle().x) > 24 || p.mouseY < area.y - 18 || p.mouseY > area.y + area.h + 18) return;
        drag = true; move(); return false;
      };
      p.mouseDragged = () => { if (drag && !locked) { move(); return false; } };
      p.mouseReleased = () => { drag = false; };
    }, 1.12, () => {
      if (locked || !rail) return null;
      return { from: handle(), to: { x: handle().x, y: rail.toPx(st.rows ? st.rows - 1 : 1) } };
    });

    return {
      loaded: m.ready,
      getState: () => ({ rows: st.rows }),
      lock() { locked = true; },
      destroy: () => m.remove(),
      demo: m.demo,
    };
  }

  return { grade, create, total, demo: true };
})();
