      const r = st.rounds[cur], tw = 40, gap = 8;
      const x0 = 70 + Math.max(0, (w - 70 - 12 - r.in.length * (tw + gap)) / 2);
      tiles = r.in.map((_, i) => ({ x: x0 + i * (tw + gap), y: h * 0.52, w: tw, h: tw }));
      outTiles = r.out.map((_, i) => ({ x: 20 + i * (tw + gap), y: h * 0.52 - 62, w: tw, h: tw }));
