    aspect: 1.5, init, ok, answer,
    solution: it => tex(answer(it)).replace(/\$/g, '').replace('\\cup', '∪').replace('\\cap', '∩').replace('\\triangle', '△').replace(/\^c/g, 'ᶜ').replace('-', '−'),
