    if (o.lx) TK.label(p, C, o.lx, b.x + b.w - 10, Math.min(b.y + b.h - 8, Y(0) - 10), C.mute, 10, 30);
    if (o.ly) TK.label(p, C, o.ly, Math.max(b.x + 10, X(0) + 12), b.y + 10, C.mute, 10, 30);
