    press(G, x, y) { const q = (G.src || []).find(q => hitBox({ x: q.x - 4, y: q.y - 4, w: q.w + 8, h: q.h + 8 }, x, y)); if (q) { G.drag = { k: q.k, x, y, from: 'tray' }; return true; } if (hitBox(G.zone, x, y)) { G.drag = { k: -1, x, y, from: 'zone' }; return true; } return false; },
