//#archivo js/games/conjugado-espejo.js
// El conjugado en el espejo (Álgebra, alg-23c; spec 2026-11-18-algebra-revision): el conjugado de a + bi es a − bi, su
// reflejo en el eje real. Se arrastra el reflejo hasta su lugar; al acertar se ve que z·z̄ = a² + b² es un número real
// (lo que permite dividir complejos).
// params = { rounds: [{ a, b }] }   state = { rounds: [{ a, b }] }   (el punto que se arrastra)
GAMES['conjugado-espejo'] = (() => {
  const V = { x0: -6, x1: 6, y0: -6, y1: 6 };
  const ok = (s, r) => s.a === r.a && s.b === -r.b;
  const z = (a, b) => GAMES['plano-complejo'].z(a, b);
  const game = roundsGame({
    aspect: 1.15,
    init: () => ({ a: 0, b: 0 }),
    ok,
    solution: r => `${z(r.a, -r.b)}; (${z(r.a, r.b)})(${z(r.a, -r.b)}) = ${r.a * r.a + r.b * r.b}`,
    prompt: r => `Pon el conjugado de $${z(r.a, r.b)}$`,
    foot: () => 'Arrastra el punto al reflejo de z en el eje real',
    layout(G) { const s = Math.min(G.W - 32, G.H - 190); G.b = { x: (G.W - s) / 2, y: 96, w: s, h: s }; G.fb = { x: 12, y: G.H - 76, w: G.W - 24, h: 48 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, s = G.locked && !ok(G.s, r) ? { a: r.a, b: -r.b } : G.s, M = G.M = RK.plane(p, C, G.b, V, { lx: 'Re', ly: 'Im' }), good = ok(s, r);
      p.stroke(C.sky); p.strokeWeight(3); p.line(M.X(0), M.Y(0), M.X(r.a), M.Y(r.b)); drawDot(p, C, M.X(r.a), M.Y(r.b), 12, C.sky); TK.label(p, C, 'z', M.X(r.a) + 12, M.Y(r.b) - 10, C.sky, 13, 20);
      p.stroke(RK.al(p, C.coral, 140)); p.strokeWeight(1.4); p.drawingContext.setLineDash([4, 4]); p.line(M.X(r.a), M.Y(r.b), M.X(s.a), M.Y(s.b)); p.drawingContext.setLineDash([]);
      RK.knob(p, C, M.X(s.a), M.Y(s.b), C.coral);
      RK.strip(p, C, G.fb, good ? `$(${z(r.a, r.b)})(${z(r.a, -r.b)}) = ${r.a}^2 + ${Math.abs(r.b)}^2 = ${r.a * r.a + r.b * r.b}$` : `$\\bar z \\;?\\; ${z(s.a, s.b)}$`, { col: G.locked || good ? C.ok : C.brand, size: 17 });
    },
    press(G, x, y) { if (!hitBox(G.b, x, y)) return false; G.grab = true; game.move(G, x, y); return true; },
    drag(G, x, y) { if (!G.grab) return false; game.move(G, x, y); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.M.X(G.s.a), y: G.M.Y(G.s.b) }, to: { x: G.M.X(2), y: G.M.Y(-2) }, text: 'Arrastra el reflejo', ty: G.b.y + G.b.h + 14 }),
    peek: G => ({ b: G.b }),
  });
  game.move = (G, x, y) => { G.s.a = Math.max(V.x0, Math.min(V.x1, Math.round(G.M.iX(x)))); G.s.b = Math.max(V.y0, Math.min(V.y1, Math.round(G.M.iY(y)))); G.touch(); };
  return game;
})();
;
//#archivo js/games/modulo-circulo.js
// El módulo es una distancia (Álgebra, alg-23c; spec 2026-11-18-algebra-revision): |a + bi| = √(a² + b²) es la distancia
// del punto al origen. Se arrastra el radio de un círculo con centro en el origen hasta que pase por z; el triángulo de
// catetos a y b muestra el teorema de Pitágoras.
// params = { rounds: [{ a, b }] }   (a² + b² es un cuadrado)   state = { rounds: [{ R }] }   (de 1 a 15)
GAMES['modulo-circulo'] = (() => {
  const need = r => Math.round(Math.hypot(r.a, r.b));
  const ok = (s, r) => s.R === need(r);
  const z = (a, b) => GAMES['plano-complejo'].z(a, b);
  const game = roundsGame({
    aspect: 1.15,
    init: () => ({ R: 1 }),
    ok,
    solution: r => `|${z(r.a, r.b)}| = √(${r.a * r.a} + ${r.b * r.b}) = ${need(r)}`,
    prompt: r => `Abre el círculo hasta $${z(r.a, r.b)}$: ¿cuál es su módulo?`,
    foot: () => 'Arrastra el borde del círculo',
    layout(G) { const s = Math.min(G.W - 32, G.H - 190); G.b = { x: (G.W - s) / 2, y: 96, w: s, h: s }; G.fb = { x: 12, y: G.H - 76, w: G.W - 24, h: 48 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, R = G.locked && !ok(G.s, r) ? need(r) : G.s.R, m = Math.max(need(r), 5) + 2, V = { x0: -m, x1: m, y0: -m, y1: m }, M = G.M = RK.plane(p, C, G.b, V, { step: m > 10 ? 2 : 1, lx: 'Re', ly: 'Im' });
      p.stroke(RK.al(p, C.sky, 160)); p.strokeWeight(1.6); p.line(M.X(0), M.Y(0), M.X(r.a), M.Y(0)); p.line(M.X(r.a), M.Y(0), M.X(r.a), M.Y(r.b));
      p.stroke(C.sky); p.strokeWeight(2.6); p.line(M.X(0), M.Y(0), M.X(r.a), M.Y(r.b)); drawDot(p, C, M.X(r.a), M.Y(r.b), 12, C.sky);
      p.noFill(); p.stroke(ok({ R }, r) || G.locked ? C.ok : C.coral); p.strokeWeight(2.4); p.circle(M.X(0), M.Y(0), 2 * (M.X(R) - M.X(0)));
      G.kx = M.X(R); RK.knob(p, C, G.kx, M.Y(0), C.coral); G.m = m;
      RK.strip(p, C, G.fb, `$\\text{radio } ${R}\\qquad |z| = \\sqrt{${r.a}^2 + ${r.b}^2}$`, { col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 17 });
    },
    press(G, x, y) { if (!hitBox(G.b, x, y)) return false; G.grab = true; game.move(G, x, y); return true; },
    drag(G, x, y) { if (!G.grab) return false; game.move(G, x, y); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.kx, y: G.M.Y(0) }, to: { x: G.kx + 50, y: G.M.Y(0) }, text: 'Arrastra el borde', ty: G.b.y + G.b.h + 14 }),
    peek: G => ({ b: G.b }),
  });
  game.move = (G, x, y) => { const R = Math.max(1, Math.min(15, Math.round(Math.hypot(G.M.iX(x), G.M.iY(y))))); if (R !== G.s.R || !G.touched[G.cur]) { G.s.R = R; G.touch(); } };
  return Object.assign(game, { need });
})();
;
//#archivo js/games/despeja-x.js
// Despeja x (Álgebra, alg-1; spec 2026-11-18-algebra-revision): resolver es aplicar la misma operación a los dos lados.
// La ecuación ax + b = c (o x/a + b = c) está escrita; abajo hay tarjetas de operaciones. Se arrastra una tarjeta sobre
// la ecuación y se aplica a los dos lados: la ecuación cambia. Hay que dejar x sola. Se puede deshacer arrastrando la
// ecuación hacia abajo.
// params = { rounds: [{ a, b, c, div?, cards: [[op, v], …] }] }   (op '+' o '×')   state = { rounds: [{ steps: [índices de tarjeta] }] }
GAMES['despeja-x'] = (() => {
  // La ecuación es k·x + m = n (k puede ser fracción).
  const start = r => ({ k: r.div ? 1 / r.a : r.a, m: r.b, n: r.c });
  const apply = (e, [op, v]) => (op === '+' ? { k: e.k, m: e.m + v, n: e.n + v } : { k: e.k * v, m: e.m * v, n: e.n * v });
  const state = (s, r) => s.steps.reduce((e, i) => apply(e, r.cards[i]), start(r));
  const ok = (s, r) => { const e = state(s, r); return Math.abs(e.k - 1) < 1e-9 && Math.abs(e.m) < 1e-9; };
  const fmt = v => RK.num(Math.round(v * 1e6) / 1e6);
  const lhs = e => { const k = Math.abs(e.k - 1) < 1e-9 ? 'x' : Math.abs(e.k + 1) < 1e-9 ? '-x' : `${fmt(e.k)}x`; return Math.abs(e.m) < 1e-9 ? k : `${k} ${e.m < 0 ? '-' : '+'} ${fmt(Math.abs(e.m))}`; };
  const answer = r => { const steps = [], e0 = start(r); const iPlus = r.cards.findIndex(([op, v]) => op === '+' && Math.abs(v + e0.m) < 1e-9); if (e0.m && iPlus >= 0) steps.push(iPlus); const iMul = r.cards.findIndex(([op, v]) => op === '×' && Math.abs(v * e0.k - 1) < 1e-9); if (Math.abs(e0.k - 1) > 1e-9 && iMul >= 0) steps.push(iMul); return { steps }; };
  const lab = ([op, v]) => (op === '+' ? `${v < 0 ? '-' : '+'}\\,${fmt(Math.abs(v))}` : `\\times\\,${fmt(v)}`);
  const game = roundsGame({
    aspect: 1.1,
    init: () => ({ steps: [] }),
    ok,
    answered: s => s.steps.length > 0,
    solution: r => { const e = state(answer(r), r); return `x = ${fmt(e.n).replace(/\\tfrac\{(\d+)\}\{(\d+)\}/, '$1/$2')}`; },
    prompt: r => `Despeja x en $${lhs(start(r))} = ${fmt(r.c)}$`,
    foot: () => 'Arrastra una tarjeta a la ecuación: se aplica a los dos lados',
    layout(G) { G.eq = { x: 16, y: 106, w: G.W - 32, h: 64 }; G.cardY = G.H * 0.55; G.fb = { x: 12, y: G.H - 76, w: G.W - 24, h: 48 }; },
    enter(G) { G.drag = null; },
    draw(G) {
      const { p, C, r } = G, s = G.locked && !ok(G.s, r) ? answer(r) : G.s, e = state(s, r);
      p.stroke(C.brand); p.strokeWeight(1.5); p.fill(RK.al(p, C.brand, 20)); p.rect(G.eq.x, G.eq.y, G.eq.w, G.eq.h, 12);
      TK.label(p, C, `$${lhs(e)} = ${fmt(e.n)}$`, G.W / 2, G.eq.y + G.eq.h / 2, C.ink, 22, G.eq.w - 20);
      TK.label(p, C, s.steps.length ? `pasos: ${s.steps.map(i => r.cards[i][0] === '+' ? `${r.cards[i][1] < 0 ? '−' : '+'}${Math.abs(r.cards[i][1])}` : `×${fmt(r.cards[i][1]).replace(/\\tfrac\{(\d+)\}\{(\d+)\}/, '$1/$2')}`).join('  ')}` : 'aún sin pasos', G.W / 2, G.eq.y + G.eq.h + 16, C.mute, 11, G.W - 30);
      const w = Math.min(70, (G.W - 24) / r.cards.length - 6);
      G.cards = r.cards.map((c, i) => ({ i, x: G.W / 2 - (r.cards.length * (w + 6) - 6) / 2 + i * (w + 6), y: G.cardY, w, h: 40 }));
      G.cards.forEach(b => { if (G.drag?.i !== b.i) RK.chip(p, C, b, `$${lab(r.cards[b.i])}$`, { size: 14 }); });
      if (G.drag) RK.chip(p, C, { x: G.drag.x - w / 2, y: G.drag.y - 20, w, h: 40 }, `$${lab(r.cards[G.drag.i])}$`, { on: true, size: 14 });
      RK.strip(p, C, G.fb, ok(s, r) ? `$x = ${fmt(e.n)}$` : '$\\text{deja la x sola}$', { kicker: 'Lo mismo a los dos lados', col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 19 });
    },
    press(G, x, y) {
      const b = (G.cards || []).find(b => hitBox(b, x, y)); if (b) { G.drag = { i: b.i, x, y }; return true; }
      if (hitBox(G.eq, x, y) && G.s.steps.length) { G.drag = { i: -1, x, y }; return true; }
      return false;
    },
    drag(G, x, y) { if (!G.drag) return false; G.drag.x = x; G.drag.y = y; return true; },
    release(G, x, y) {
      const d = G.drag; G.drag = null; if (!d) return;
      if (d.i === -1) { if (y > G.eq.y + G.eq.h + 30) { G.s.steps.pop(); G.touch(); } return; }
      if (hitBox({ x: G.eq.x, y: G.eq.y - 20, w: G.eq.w, h: G.eq.h + 40 }, x, y) && G.s.steps.length < 4) { G.s.steps.push(d.i); G.touch(); }
    },
    demo(G) { const b = G.cards?.[0]; return b ? { from: { x: b.x + b.w / 2, y: b.y + 20 }, to: { x: G.W / 2, y: G.eq.y + 30 }, text: 'Arrastra una tarjeta a la ecuación', ty: G.cardY + 60 } : null; },
    peek: G => ({ cards: G.cards, eq: G.eq }),
  });
  return Object.assign(game, { answer, state });
})();
;
//#archivo js/games/encuentro-caminantes.js
// ¿Cuándo se encuentran? (Álgebra, alg-1; spec 2026-11-18-algebra-revision): dos caminantes en un mismo camino; uno sale
// adelante y el otro va más rápido. Su posición es lineal en el tiempo: a·t + b. Se arrastra el reloj y se mueven los
// dos; hay que parar el reloj cuando están en el mismo punto: a·t + b = c·t + d.
// params = { rounds: [{ A: [vel, inicio], B: [vel, inicio], max }] }   state = { rounds: [{ t }] }   (minutos enteros)
GAMES['encuentro-caminantes'] = (() => {
  const pos = (q, t) => q[0] * t + q[1];
  const need = r => (r.B[1] - r.A[1]) / (r.A[0] - r.B[0]);
  const ok = (s, r) => pos(r.A, s.t) === pos(r.B, s.t);
  const game = roundsGame({
    aspect: 1,
    init: () => ({ t: 0 }),
    ok,
    solution: r => `t = ${need(r)}: ${r.A[0]}t + ${r.A[1]} = ${r.B[0]}t + ${r.B[1]}`,
    prompt: r => `Ana sale a ${r.A[1]} m y anda ${r.A[0]} m/min; Beto, a ${r.B[1]} m, ${r.B[0]} m/min. ¿Cuándo se juntan?`,
    foot: () => 'Arrastra el reloj',
    layout(G) { G.y1 = 150; G.y2 = 200; G.tY = G.H - 108; G.fb = { x: 12, y: G.H - 72, w: G.W - 24, h: 46 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, t = G.locked && !ok(G.s, r) ? need(r) : G.s.t, D = Math.max(pos(r.A, r.max), pos(r.B, r.max)) * 1.05, X = v => 20 + (G.W - 40) * v / D;
      [[G.y1, r.A, C.sky, 'Ana'], [G.y2, r.B, C.coral, 'Beto']].forEach(([y, q, col, n]) => { p.stroke(C.line); p.strokeWeight(2); p.line(20, y + 12, G.W - 20, y + 12); const x = X(pos(q, t)); p.noStroke(); p.fill(col); p.circle(x, y, 18); TK.label(p, C, `${n}: ${pos(q, t)} m`, Math.min(G.W - 50, Math.max(50, x)), y - 18, col, 11, 90); });
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, r.max + 1, t, i => (i % 2 === 0 ? String(i) : null));
      TK.label(p, C, `t = ${t} min`, G.W / 2, G.tY - 22, C.ink, 13, 100);
      RK.strip(p, C, G.fb, `$${r.A[0]}\\cdot${t} + ${r.A[1]} = ${pos(r.A, t)} \\quad ${r.B[0]}\\cdot${t} + ${r.B[1]} = ${pos(r.B, t)}$`, { col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 15 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.t), y: G.tY }, to: { x: G.X(G.s.t + 4), y: G.tY }, text: 'Arrastra el reloj', ty: G.tY - 46 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const t = RK.pick(x, 30, G.W - 30, G.r.max + 1); if (t !== G.s.t || !G.touched[G.cur]) { G.s.t = t; G.touch(); } };
  return Object.assign(game, { need });
})();
;
//#archivo js/games/consecutivos.js
// Números seguidos (Álgebra, alg-1; spec 2026-11-18-algebra-revision): plantear una ecuación con una incógnita. Hay k
// números consecutivos (o de dos en dos) que suman S; se arrastra el primero, x, y los demás lo siguen: x, x + d, x + 2d…
// Las barras muestran la suma, que es kx + (algo fijo). Hay que encontrar x.
// params = { rounds: [{ k, d, S }] }   state = { rounds: [{ x }] }   (de 1 a 60)
GAMES['consecutivos'] = (() => {
  const sum = (r, x) => r.k * x + (r.d * r.k * (r.k - 1)) / 2;
  const need = r => (r.S - (r.d * r.k * (r.k - 1)) / 2) / r.k;
  const ok = (s, r) => sum(r, s.x) === r.S;
  const game = roundsGame({
    aspect: 1,
    init: () => ({ x: 1 }),
    ok,
    solution: r => Array.from({ length: r.k }, (_, i) => need(r) + i * r.d).join(' + ') + ` = ${r.S}`,
    prompt: r => `${r.k} números ${r.d === 1 ? 'seguidos' : r.d === 2 ? 'pares (o impares) seguidos' : `de ${r.d} en ${r.d}`} suman ${r.S}. ¿Cuál es el primero?`,
    foot: () => 'Arrastra el primero: los demás lo siguen',
    layout(G) { G.base = G.H - 150; G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, x = G.locked && !ok(G.s, r) ? need(r) : G.s.x, w = (G.W - 40) / r.k, top = 60 + r.d * r.k, Y = v => G.base - (G.base - 104) * v / top;
      for (let i = 0; i < r.k; i++) { const v = x + i * r.d; p.noStroke(); p.fill(C.sky); p.rect(20 + i * w + 4, Y(v), w - 8, G.base - Y(v), 3); TK.label(p, C, String(v), 20 + i * w + w / 2, Y(v) - 10, C.ink, 12, w); }
      TK.label(p, C, `suma: ${sum(r, x)}`, G.W / 2, 104, sum(r, x) === r.S ? C.ok : C.mute, 13, 140);
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, 60, x - 1, i => ((i + 1) % 10 === 0 ? String(i + 1) : null));
      RK.strip(p, C, G.fb, `$${r.k}x + ${(r.d * r.k * (r.k - 1)) / 2} = ${r.S}$`, { kicker: `x = ${x}`, col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 18 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.x - 1), y: G.tY }, to: { x: G.X(G.s.x + 12), y: G.tY }, text: 'Arrastra el primero', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const v = RK.pick(x, 30, G.W - 30, 60) + 1; if (v !== G.s.x || !G.touched[G.cur]) { G.s.x = v; G.touch(); } };
  return Object.assign(game, { need });
})();
;
//#archivo js/games/sin-o-infinitas.js
// Una, ninguna o infinitas (Álgebra, alg-1; spec 2026-11-18-algebra-revision): en ax + b = cx + d las dos partes son
// rectas. Se arrastra el número que falta y se ven las dos rectas: si se cortan hay una solución, si son paralelas no hay
// ninguna y si son la misma hay infinitas. Cada ronda pide uno de los tres casos.
// params = { rounds: [{ a, b, c, want: 'una' | 'ninguna' | 'infinitas', what: 'd' }] }   state = { rounds: [{ d }] }   (de −6 a 6)
GAMES['sin-o-infinitas'] = (() => {
  const kind = (r, d) => (r.a !== r.c ? 'una' : r.b === d ? 'infinitas' : 'ninguna');
  const ok = (s, r) => kind(r, s.d) === r.want;
  const answer = r => { for (let d = -6; d <= 6; d++) if (kind(r, d) === r.want) return { d }; return null; };
  const t = (a, b) => `${a === 1 ? '' : a === -1 ? '-' : a}x ${b < 0 ? '-' : '+'} ${Math.abs(b)}`;
  const V = { x0: -5, x1: 5, y0: -12, y1: 12 };
  const game = roundsGame({
    aspect: 1.1,
    init: r => ({ d: r.want === 'infinitas' ? (r.b === 6 ? 5 : r.b + 1) : r.b }),
    ok,
    solution: r => `d = ${answer(r).d}`,
    prompt: r => `Elige d para que $${t(r.a, r.b)} = ${t(r.c, 0).replace('+ 0', '+ d')}$ tenga ${r.want === 'una' ? 'una solución' : r.want === 'ninguna' ? 'ninguna solución' : 'infinitas soluciones'}`,
    foot: () => 'Arrastra d y mira las dos rectas',
    layout(G) { G.b = { x: 16, y: 104, w: G.W - 32, h: G.H * 0.42 }; G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, d = G.locked && !ok(G.s, r) ? answer(r).d : G.s.d, M = RK.plane(p, C, G.b, V, { step: 2 }), k = kind(r, d);
      RK.curve(p, G.b, M, V, x => r.a * x + r.b, C.sky, 3); RK.curve(p, G.b, M, V, x => r.c * x + d, C.coral, k === 'infinitas' ? 1.5 : 3);
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, 13, d + 6, i => (i % 2 === 0 ? String(i - 6) : null));
      RK.strip(p, C, G.fb, `$${t(r.a, r.b)} = ${t(r.c, d)}$`, { kicker: k === 'una' ? 'se cortan: una solución' : k === 'ninguna' ? 'paralelas: ninguna' : 'la misma recta: infinitas', col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 17 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.d + 6), y: G.tY }, to: { x: G.X(G.s.d + 8), y: G.tY }, text: 'Arrastra d', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const d = RK.pick(x, 30, G.W - 30, 13) - 6; if (d !== G.s.d || !G.touched[G.cur]) { G.s.d = d; G.touch(); } };
  return Object.assign(game, { answer, kind });
})();
