//#archivo js/games/discriminante-traslada.js
// ¿Cuántas veces corta? (Álgebra, alg-4; spec 2026-11-18-algebra-revision): subir o bajar la parábola cambia su
// discriminante. y = x² + bx + c: se arrastra c y la parábola sube o baja; se ven sus cortes con el eje x y Δ = b² − 4c.
// Cada ronda pide un caso: dos cortes, uno (toca) o ninguno.
// params = { rounds: [{ b, want: 2 | 1 | 0 }] }   state = { rounds: [{ c }] }   (de −8 a 12)
GAMES['discriminante-traslada'] = (() => {
  const V = { x0: -7, x1: 7, y0: -8, y1: 12 };
  const D = (r, c) => r.b * r.b - 4 * c;
  const n = d => (d > 0 ? 2 : d === 0 ? 1 : 0);
  const ok = (s, r) => n(D(r, s.c)) === r.want;
  const answer = r => { for (let c = -8; c <= 12; c++) if (n(D(r, c)) === r.want) return { c }; return null; };
  const game = roundsGame({
    aspect: 1.2,
    init: r => ({ c: r.want === 1 ? (r.b * r.b) / 4 + 1 : r.want === 0 ? -1 : 12 }),
    ok,
    solution: r => `c = ${answer(r).c}`,
    prompt: r => `Mueve $y = x^2 ${r.b < 0 ? '-' : '+'} ${Math.abs(r.b)}x + c$ para que corte el eje ${r.want === 2 ? 'dos veces' : r.want === 1 ? 'una sola vez' : 'ninguna vez'}`,
    foot: () => 'Arrastra c: la parábola sube o baja',
    layout(G) { G.b = { x: 16, y: 100, w: G.W - 32, h: G.H * 0.5 }; G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, c = G.locked && !ok(G.s, r) ? answer(r).c : G.s.c, d = D(r, c), M = RK.plane(p, C, G.b, V, { step: 2 });
      RK.curve(p, G.b, M, V, x => x * x + r.b * x + c, ok({ c }, r) ? C.ok : C.sky, 2.6);
      if (d >= 0) [(-r.b - Math.sqrt(d)) / 2, (-r.b + Math.sqrt(d)) / 2].forEach(x => drawDot(p, C, M.X(x), M.Y(0), 11, C.coral));
      G.X = RK.track(p, C, 24, G.W - 24, G.tY, 21, c + 8, i => (i % 4 === 0 ? String(i - 8) : null));
      RK.strip(p, C, G.fb, `$\\Delta = ${r.b}^2 - 4\\cdot${c} = ${d}$`, { kicker: d > 0 ? 'positivo: dos cortes' : d === 0 ? 'cero: toca una vez' : 'negativo: ningún corte', col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 18 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.c + 8), y: G.tY }, to: { x: G.X(G.s.c + 4), y: G.tY }, text: 'Arrastra c', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const c = RK.pick(x, 24, G.W - 24, 21) - 8; if (c !== G.s.c || !G.touched[G.cur]) { G.s.c = c; G.touch(); } };
  return Object.assign(game, { answer, D });
})();
;
//#archivo js/games/raices-simetricas.js
// Las raíces a los dos lados del eje (Álgebra, alg-4; spec 2026-11-18-algebra-revision): la fórmula general dice
// x = h ± d, con h = −b/(2a) el eje y d = √Δ/(2|a|) la distancia. Las dos marcas salen del eje a la misma distancia; se
// arrastra d hasta que caigan en los cortes de la parábola.
// params = { rounds: [{ a, b, c }] }   (raíces reales con d múltiplo de 0.5)   state = { rounds: [{ d }] }   (de 0 a 6 de medio en medio)
GAMES['raices-simetricas'] = (() => {
  const V = { x0: -7, x1: 7, y0: -10, y1: 10 };
  const h = r => -r.b / (2 * r.a), need = r => Math.sqrt(r.b * r.b - 4 * r.a * r.c) / (2 * Math.abs(r.a));
  const ok = (s, r) => Math.abs(s.d - need(r)) < 1e-9;
  const poly = r => GAMES['bloques-polinomio'].poly([r.a, r.b, r.c]);
  const game = roundsGame({
    aspect: 1.2,
    init: () => ({ d: 0.5 }),
    ok,
    solution: r => `x = ${h(r)} ± ${need(r)}`,
    prompt: r => `Raíces de $${poly(r)} = 0$: abre las marcas desde el eje`,
    foot: () => 'Arrastra la distancia: las dos marcas se separan igual del eje',
    layout(G) { G.b = { x: 16, y: 100, w: G.W - 32, h: G.H * 0.5 }; G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, d = G.locked && !ok(G.s, r) ? need(r) : G.s.d, M = RK.plane(p, C, G.b, V, { step: 2 }), H = h(r);
      RK.curve(p, G.b, M, V, x => r.a * x * x + r.b * x + r.c, C.sky, 2.6);
      p.stroke(C.brand); p.strokeWeight(1.5); p.drawingContext.setLineDash([5, 4]); p.line(M.X(H), G.b.y, M.X(H), G.b.y + G.b.h); p.drawingContext.setLineDash([]);
      [H - d, H + d].forEach(x => { p.stroke(ok({ d }, r) ? C.ok : C.coral); p.strokeWeight(2.5); p.line(M.X(x), M.Y(0) - 10, M.X(x), M.Y(0) + 10); });
      G.X = RK.track(p, C, 24, G.W - 24, G.tY, 13, d * 2, i => (i % 2 === 0 ? String(i / 2) : null));
      RK.strip(p, C, G.fb, `$x = ${RK.num(H)} \\pm ${RK.num(d)}$`, { kicker: `Eje en x = ${H}`, col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 19 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.d * 2), y: G.tY }, to: { x: G.X(G.s.d * 2 + 4), y: G.tY }, text: 'Arrastra la distancia', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const d = RK.pick(x, 24, G.W - 24, 13) / 2; if (d !== G.s.d || !G.touched[G.cur]) { G.s.d = d; G.touch(); } };
  return Object.assign(game, { need });
})();
;
//#archivo js/games/area-ecuacion.js
// El terreno de área dada (Álgebra, alg-4; spec 2026-11-18-algebra-revision): un rectángulo de lados x y x + m tiene área
// x(x + m): una ecuación cuadrática. Se arrastra x y el rectángulo se llena de cuadritos con su área. Hay que llegar al
// área pedida; la otra raíz de la ecuación es negativa y no sirve como medida.
// params = { rounds: [{ m, area }] }   state = { rounds: [{ x }] }   (de 1 a 15)
GAMES['area-ecuacion'] = (() => {
  const A = (r, x) => x * (x + r.m);
  const need = r => { for (let x = 1; x <= 15; x++) if (A(r, x) === r.area) return x; return -1; };
  const ok = (s, r) => A(r, s.x) === r.area;
  const game = roundsGame({
    aspect: 1.05,
    init: () => ({ x: 1 }),
    ok,
    solution: r => `x = ${need(r)}: ${need(r)} · ${need(r) + r.m} = ${r.area} (la otra raíz, ${-need(r) - r.m}, no es una medida)`,
    prompt: r => `Un terreno mide x por x + ${r.m} y tiene ${r.area} m². ¿Cuánto vale x?`,
    foot: () => 'Arrastra x',
    layout(G) { G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, x = G.locked && !ok(G.s, r) ? need(r) : G.s.x, w = x + r.m, u = Math.min((G.W - 60) / (15 + r.m), (G.tY - 150) / 15);
      p.stroke(C.line); p.strokeWeight(0.6); for (let i = 0; i <= w; i++) p.line(30 + i * u, 108, 30 + i * u, 108 + x * u); for (let j = 0; j <= x; j++) p.line(30, 108 + j * u, 30 + w * u, 108 + j * u);
      p.noFill(); p.stroke(A(r, x) === r.area || G.locked ? C.ok : C.brand); p.strokeWeight(2.5); p.rect(30, 108, w * u, x * u);
      TK.label(p, C, `${x} × ${w} = ${A(r, x)}`, 30 + w * u / 2, 108 + x * u + 14, C.ink, 12, 140);
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, 15, x - 1, i => ((i + 1) % 3 === 0 ? String(i + 1) : null));
      RK.strip(p, C, G.fb, `$x(x + ${r.m}) = ${r.area}\\quad\\to\\quad x^2 + ${r.m}x - ${r.area} = 0$`, { col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 15 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.x - 1), y: G.tY }, to: { x: G.X(G.s.x + 4), y: G.tY }, text: 'Arrastra x', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const v = RK.pick(x, 30, G.W - 30, 15) + 1; if (v !== G.s.x || !G.touched[G.cur]) { G.s.x = v; G.touch(); } };
  return Object.assign(game, { need });
})();
;
//#archivo js/games/bolsas-residuo.js
// Bolsas y sobrantes (Álgebra, alg-23b; spec 2026-11-18-algebra-revision): dividir es empacar. N objetos en bolsas de d:
// se arrastra cuántas bolsas llenar; lo que queda suelto es el residuo, y solo vale si es menor que una bolsa. Así se lee
// dividendo = divisor · cociente + residuo, la misma igualdad de la división de polinomios.
// params = { rounds: [{ N, d }] }   state = { rounds: [{ q }] }   (de 0 a 15)
GAMES['bolsas-residuo'] = (() => {
  const ok = (s, r) => s.q === Math.floor(r.N / r.d);
  const game = roundsGame({
    aspect: 1.05,
    init: () => ({ q: 1 }),
    ok,
    solution: r => `${r.N} = ${r.d} · ${Math.floor(r.N / r.d)} + ${r.N % r.d}`,
    prompt: r => `Empaca ${r.N} en bolsas de ${r.d}: ¿cociente y residuo?`,
    foot: (r, s) => { const res = r.N - r.d * s.q; return res < 0 ? 'No alcanzan para tantas bolsas' : res >= r.d ? 'Sobra para otra bolsa: el residuo debe ser menor que el divisor' : 'El residuo es menor que una bolsa'; },
    layout(G) { G.tY = G.H - 104; G.fb = { x: 12, y: G.H - 68, w: G.W - 24, h: 44 }; },
    enter(G) { G.grab = false; },
    draw(G) {
      const { p, C, r } = G, q = G.locked && !ok(G.s, r) ? Math.floor(r.N / r.d) : G.s.q, res = r.N - r.d * q, cols = 5, bw = (G.W - 40) / cols;
      for (let b = 0; b < Math.min(q, 15); b++) { const x = 20 + (b % cols) * bw, y = 104 + Math.floor(b / cols) * 40; p.stroke(res < 0 && b >= Math.floor(r.N / r.d) ? C.bad : C.line); p.strokeWeight(1.4); p.fill(RK.al(p, C.sky, 70)); p.rect(x + 3, y, bw - 6, 34, 8); TK.label(p, C, String(r.d), x + bw / 2, y + 17, C.ink, 12, bw); }
      const loose = Math.max(0, res);
      for (let i = 0; i < Math.min(loose, 40); i++) { p.noStroke(); p.fill(res >= r.d ? C.coral : C.sun); p.circle(28 + (i % 16) * 17, 238 + Math.floor(i / 16) * 16, 11); }
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, 16, q, i => (i % 3 === 0 ? String(i) : null));
      RK.strip(p, C, G.fb, `$${r.N} = ${r.d}\\cdot${q} + ${res}$`, { kicker: `cociente ${q} · residuo ${res}`, col: G.locked || ok(G.s, r) ? C.ok : C.brand, size: 19 });
    },
    press(G, x, y) { if (Math.abs(y - G.tY) > 30) return false; G.grab = true; game.move(G, x); return true; },
    drag(G, x) { if (!G.grab) return false; game.move(G, x); return true; },
    release(G) { G.grab = false; },
    demo: G => ({ from: { x: G.X(G.s.q), y: G.tY }, to: { x: G.X(G.s.q + 4), y: G.tY }, text: 'Arrastra las bolsas', ty: G.tY - 30 }),
    peek: G => ({ tY: G.tY }),
  });
  game.move = (G, x) => { const q = RK.pick(x, 30, G.W - 30, 16); if (q !== G.s.q || !G.touched[G.cur]) { G.s.q = q; G.touch(); } };
  return game;
})();
;
//#archivo js/games/grado-cociente.js
// Grados en la división (Álgebra, alg-23b; spec 2026-11-18-algebra-revision): si P = D·Q + R, el grado de P es el de D
// más el de Q, y el residuo tiene grado menor que D. Torres de bloques muestran los grados; se arrastra el grado del
// cociente hasta que D y Q apilados igualen a P.
