    demo(G) { const X = G.X; return X ? { from: { x: G.src.x + 22, y: G.src.y + 15 }, to: { x: X(G.r.zeros[0][0]), y: G.L.y }, text: 'Arrastra un cero a la recta', ty: G.src.y + 46 } : null; },
    peek: G => ({ L: G.L, src: G.src }),
