    demo: G => ({ from: { x: G.X[1](0), y: G.tr[1] }, to: { x: G.X[1](3), y: G.tr[1] }, text: 'Arrastra el radicando', ty: G.tr[0] - 34 }),
    peek: G => ({ tr: G.tr }),
