    foot: () => 'Arrastra una barra arriba o abajo; mira las diferencias',
    layout(G) { G.b = { x: 20, y: 110, w: G.W - 40, h: G.H - 210 }; G.fb = { x: 12, y: G.H - 70, w: G.W - 24, h: 46 }; },
