      for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { const k = Math.max(i, j); p.stroke(C.bg); p.strokeWeight(1.2); p.fill(ok(s, r) ? C.ok : k % 2 ? C.coral : C.sky); p.rect(ox + i * c, oy + j * c, c, c, 2); }
