      TK.label(p, C, n <= 6 ? `${terms.join(' + ')} = ${n * n}` : `1 + 3 + … + ${2 * n - 1} = ${n * n}`, G.W / 2, oy + 10 * c + 14, C.ink, 12, G.W - 30);
      G.X = RK.track(p, C, 30, G.W - 30, G.tY, 10, n - 1, i => String(i + 1));
