      p.noFill(); p.stroke(C.coral); p.drawingContext.setLineDash([5, 4]); p.rect(x0 + off * u, yb - r.h * u, s.b * u, r.h * u); p.drawingContext.setLineDash([]);
      p.stroke(C.brand); p.strokeWeight(1.4); p.line(x0 + off * u, yb, x0 + off * u, yb - r.h * u);
