        p.beginShape();
        for (let k = 0; k < 10; k++) { const ang = -Math.PI / 2 + (k * Math.PI) / 5, q = k % 2 ? rad * 0.45 : rad; p.vertex(cx + Math.cos(ang) * q, cy + Math.sin(ang) * q); }
        p.endShape(p.CLOSE);
