      peek: () => ({ phase: a.phase, cur: a.cur, lives: a.lives, W, H, buf, pause, answer: item().answer, keys: keys.map(k => ({ k: k.k, x: k.x + k.w / 2, y: k.y + k.h / 2 })) }),
