  const ansTxt = (it, span) => { const w = wantOf(it, span).map(negTxt); return `${askTxt(it).replace(': ¿qué números x?', '').replace(' = ?', '')} → ${w.length ? w.join(' y ') : (it.kind === 'eq' ? 'ningún real' : 'no es real')}`; };
