//#archivo js/games/tabla-conjugado.js
// La tabla del conjugado (Álgebra, racionalizar; lección alg-22b): para quitar la raíz de un denominador hay que
// multiplicarlo por algo que la haga desaparecer. Se elige por cuál multiplicar y el juego hace la tabla de la
// multiplicación, término por término: se ve qué casillas quedan con raíz y cuáles se cancelan (en el conjugado, las
// dos del medio son opuestas). Se puede probar con todas antes de comprobar.
// Un término es { c, r } = c·√r (r = 1: número sin raíz).
// params = { rounds: [{ den: [término], options: [[término]] }] }   state = { rounds: [{ pick }] }
// Spec 2026-11-15-torres-de-potencias.

GAMES['tabla-conjugado'] = (() => {
  // Producto de dos términos, sacando de la raíz los cuadrados perfectos.
  function mulTerm(a, b) {
    let c = a.c * b.c, r = a.r * b.r;
    for (let f = Math.floor(Math.sqrt(r)); f > 1; f--) if (r % (f * f) === 0) { c *= f; r /= f * f; }
    return { c, r };
  }
  // Suma de términos: junta los de la misma raíz y quita los que dan cero.
  function sumTerms(ts) {
    const by = new Map(); ts.forEach(t => by.set(t.r, (by.get(t.r) || 0) + t.c));
    return [...by.entries()].filter(([, c]) => c !== 0).sort((a, b) => a[0] - b[0]).map(([r, c]) => ({ c, r }));
  }
  const product = (A, B) => sumTerms(A.flatMap(a => B.map(b => mulTerm(a, b))));
  const rational = ts => ts.every(t => t.r === 1);
  const termTxt = t => (t.r === 1 ? negTxt(t.c) : `${t.c === 1 ? '' : t.c === -1 ? '−' : negTxt(t.c)}√${t.r}`);
  const polyTxt = ts => (ts.length ? ts.map((t, i) => (i === 0 ? termTxt(t) : `${t.c < 0 ? '−' : '+'} ${termTxt({ c: Math.abs(t.c), r: t.r })}`)).join(' ') : '0');
  const goodOf = r => r.options.findIndex(o => rational(product(r.den, o)));

  const game = roundsGame({
    aspect: 1.25,
    init: () => ({ pick: -1 }),
    ok: (s, r) => s.pick >= 0 && rational(product(r.den, r.options[s.pick])),
    answered: s => s.pick >= 0,
    solution: r => { const o = r.options[goodOf(r)]; return `(${polyTxt(r.den)})(${polyTxt(o)}) = ${polyTxt(product(r.den, o))}`; },
    prompt: r => `¿Por cuál multiplicas ${polyTxt(r.den)} para quitar la raíz? Prueba y mira la tabla`,
    foot: (r, s) => (s.pick < 0 ? 'Puedes probar todas antes de comprobar' : 'Verde: sin raíz · coral: con raíz'),
    layout(G) { const w = (G.W - 36) / 2; G.opt = [0, 1, 2, 3].map(i => ({ x: 12 + (i % 2) * (w + 12), y: 94 + Math.floor(i / 2) * 44, w, h: 36 })); },
    draw(G) {
      const { p, C, W, s, r } = G;
      r.options.forEach((o, i) => drawTile(p, C, G.opt[i], polyTxt(o), { fill: s.pick === i ? C.sun : C.cream, size: 15, r: 9, lift: 2 }));
      if (s.pick < 0) { p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(13); p.textAlign(p.CENTER, p.CENTER); p.text('Toca una opción para multiplicar', W / 2, 250); return; }
      const B = r.options[s.pick], A = r.den, cw = Math.min(84, (W - 24) / (B.length + 1)), ch = 38, x0 = W / 2 - ((B.length + 1) * cw) / 2, y0 = 196;
      const cell = (i, j, txt, fill, ink) => drawTile(p, C, { x: x0 + j * cw + 2, y: y0 + i * ch + 2, w: cw - 4, h: ch - 6 }, txt, { fill, ink, size: 14, r: 7, lift: fill === C.card ? 0 : 2 });
      cell(0, 0, '×', C.card, C.mute);
      B.forEach((b, j) => cell(0, j + 1, termTxt(b), C.sky));
      A.forEach((a, i) => {
        cell(i + 1, 0, termTxt(a), C.sky);
        B.forEach((b, j) => { const t = mulTerm(a, b); cell(i + 1, j + 1, termTxt(t), t.r === 1 ? C.mint : C.coral); });
      });
      const res = product(A, B), good = rational(res), y = y0 + (A.length + 1) * ch + 22;
      p.noStroke(); p.fill(good ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `(${polyTxt(A)})(${polyTxt(B)}) = ${polyTxt(res)}`, W / 2, y, W - 24, 16);
      p.fill(good ? C.ok : C.bad); p.textSize(12); p.text(good ? 'La raíz desapareció' : 'Todavía queda una raíz', W / 2, y + 22);
    },
    press(G, x, y) {
      const i = G.opt.findIndex((b, k) => k < G.r.options.length && hitBox(b, x, y));
      if (i < 0) return false;
      G.s.pick = i; G.touch();
      return true;
    },
    peek: G => ({ opt: G.opt, good: goodOf(G.r) }),
  });
  return { ...game, mulTerm, sumTerms, product, rational, termTxt, polyTxt, goodOf };
})();
;
//#archivo js/games/muro-radicales.js
// El muro de radicales (Álgebra, radicales semejantes; juego dinámico de la lección alg-22b): cada ladrillo mide
// √n de largo, dibujado a escala. Un ladrillo como √12 trae una costura: son dos ladrillos de √3 pegados (√12 = 2√3).
// (la costura y el color del tipo solo se ven al ponerlo en la fila: el montón es neutro).
// Se tocan ladrillos del montón para ponerlos en fila (tocarlos en la fila los devuelve) hasta que la fila mida lo
// pedido, por ejemplo 4√3. Solo se juntan en un solo radical los ladrillos del mismo tipo: √2 con √3 no se suman.
// No hay reloj. «¡Listo!» comprueba; fallar quita una vida y dice por qué. Sin vidas, la ronda empieza otra vez.
// params = { rounds: [{ title, items: [{ target: { c, r }, bricks: [n, …] }] }], lives? }   state = { done: [n] }
// Spec 2026-11-15-torres-de-potencias.

GAMES['muro-radicales'] = (() => {
  // √n = c·√r, con r sin cuadrados escondidos.
  function simp(n) { let c = 1, r = n; for (let f = Math.floor(Math.sqrt(n)); f > 1; f--) if (r % (f * f) === 0) { c *= f; r /= f * f; } return { c, r }; }
  const radTxt = t => (t.r === 1 ? `${t.c}` : `${t.c === 1 ? '' : t.c}√${t.r}`);
  // Largo total de unos ladrillos: cuántos √r de cada tipo.
  function totalOf(ns) {
    const by = new Map(); ns.forEach(n => { const t = simp(n); by.set(t.r, (by.get(t.r) || 0) + t.c); });
    return [...by.entries()].sort((a, b) => a[0] - b[0]).map(([r, c]) => ({ c, r }));
  }
  const totalTxt = ts => (ts.length ? ts.map(radTxt).join(' + ') : '0');
  function judge(it, ns) {
    const tot = totalOf(ns), g = it.target;
    if (!ns.length) return { ok: false, msg: 'Pon ladrillos en la fila' };
    if (tot.length > 1) return { ok: false, msg: `Hay ladrillos de ${tot.map(t => `√${t.r}`).join(' y de ')}: no se juntan en uno solo` };
    if (tot[0].r !== g.r) return { ok: false, msg: `La fila es de √${tot[0].r} y la meta es de √${g.r}` };
    if (tot[0].c !== g.c) return { ok: false, msg: `Mide ${radTxt(tot[0])}: ${tot[0].c < g.c ? 'le falta' : 'le sobra'}` };
    return { ok: true, msg: `${ns.map(n => `√${n}`).join(' + ')} = ${radTxt(g)}` };
  }
  // Un grupo de ladrillos (sus posiciones) que da la meta, o null.
  function solve(it) {
    for (let mask = 1; mask < 1 << it.bricks.length; mask++) {
      const idx = it.bricks.map((_, i) => i).filter(i => mask & (1 << i));
      if (judge(it, idx.map(i => it.bricks[i])).ok) return idx;
    }
    return null;
  }

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => (state.done?.[i] ?? 0) >= r.items.length);
    return { ok, solution: params.rounds.map(r => r.items.map(it => judge(it, solve(it).map(i => it.bricks[i])).msg).join(' · ')).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const st = { done: R.map(() => 0) };
    let locked = false, W = 0, H = 0, row = [], pause = 0, result = null, btn = {}, pile = [];
    const a = makeArcade(R.length, params.lives ?? 3, api, {
      start(i) { st.done[i] = 0; row = []; pause = 0; result = null; },
      lost(i) { st.done[i] = 0; },
    });
    const round = () => R[a.cur], item = () => round().items[Math.min(st.done[a.cur], round().items.length - 1)];
    const colOf = r => ({ 2: C.sky, 3: C.mint, 5: C.coral, 7: C.sun }[r] || C.Q);
    const unit = () => (W - 28) / 13;

    function layout(w, h) { W = w; H = h; btn = { x: w / 2 - 62, y: h - 60, w: 124, h: 32 }; }
    function boxes(it = item()) { const n = it.bricks.length, per = Math.min(n, 3), bw = Math.min(96, (W - 24) / per - 8); pile = it.bricks.map((_, i) => ({ x: W / 2 - (per * (bw + 8) - 8) / 2 + (i % per) * (bw + 8), y: 262 + Math.floor(i / per) * 46, w: bw, h: 36 })); }
    function check() {
      const it = item(), res = judge(it, row.map(i => it.bricks[i]));
      if (!row.length) { a.say(res.msg, C.sun); return; }
      result = res; pause = res.ok ? 1.6 : 1.3;
      if (res.ok) { st.done[a.cur]++; a.hit(); a.say(res.msg, C.ok); }
      else { a.say(res.msg, C.bad); if (a.miss()) { result = null; pause = 0; row = []; } }
    }
    // Una barra de ladrillos a escala, con la costura de cada ladrillo compuesto.
    function bar(p, ns, y, h, ghost) {
      let x = 14; const u = unit(), cells = [];
      ns.forEach((n, k) => {
        const t = simp(n), len = Math.sqrt(n) * u, w = Math.min(len, W - 14 - x);
        if (w <= 0) return;
        if (ghost) { p.noFill(); p.stroke(C.mute); p.strokeWeight(2); p.drawingContext.setLineDash([5, 5]); p.rect(x, y, w, h, 5); p.drawingContext.setLineDash([]); }
        else {
          p.noStroke(); p.fill(shade(colOf(t.r), 0.74)); p.rect(x, y + 3, w, h, 5); p.fill(colOf(t.r)); p.rect(x, y, w, h, 5);
          p.stroke(C.night); p.strokeWeight(1.5); for (let j = 1; j < t.c; j++) { const sx = x + (j * len) / t.c; if (sx < W - 14) p.line(sx, y + 3, sx, y + h - 3); }
          p.noStroke(); p.fill(inkOn(colOf(t.r), C.ink)); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, `√${n}`, x + w / 2, y + h / 2 + 1, w - 4, 13);
        }
        cells.push({ x, y, w, h, k }); x += len;
      });
      return cells;
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => { layout(size.w, size.h); if (a.stopped) p.redraw(); };

      function step(dt) {
        a.tick(dt);
        if (a.phase !== 'play' || pause <= 0) return;
        pause -= dt;
        if (pause <= 0) { const good = result && result.ok; result = null; if (good) { row = []; if (st.done[a.cur] >= round().items.length) a.win(); } }
      }

      p.draw = () => {
        p.background(C.bg);
        const dt = frameDt(p);
        if (!locked) step(dt * a.slow);
        const r = round(), live = a.phase === 'play', over = locked || a.phase === 'all';
        const it = pause > 0 && result && result.ok ? r.items[Math.max(0, st.done[a.cur] - 1)] : item();

        drawArcadeHead(p, C, a, R.length);
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
        fitText(p, `${r.title} · cada ladrillo mide lo que dice, a escala`, W / 2, 40, W - 24, 11);
        if (live) {
          drawPill(p, C, `Arma una fila que mida ${radTxt(it.target)}`, W / 2, 68, C.sun, 16);
          boxes(it);   // el montón de la pregunta que se ve (mientras se muestra un acierto, la anterior)
          const g = it.target, ns = row.map(i => it.bricks[i]), tot = totalOf(ns);
          p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.LEFT, p.CENTER); p.text('meta', 14, 98);
          bar(p, Array(g.c).fill(g.r), 106, 22, true);
          p.noStroke(); p.fill(C.mute); p.textSize(11); p.textAlign(p.LEFT, p.CENTER); p.text('tu fila', 14, 144);
          G_row = bar(p, ns, 152, 30, false);
          p.noStroke(); p.fill(result ? (result.ok ? C.ok : C.bad) : C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
          fitText(p, ns.length ? `${ns.map(n => `√${n}`).join(' + ')} = ${totalTxt(tot)}` : 'Toca ladrillos del montón para ponerlos en fila', W / 2, 206, W - 24, 15);
          p.fill(C.mute); p.textSize(11); p.text('montón', W / 2, 246);
          it.bricks.forEach((n, i) => { const usedB = row.includes(i), t = simp(n); drawTile(p, C, pile[i], `√${n}`, { fill: usedB ? C.card : C.cream, ink: usedB ? C.mute : undefined, size: 16, r: 9, lift: usedB ? 0 : 3 }); });
          if (pause <= 0) drawTile(p, C, btn, '¡Listo!', { fill: C.mint, size: 15, r: 10, lift: 2 });
        }

        arcadeToast(p, C, a, W / 2, H - 13, locked);
        if (over) drawArcadeSummary(p, C, R.flatMap((rr, i) => rr.items.map(x => ({ ok: st.done[i] >= rr.items.length, text: judge(x, solve(x).map(k => x.bricks[k])).msg }))).slice(0, 8), H / 2);
        else drawArcadeBanner(p, C, a, H / 2 - 20, { idle: 'Sin prisa: mira las costuras de cada ladrillo', lost: 'Varias filas no midieron lo pedido' });
        if (!a.toast && (over || a.phase === 'idle')) {
          p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
          p.text(over ? '¡Muro terminado! Ya puedes comprobar' : 'Solo se juntan los ladrillos del mismo tipo', W / 2, H - 13);
        }
        arcadeStop(p, a, locked);
      };
      let G_row = [];

      p.mousePressed = () => {
        if (!inCanvas(p)) return;
        const tp = a.tap(locked);
        if (tp === 'off') return;
        if (tp !== 'play' || pause > 0) return false;
        const x = p.mouseX, y = p.mouseY;
        if (hitBox({ x: btn.x - 6, y: btn.y - 4, w: btn.w + 12, h: btn.h + 10 }, x, y)) { check(); return false; }
        const i = pile.findIndex(b => hitBox(b, x, y));
        if (i >= 0) { if (row.includes(i)) row = row.filter(k => k !== i); else row.push(i); api.sfx?.tap?.(); return false; }
        const c = G_row.find(b => hitBox(b, x, y));
        if (c) { row.splice(c.k, 1); api.sfx?.tap?.(); return false; }
      };
    }, 1.3);

    return {
      loaded: m.ready,
      getState: () => ({ done: [...st.done] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
      // Para pruebas en el navegador: lo que hay en pantalla en este momento.
      peek: () => { if (a.phase === 'play') boxes(); return { phase: a.phase, cur: a.cur, lives: a.lives, W, H, pause, row: [...row], sol: solve(item()), ok: { x: btn.x + btn.w / 2, y: btn.y + btn.h / 2 }, pile: pile.map(b => ({ x: b.x + b.w / 2, y: b.y + b.h / 2 })) }; },
    };
  }

  return { grade, create, simp, totalOf, judge, solve, radTxt };
})();
;
//#archivo js/games/cuenta-saltos.js
// Saltos, no términos (Álgebra, progresiones; lecciones alg-14, alg-14b y alg-14c): la trampa de siempre es contar
// términos cuando hay que contar saltos. Del término 1 al término n hay n − 1 saltos (como los postes de una cerca).
// Se eligen los saltos con − y + y el juego dibuja los postes y hace la cuenta; los postes no llevan número hasta
// comprobar: contarlos es justo la idea.
//   mode 'value': hay que caer justo en el término pedido (su valor lo calcula el juego).
//   mode 'count': hay que llegar al último número de la lista y decir además cuántos términos son.
// kind 'arit' suma `step` en cada salto; 'geo' multiplica por `step`.
// params = { rounds: [{ kind, mode, a1, step, n? (value), last? (count) }] }   state = { rounds: [{ j, t }] }
// Spec 2026-11-15-escalera-de-sigma.

GAMES['cuenta-saltos'] = (() => {
  const at = (r, j) => (r.kind === 'geo' ? r.a1 * r.step ** j : r.a1 + j * r.step);
  // Saltos que hacen falta: n − 1 para el término n; en 'count', los que llevan del primero al último.
  function jumpsOf(r) {
    if (r.mode === 'value') return r.n - 1;
    for (let j = 0; j <= 40; j++) if (Math.abs(at(r, j) - r.last) < 1e-9) return j;
    return -1;
  }
  const opTxt = r => (r.kind === 'geo' ? `× ${numTxt(r.step)}` : r.step < 0 ? `− ${-r.step}` : `+ ${r.step}`);
  const listTxt = r => `${[0, 1, 2].map(j => numTxt(at(r, j))).join(', ')}, …`;

  const game = roundsGame({
    aspect: 1.15,
    init: () => ({ j: 0, t: 1 }),
    ok: (s, r) => s.j === jumpsOf(r) && (r.mode === 'value' || s.t === s.j + 1),
    solution: r => { const j = jumpsOf(r); return r.mode === 'value' ? `término ${r.n}: ${j} saltos desde ${numTxt(r.a1)} → ${numTxt(at(r, j))}` : `de ${numTxt(r.a1)} a ${numTxt(r.last)} hay ${j} saltos y ${j + 1} términos`; },
    prompt: r => (r.mode === 'value' ? `${listTxt(r)} Da los saltos justos para caer en el término ${r.n}` : `${listTxt(r)} hasta ${numTxt(r.last)}: ¿cuántos saltos y cuántos términos?`),
    foot: r => (r.mode === 'value' ? 'Cuenta los postes: el primero ya está puesto' : 'Entre dos postes hay un salto: cuenta los postes'),
    layout(G) { const w = (G.W - 36) / 2; G.box = [{ x: G.r.mode === 'count' ? 12 : G.W / 2 - w / 2, y: G.H - 66, w, h: 32 }, { x: 24 + w, y: G.H - 66, w, h: 32 }]; },
    enter(G) { const w = (G.W - 36) / 2; G.box[0].x = G.r.mode === 'count' ? 12 : G.W / 2 - w / 2; },
    draw(G) {
      const { p, C, W, H, s, r } = G, n = s.j + 1, show = n, y = 168, x0 = 26, x1 = W - 26;
      const X = i => (show === 1 ? W / 2 : x0 + (i / (show - 1)) * (x1 - x0)), few = show <= 7;
      // Los postes (términos) y los saltos entre ellos.
      p.stroke(C.line); p.strokeWeight(3); p.line(x0 - 8, y + 14, x1 + 8, y + 14);
      for (let i = 0; i < show; i++) {
        if (i > 0) { p.noFill(); p.stroke(C.sky); p.strokeWeight(2); p.arc((X(i - 1) + X(i)) / 2, y - 12, X(i) - X(i - 1), Math.min(40, (X(i) - X(i - 1)) * 0.9), Math.PI, 0); if (few) { p.noStroke(); p.fill(C.sky); p.textStyle(p.BOLD); p.textSize(10); p.textAlign(p.CENTER, p.CENTER); p.text(opTxt(r), (X(i - 1) + X(i)) / 2, y - 12 - Math.min(40, (X(i) - X(i - 1)) * 0.9) / 2 - 8); } }
        const last = i === show - 1;
        p.stroke(last ? C.sun : C.ink); p.strokeWeight(4); p.line(X(i), y - 12, X(i), y + 14);
        p.noStroke(); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
        if (G.locked) { p.fill(last ? C.N : C.mute); p.textSize(few ? 11 : 9); p.text(i + 1, X(i), y + 26); }
        if (few || last || i === 0) { p.fill(last ? C.ink : C.mute); p.textSize(few ? 12 : 10); p.text(numTxt(at(r, i)), X(i), y + 42); }
      }
      p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(16); p.textAlign(p.CENTER, p.CENTER);
      const v = at(r, s.j);
      const word = r.kind === 'geo' ? (s.j === 1 ? 'multiplicación' : 'multiplicaciones') : s.j === 1 ? 'salto' : 'saltos';
      fitText(p, `${s.j} ${word}: llegas a ${numTxt(v)}${G.locked ? `, el término ${n}` : ''}`, W / 2, y + 86, W - 20, 16);
      drawStepper(p, C, G.box[0], s.j, r.kind === 'geo' ? 'multiplicaciones' : 'saltos');
      if (r.mode === 'count') drawStepper(p, C, G.box[1], s.t, 'términos de la lista');
    },
    press(G, x, y) {
      const a = stepHit(G.box[0], x, y), b = G.r.mode === 'count' ? stepHit(G.box[1], x, y) : 0;
      if (!a && !b) return false;
      G.s.j = Math.max(0, Math.min(14, G.s.j + a)); G.s.t = Math.max(1, Math.min(16, G.s.t + b)); G.touch();
      return true;
    },
    peek: G => ({ box: G.box, want: jumpsOf(G.r), mode: G.r.mode }),
  });
  return { ...game, at, jumpsOf };
})();
;
//#archivo js/games/resta-corrida.js
// La resta corrida (Álgebra, suma de una progresión geométrica; lección alg-14d): el truco para sumar
// S = a + ar + ar² + … es multiplicar toda la suma por la razón: sale la misma lista corrida un lugar. Arriba está
// r·S y abajo S, cada término en la columna de su valor. Se tocan las columnas con dos números iguales para tacharlos:
// al restar sobreviven solo el último de arriba y el primero de abajo, y el juego termina la cuenta.
// params = { rounds: [{ a1, r, n }] }   state = { rounds: [{ cut: [bool por pareja] }] }
// Spec 2026-11-15-escalera-de-sigma.

GAMES['resta-corrida'] = (() => {
  const term = (r, k) => r.a1 * r.r ** k;
  const sumOf = r => (term(r, r.n) - r.a1) / (r.r - 1);

  const game = roundsGame({
    aspect: 1.1,
    init: r => ({ cut: Array(r.n - 1).fill(false) }),
    ok: s => s.cut.every(Boolean),
    solution: r => `${r.r}S − S = ${term(r, r.n)} − ${r.a1}, así que S = ${term(r, r.n) - r.a1} ÷ ${r.r - 1} = ${sumOf(r)}`,
    prompt: r => `S = ${[0, 1, 2].map(k => term(r, k)).join(' + ')} + … (${r.n} términos). Tacha las parejas iguales de ${r.r}S y S`,
    foot: (r, s) => (s.cut.every(Boolean) ? 'Solo quedan el último de arriba y el primero de abajo' : 'Al multiplicar por la razón, la lista se corre un lugar'),
    draw(G) {
      const { p, C, W, s, r } = G, cols = r.n + 1, cw = (W - 56) / cols, x0 = 50, yT = 122, yB = 172, done = s.cut.every(Boolean);
      G.cols = [];
      p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(14); p.textAlign(p.RIGHT, p.CENTER);
      p.text(`${r.r}S =`, x0 - 6, yT + 16); p.text('S =', x0 - 6, yB + 16);
      for (let c = 0; c < cols; c++) {
        const x = x0 + c * cw, pair = c >= 1 && c <= r.n - 1, dead = pair && s.cut[c - 1], v = term(r, c);
        G.cols.push({ x, y: yT - 4, w: cw, h: yB + 40 - yT, pair });
        const tile = (y, col) => {
          drawTile(p, C, { x: x + 2, y, w: cw - 4, h: 30 }, v, { fill: dead ? C.card : col, ink: dead ? C.mute : undefined, size: 14, r: 7, lift: dead ? 0 : 2 });
          if (dead) { p.stroke(C.bad); p.strokeWeight(2); p.line(x + 6, y + 26, x + cw - 6, y + 4); }
        };
        if (c >= 1) tile(yT, c === r.n ? C.sun : C.sky);         // r·S ocupa las columnas 1 … n
        if (c <= r.n - 1) tile(yB, c === 0 ? C.sun : C.mint);    // S ocupa las columnas 0 … n − 1
      }
      p.stroke(C.ink); p.strokeWeight(2); p.line(x0 - 34, yB + 44, W - 8, yB + 44);
      p.noStroke(); p.fill(done ? C.ink : C.mute); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      const left = s.cut.filter(c => !c).length;
      fitText(p, done ? `${r.r}S − S = ${term(r, r.n)} − ${r.a1} = ${term(r, r.n) - r.a1}` : `Faltan ${left} ${left === 1 ? 'pareja' : 'parejas'} por tachar`, W / 2, yB + 66, W - 20, 16);
      if (done) {
        if (r.r - 1 > 1) { p.fill(C.ink); fitText(p, `${r.r - 1}S = ${term(r, r.n) - r.a1}`, W / 2, yB + 92, W - 20, 16); }
        p.fill(C.N); fitText(p, `S = ${sumOf(r)}`, W / 2, yB + 120, W - 20, 20);
      }
    },
    press(G, x, y) {
      const c = (G.cols || []).findIndex(b => hitBox(b, x, y));
      if (c < 0) return false;
      if (G.cols[c].pair) { G.s.cut[c - 1] = !G.s.cut[c - 1]; G.touch(); }
      return true;
    },
    peek: G => ({ cols: G.cols }),
  });
  return { ...game, term, sumOf };
})();
;
//#archivo js/games/parte-sigma.js
// Parte la sigma (Álgebra, propiedades de la sumatoria; lección alg-15): la suma Σ (c·k + d) se dibuja columna por
// columna: en la columna k hay c·k piezas azules y d piezas amarillas. Las azules de todas las columnas son c veces
// Σk; las amarillas se repiten una vez por cada k, así que suman d·n (y no d: esa es la trampa). Se escribe la suma
// como «a · Σk + b» eligiendo a y b con − y +.
// params = { rounds: [{ c, d, hi }] }   (k va de 1 a hi)   state = { rounds: [{ a, b }] }
// Spec 2026-11-15-escalera-de-sigma.

GAMES['parte-sigma'] = (() => {
  const termTxt = r => (r.c === 0 ? `${r.d}` : `${r.c === 1 ? '' : r.c}k${r.d ? ` + ${r.d}` : ''}`);
  const gauss = n => (n * (n + 1)) / 2;
  const totalOf = r => r.c * gauss(r.hi) + r.d * r.hi;

  const game = roundsGame({
    aspect: 1.25,
    init: () => ({ a: 0, b: 0 }),
    ok: (s, r) => s.a === r.c && s.b === r.d * r.hi,
    solution: r => `Σ (${termTxt(r)}) = ${r.c}·Σk + ${r.d * r.hi} = ${r.c}·${gauss(r.hi)} + ${r.d * r.hi} = ${totalOf(r)}`,
    prompt: r => `Σ (${termTxt(r)}), con k de 1 a ${r.hi}: sepárala en azules y amarillas`,
    foot: () => 'Las amarillas se repiten una vez por cada valor de k',
    layout(G) { const w = (G.W - 36) / 2; G.box = [{ x: 12, y: G.H - 64, w, h: 32 }, { x: 24 + w, y: G.H - 64, w, h: 32 }]; },
    draw(G) {
      const { p, C, W, H, s, r } = G, n = r.hi, base = H - 150, top = 100, tall = r.c * n + r.d, u = Math.min(16, (base - top) / tall), cw = Math.min(46, (W - 40) / n), x0 = W / 2 - (n * cw) / 2;
      for (let k = 1; k <= n; k++) {
        const x = x0 + (k - 1) * cw + 4, w = cw - 8;
        for (let i = 0; i < r.c * k; i++) { p.noStroke(); p.fill(C.sky); p.rect(x, base - (i + 1) * u + 1, w, u - 2, 3); }
        for (let i = 0; i < r.d; i++) { p.noStroke(); p.fill(C.sun); p.rect(x, base - (r.c * k + i + 1) * u + 1, w, u - 2, 3); }
        p.noStroke(); p.fill(C.mute); p.textStyle(p.BOLD); p.textSize(11); p.textAlign(p.CENTER, p.CENTER); p.text(`k = ${k}`, x + w / 2, base + 12);
      }
      p.stroke(C.ink); p.strokeWeight(2); p.line(x0 - 6, base, x0 + n * cw + 6, base);
      p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
      fitText(p, `Σ (${termTxt(r)}) = ${s.a} · Σk + ${s.b} = ${s.a} · ${gauss(n)} + ${s.b} = ${s.a * gauss(n) + s.b}`, W / 2, base + 38, W - 20, 15);
      drawStepper(p, C, G.box[0], s.a, 'veces Σk (azules)', C.sky);
      drawStepper(p, C, G.box[1], s.b, 'amarillas en total', C.N);
    },
    press(G, x, y) {
      const a = stepHit(G.box[0], x, y), b = stepHit(G.box[1], x, y);
      if (!a && !b) return false;
      G.s.a = Math.max(0, Math.min(9, G.s.a + a)); G.s.b = Math.max(0, Math.min(60, G.s.b + b)); G.touch();
      return true;
    },
    peek: G => ({ box: G.box, want: [G.r.c, G.r.d * G.r.hi] }),
  });
  return { ...game, termTxt, totalOf };
})();
;
//#archivo js/games/arma-notacion.js
// Arma la notación (Álgebra 0, cómo se escribe un conjunto): cada ronda describe un conjunto con palabras
// («los colores de la bandera de Colombia») y hay fichas con el nombre, «=», llaves, comas, elementos y algunas
// trampas («(», «[», elementos que no van). Se tocan las fichas en orden para escribir el conjunto por extensión
// en la pizarra; «⌫» borra la última. Vale cualquier orden de los elementos, pero sin repetir y con las comas
// entre ellos. Las fichas se pueden usar varias veces (las comas se necesitan muchas).
// params = { rounds: [{ prompt, name, members: [etiquetas], chips: [etiquetas] }] }   state = { seqs: [[índice de ficha]] }

GAMES['arma-notacion'] = (() => {
  const SYMS = ['=', '{', '}', ',', '(', ')', '[', ']'];
  // Lee una secuencia de etiquetas como «N = { a , b }»; devuelve { name, elems } o null si la forma está mal.
  function parse(labels) {
    if (labels.length < 4 || labels[1] !== '=' || labels[2] !== '{' || labels[labels.length - 1] !== '}') return null;
    const inner = labels.slice(3, -1), elems = [];
    for (let k = 0; k < inner.length; k++) {
      const isComma = inner[k] === ',';
      if (k % 2 === 1 ? !isComma : isComma || ['=', '{', '}', '(', ')', '[', ']'].includes(inner[k])) return null;
      if (k % 2 === 0) elems.push(inner[k]);
    }
    if (inner.length && inner.length % 2 === 0) return null;   // termina en coma
    return { name: labels[0], elems };
  }
  const labelsOf = (seq, r) => (seq || []).map(i => r.chips[i]);
  function good(seq, r) {
    const p = parse(labelsOf(seq, r));
    return !!p && p.name === r.name && p.elems.length === r.members.length && new Set(p.elems).size === p.elems.length && r.members.every(m => p.elems.includes(m));
  }
  const setText = r => `${r.name} = {${r.members.join(', ')}}`;

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => good(state.seqs?.[i], r));
    return { ok, solution: params.rounds.map(setText).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const st = { seqs: R.map(() => []) };
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], board = null, chipBoxes = [], back = null, pop = { i: -1, t: 0 };

    function layout(w, h) {
      W = w; H = h;
      tabs = roundTabs(R.length, w);
      board = { x: 12, y: 100, w: w - 24, h: 74 };
      back = { x: w - 12 - 56, y: board.y + board.h + 9, w: 56, h: 30 };
      placeChips();
    }
    function placeChips() {
      const chips = R[cur].chips, gap = 7, rowH = 34;
      let x = 12, y = back.y + 44;
      chipBoxes = chips.map(label => {
        const short = SYMS.includes(label) || label.length <= 1;
        const w = short ? 38 : Math.min(W - 24, 26 + label.length * 9);
        if (x + w > W - 12) { x = 12; y += rowH + gap; }
        const b = { x, y, w, h: rowH }; x += w + gap; return b;
      });
    }
    const ready = () => api.ready(st.seqs.every(s => s.length > 0));

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], seq = st.seqs[cur], ok = good(seq, r), labels = labelsOf(seq, r), A = SK.sets(C)[0];
        drawTabs(p, C, tabs, cur, i => (locked ? (good(st.seqs[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : st.seqs[i].length ? C.Z : C.line));
        SK.kicker(p, C, 'Escribe por extensión', 14, 56);
        p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(14); p.textAlign(p.LEFT, p.TOP);
        p.text(r.prompt, 14, 64, W - 28, 36);
        // La pizarra: lo que se va escribiendo, en la franja formal.
        const text = labels.length ? labels.map(l => (l === ',' ? ',' : ` ${l}`)).join('').replace(/\{ /g, '{').replace(/ \}/g, '}').trim() : '';
        SK.panel(p, C, board, { col: locked ? (ok ? C.ok : C.bad) : null });
        p.noStroke(); p.fill(locked ? (ok ? C.ok : C.bad) : A.line); p.rect(board.x + 1, board.y + 10, 3, board.h - 20, 2);
        p.fill(labels.length ? C.ink : C.mute); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
        fitText(p, text || 'Toca las fichas en orden', W / 2, board.y + board.h / 2, board.w - 28, labels.length ? 23 : 13, board.h - 14);
        // Borrar la última ficha
        SK.chip(p, C, back, '⌫', { size: 15, r: 10 });
        p.fill(C.mute); p.textStyle(p.NORMAL); p.textAlign(p.LEFT, p.CENTER);
        fitText(p, 'Las fichas se pueden usar varias veces', 14, back.y + back.h / 2, back.x - 26, 11);
        // Fichas: los signos de la notación, en el color del mundo; los elementos, en píldoras.
        pop.t = Math.max(0, pop.t - 0.08);
        chipBoxes.forEach((b, i) => {
          const lab = r.chips[i], k = pop.i === i ? 1 + 0.12 * pop.t : 1;
          if (SYMS.includes(lab)) drawTile(p, C, b, lab, { fill: C.mint, r: 9, lift: 2, size: 20, k });
          else SK.chip(p, C, b, lab, { size: 14, k });
        });
        p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
        if (locked && !ok) { p.fill(C.ok); fitText(p, `Así: ${setText(r)}`, W / 2, H - 12, W - 24, 12); }
      };

      p.mousePressed = () => {
        const t = tabs.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; placeChips(); api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(back, p.mouseX, p.mouseY)) { st.seqs[cur].pop(); ready(); api.sfx?.tap?.(); return false; }
        const i = chipBoxes.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (i >= 0 && st.seqs[cur].length < 30) { st.seqs[cur].push(i); pop = { i, t: 1 }; ready(); api.sfx?.tap?.(); return false; }
      };
    }, 1.32);

    return {
      loaded: m.ready,
      getState: () => ({ seqs: st.seqs.map(s => [...s]) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, parse };
})();
;
//#archivo js/games/cumple-notacion.js
// Haz que se cumpla (Álgebra 0, pertenece ∈ / no pertenece ∉): arriba hay frases escritas con símbolos,
// como «perro ∈ M» o «pez ∉ M». Abajo está la bolsa del conjunto M y, afuera, las fichas. Tocar una ficha la
// mete a la bolsa o la saca. Meta: que todas las frases sean ciertas. Al lado de cada frase se ve en vivo si ya
// se cumple, para aprender a leer los símbolos.
// params = { rounds: [{ set, tokens: [etiquetas], inside: [bool por ficha] }] }   state = { inside: [[bool]] }

GAMES['cumple-notacion'] = (() => {
  const sentence = (tok, set, inn) => `${tok} ${inn ? '∈' : '∉'} ${set}`;
  const good = (ins, r) => !!ins && r.inside.every((v, k) => ins[k] === v);
  const setText = r => `${r.set} = {${r.tokens.filter((_, k) => r.inside[k]).join(', ')}}`;

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => good(state.inside?.[i], r));
    return { ok, solution: params.rounds.map(setText).join(' · ') };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const st = { inside: R.map(r => r.tokens.map(() => false)) };
    const touched = R.map(() => false);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], bag = null, spots = [], pos = [], fb = null, listH = 0;

    function layout(w, h) {
      W = w; H = h;
      tabs = roundTabs(R.length, w);
      placeAll();
    }
    function placeAll() {
      const r = R[cur], n = r.tokens.length;
      listH = Math.ceil(n / 2) * 26 + 12;
      const top = 48 + listH + 8;
      fb = { x: 12, y: H - 60, w: W - 24, h: 50 };
      const rows = Math.ceil(n / Math.min(4, n)), trayH = rows * 38;
      bag = { x: W / 2, rx: (W - 44) / 2 };
      bag.ry = Math.max(46, (fb.y - 10 - trayH - 8 - top) / 2 - 4); bag.y = top + bag.ry + 4;
      // Lugares dentro de la membrana (dos columnas) y afuera (fila de abajo, dentro del universo).
      const half = Math.ceil(n / 2), step = Math.min(36, (bag.ry * 1.56) / Math.max(1, half));
      const cols = Math.min(4, n), tw = (W - 24 - 16 - (cols - 1) * 6) / cols, y0 = fb.y - 10 - trayH + 4;
      const cw = Math.min(tw, bag.rx * 0.78);
      spots = r.tokens.map((_, k) => ({
        inn: { x: bag.x + (k % 2 ? 1 : -1) * bag.rx * 0.42, y: bag.y + (Math.floor(k / 2) - (half - 1) / 2) * step + 6 },
        out: { x: 20 + (k % cols) * (tw + 6) + tw / 2, y: y0 + Math.floor(k / cols) * 38 + 15 }, w: cw,
      }));
      pos = spots.map((s, k) => ({ ...(st.inside[cur][k] ? s.inn : s.out) }));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], ins = st.inside[cur], dt = frameDt(p), A = locked ? (good(ins, r) ? { line: C.ok, ink: C.ok } : { line: C.bad, ink: C.bad }) : SK.sets(C)[0];
        drawTabs(p, C, tabs, cur, i => (locked ? (good(st.inside[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : touched[i] ? C.Z : C.line));
        // Las frases que deben cumplirse, con su marca.
        SK.panel(p, C, { x: 12, y: 46, w: W - 24, h: listH }, { r: 12 });
        r.tokens.forEach((tok, k) => {
          const x = 24 + (k % 2) * (W - 24) / 2, y = 65 + Math.floor(k / 2) * 26, ok = ins[k] === r.inside[k];
          if (ok) { p.noStroke(); p.fill(C.ok); p.circle(x, y, 9); } else { p.noFill(); p.stroke(C.mute); p.strokeWeight(1.3); p.circle(x, y, 8); p.noStroke(); }
          p.fill(ok ? C.ink : C.mute); p.textStyle(p.BOLD); p.textAlign(p.LEFT, p.CENTER);
          fitText(p, sentence(tok, r.set, r.inside[k]), x + 12, y + 1, (W - 24) / 2 - 30, 14);
        });
        // El universo, con la membrana del conjunto.
        const U = { x: 12, y: 48 + listH + 8, w: W - 24, h: fb.y - 10 - (48 + listH + 8) };
        SK.panel(p, C, U, { u: true });
        SK.membrane(p, C, bag.x, bag.y, bag.rx, bag.ry, A.line);
        SK.tag(p, C, r.set, bag.x - bag.rx * 0.74, bag.y - bag.ry * 0.82, A);
        // Píldoras: se deslizan entre adentro y afuera.
        r.tokens.forEach((tok, k) => {
          const s = spots[k], t = ins[k] ? s.inn : s.out, b = pos[k], bad = locked && ins[k] !== r.inside[k];
          SK.ease(b, 'x', t.x, dt); SK.ease(b, 'y', t.y, dt);
          SK.chip(p, C, { x: b.x - s.w / 2, y: b.y - 13, w: s.w, h: 26 }, tok, { state: bad ? 'bad' : ins[k] ? (locked ? 'ok' : 'on') : 'idle', size: 13 });
        });
        const list = r.tokens.filter((_, k) => ins[k]);
        SK.formal(p, C, fb, SK.setTex(r.set, list), { kicker: 'Así queda escrito', col: A.line, size: 17 });
      };

      p.mousePressed = () => {
        const t = tabs.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; placeAll(); api.sfx?.tap?.(); return false; }
        if (locked) return;
        const ins = st.inside[cur];
        const k = spots.findIndex((s, k) => { const pt = ins[k] ? s.inn : s.out; return Math.abs(p.mouseX - pt.x) < s.w / 2 && Math.abs(p.mouseY - pt.y) < 16; });
        if (k >= 0) { ins[k] = !ins[k]; touched[cur] = true; api.ready(touched.every(Boolean)); api.sfx?.tap?.(); return false; }
      };
    }, 1.45);

    return {
      loaded: m.ready,
      getState: () => ({ inside: st.inside.map(x => [...x]) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, sentence };
})();
;
//#archivo js/games/tacha-repetidos.js
// Tacha los repetidos (Álgebra 0, en un conjunto nada se repite): se escribe una palabra letra por letra y hay
// que tachar (tocar) las letras que sobran para que quede el conjunto de sus letras, cada una una sola vez.
// Abajo se arma en vivo el conjunto con las letras sin tachar y su cardinal n(L). Tocar una letra tachada la
// recupera. Vale dejar cualquier copia de cada letra.
// params = { rounds: [{ word, name }] }   state = { crossed: [[índices tachados]] }

GAMES['tacha-repetidos'] = (() => {
  const distinct = w => [...new Set([...w])];
  function good(cr, r) {
    if (!cr) return false;
    const left = [...r.word].filter((_, i) => !cr.includes(i));
    return left.length === distinct(r.word).length && new Set(left).size === left.length;
  }

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => good(state.crossed?.[i], r));
    const solution = params.rounds.map(r => `${r.name || 'L'} = {${distinct(r.word).join(', ')}}, n = ${distinct(r.word).length}`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const st = { crossed: R.map(() => []) };
    const touched = R.map(() => false);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], cells = [];

    function layout(w, h) {
      W = w; H = h;
      tabs = roundTabs(R.length, w);
      placeCells();
    }
    function placeCells() {
      const n = R[cur].word.length, per = n > 7 ? Math.ceil(n / 2) : n, cw = Math.min(46, (W - 28 - (per - 1) * 6) / per);
      cells = [...R[cur].word].map((_, i) => {
        const row = Math.floor(i / per), inRow = row ? n - per : per, total = inRow * cw + (inRow - 1) * 6;
        return { x: W / 2 - total / 2 + (i % per) * (cw + 6), y: 100 + row * (cw * 1.2 + 9), w: cw, h: cw * 1.2 };
      });
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], cr = st.crossed[cur], ok = good(cr, r), name = r.name || 'L', A = SK.sets(C)[0];
        drawTabs(p, C, tabs, cur, i => (locked ? (good(st.crossed[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : touched[i] ? C.Z : C.line));
        SK.kicker(p, C, 'En un conjunto nada se repite', 14, 56);
        p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER);
        fitText(p, `${name} = {x : x es una letra de ${r.word}}`, W / 2, 80, W - 28, 14);
        // La palabra, letra por letra: en ámbar, la que todavía está repetida; tachada, queda el hueco.
        cells.forEach((b, i) => {
          const off = cr.includes(i), ch = r.word[i], dup = !off && [...r.word].some((c, j) => j !== i && c === ch && !cr.includes(j));
          SK.chip(p, C, b, '', { state: off ? 'ghost' : dup && !locked ? 'on' : 'idle', col: C.sun, r: 9 });
          SK.serif(p, ch, b.x + b.w / 2, b.y + b.h / 2 + 1, Math.min(25, b.w * 0.62), off ? C.mute : C.ink);
          if (off) { p.stroke(C.coral); p.strokeWeight(2); p.line(b.x + 7, b.y + b.h - 7, b.x + b.w - 7, b.y + 7); p.noStroke(); }
        });
        const last = cells[cells.length - 1];
        p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.textAlign(p.CENTER, p.CENTER);
        p.text('Resaltada: esa letra todavía está repetida', W / 2, last.y + last.h + 16);
        // El conjunto que queda, en la franja formal.
        const left = [...r.word].filter((_, i) => !cr.includes(i)), col = locked ? (ok ? C.ok : C.bad) : A.line;
        SK.formal(p, C, { x: 12, y: last.y + last.h + 34, w: W - 24, h: 78 },
          `$${name} = \\{${left.join(', ')}\\} \\quad n(${name}) = ${touched[cur] ? new Set(left).size : '?'}$`, { kicker: 'Lo que queda', col, size: 20 });
        p.textAlign(p.CENTER, p.CENTER);
        if (locked && !ok) { p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, `${name} = {${distinct(r.word).join(', ')}}`, W / 2, H - 14, W - 24, 12); }
        else { p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.text('Toca una letra para tacharla o recuperarla', W / 2, H - 14); }
      };

      p.mousePressed = () => {
        const t = tabs.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (t >= 0) { cur = t; placeCells(); api.sfx?.tap?.(); return false; }
        if (locked) return;
        const i = cells.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (i >= 0) {
          const cr = st.crossed[cur], k = cr.indexOf(i);
          if (k >= 0) cr.splice(k, 1); else cr.push(i);
          touched[cur] = true; api.ready(touched.every(Boolean)); api.sfx?.tap?.(); return false;
        }
      };
    }, 1.4);

    return {
      loaded: m.ready,
      getState: () => ({ crossed: st.crossed.map(c => [...c]) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, distinct };
})();
;
//#archivo js/games/recta-espejo.js
// La recta del espejo (Álgebra 1.1, enteros y opuestos): una recta de enteros con un espejo en el 0. Cada ronda
// describe un número con palabras o con notación («el opuesto de 5», «−(−3)», «el número que sumado con 6 da 0»).
// Se toca o se arrastra sobre la recta para poner el punto (se ajusta a enteros) y al otro lado del espejo aparece
// su reflejo (sin número, para que el estudiante lo razone). Califica el entero exacto.
// params = { min, max, rounds: [{ text, value }] }   state = { xs: [entero | null] }

GAMES['recta-espejo'] = (() => {
  const snap = (v, min, max) => Math.min(max, Math.max(min, Math.round(v)));
  const neg = v => String(v).replace('-', '−');

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => state.xs?.[i] === r.value);
    const solution = params.rounds.map(r => `${r.text}: ${neg(r.value)}`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds, min = params.min, max = params.max;
    const st = { xs: R.map(() => null) };
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], line = null, drag = false, t = 0;

    function layout(w, h) {
      W = w; H = h;
      tabs = roundTabs(R.length, w);
      line = { x0: 22, x1: w - 22, y: h * 0.66 };
    }
    const X = v => line.x0 + (v - min) / (max - min) * (line.x1 - line.x0);
    const V = px => min + (px - line.x0) / (line.x1 - line.x0) * (max - min);
    function setX(px) { st.xs[cur] = snap(V(px), min, max); api.ready(st.xs.every(x => x != null)); }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        t += 0.05;
        const r = R[cur], x = st.xs[cur], ok = x === r.value;
        drawTabs(p, C, tabs, cur, i => (locked ? (st.xs[i] === R[i].value ? C.ok : C.bad) : i === cur ? C.brand : st.xs[i] != null ? C.Z : C.line));
        drawKicker(p, C, 'Pon en la recta', W / 2, 58, { center: true });
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.CENTER); fitText(p, r.text, W / 2, 86, W - 28, 21);
        // Espejo en el 0
        const z = X(0);
        p.stroke(C.sun); p.strokeWeight(2.5); p.drawingContext.setLineDash([5, 6]); p.line(z, line.y - 68, z, line.y - 12); p.drawingContext.setLineDash([]);
        drawPill(p, C, 'espejo', z, line.y - 80, C.sun, 11);
        // Recta y marcas
        drawNumLine(p, C, { x0: line.x0, x1: line.x1, y: line.y, min, max });
        if (x != null) {
          // Reflejo (el opuesto), tenue, al otro lado del espejo
          if (x !== 0) {
            const c = p.color(C.mute); c.setAlpha(140);
            p.noFill(); p.stroke(c); p.strokeWeight(2); p.circle(X(-x), line.y, 16);
            p.noStroke(); p.fill(C.mute); p.textSize(11); p.textStyle(p.NORMAL);
            const tw = p.textWidth('reflejo') / 2 + 4;
            p.text('reflejo', Math.min(W - tw, Math.max(tw, X(-x))), line.y - 24);
            p.stroke(c); p.strokeWeight(1); p.drawingContext.setLineDash([3, 4]);
            p.noFill(); p.arc(z, line.y, Math.abs(X(x) - X(-x)), 50, Math.PI, 2 * Math.PI); p.drawingContext.setLineDash([]);
          }
          const pc = locked ? (ok ? C.ok : C.bad) : x < 0 ? C.coral : x > 0 ? C.sky : C.sun;
          drawDot(p, C, X(x), line.y, 18 + 2 * Math.sin(t), pc);
          drawPill(p, C, neg(x), X(x), line.y - 44, pc, 15);
        }
        p.noStroke(); p.textStyle(p.NORMAL); p.textSize(12);
        if (locked && !ok) { p.noFill(); p.stroke(C.ok); p.strokeWeight(3); p.circle(X(r.value), line.y, 22); p.noStroke(); }
        if (locked && !ok) { p.fill(C.ok); p.textStyle(p.BOLD); p.text(`Era ${neg(r.value)}`, W / 2, H - 16); }
        else { p.fill(C.mute); p.text('Toca o arrastra sobre la recta', W / 2, H - 16); }
      };

      p.mousePressed = () => {
        const tb = tabs.findIndex(b => hitBox(b, p.mouseX, p.mouseY));
        if (tb >= 0) { cur = tb; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (Math.abs(p.mouseY - line.y) < 60) { drag = true; setX(p.mouseX); api.sfx?.tap?.(); return false; }
      };
      p.mouseDragged = () => { if (drag && !locked) { setX(p.mouseX); return false; } };
      p.mouseReleased = () => { drag = false; };
    }, 1.25);

    return {
      loaded: m.ready,
      getState: () => ({ xs: [...st.xs] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, snap };
})();
;
//#archivo js/games/inversos-gemelos.js
// Los inversos gemelos (Álgebra 1.2, axiomas de campo: opuesto y recíproco). Cada ronda trae un número y la
// máquina opera con su «gemelo», que el estudiante arma con un botón de signo, ruedas − / + para el numerador y el
// denominador y un interruptor √ (para raíces como √6). Con + la meta es el neutro 0 (el opuesto); con × la meta
// es el neutro 1 (el recíproco). El 0 no tiene recíproco: para él está el botón «no tiene». La máquina muestra el
// resultado en vivo. Cualquier fracción equivalente vale.
// params = { op: '+' | '×', rounds: [{ label, v, sol }] }   state = { ans: [{ s, n, d, r, none } | null] }

GAMES['inversos-gemelos'] = (() => {
  const valueOf = a => a.s * (a.r ? Math.sqrt(a.n) : a.n) / a.d;
  const close = (x, y) => Math.abs(x - y) < 1e-9;

  function okRound(a, r, op) {
    if (!a) return false;
    if (op === '×' && r.v === 0) return !!a.none;
    if (a.none) return false;
    return op === '+' ? close(r.v + valueOf(a), 0) : close(r.v * valueOf(a), 1);
  }

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.ans?.[i], r, params.op));
    const word = params.op === '+' ? 'opuesto' : 'recíproco';
    const solution = params.rounds.map(r => `${word} de ${r.label}: ${r.sol}`).join(' · ');
    return { ok, solution };
  }

  const txt = a => {
    if (a.none) return 'no tiene';
    const num = (a.r ? '√' : '') + a.n;
    return (a.s < 0 ? '−' : '') + (a.d === 1 ? num : `${num}/${a.d}`);
  };
  const show = v => {
    const k = Math.round(v * 1e6) / 1e6;
    return Math.abs(k - Math.round(k)) < 1e-9 ? String(Math.round(k)).replace('-', '−') : `≈ ${numTxt(+k.toFixed(3))}`;
  };

  function create(host, params, api) {
    const C = api.palette, R = params.rounds, op = params.op, mul = op === '×';
    const A = R.map(() => ({ s: 1, n: 0, d: 1, r: false, none: false, touched: false }));
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], B = {}, shake = 0;

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      const cx = w / 2, bw = 44, bh = 36;
      B = {
        nMinus: { x: cx - 92, y: 148, w: bw, h: bh }, nPlus: { x: cx + 48, y: 148, w: bw, h: bh },
        dMinus: { x: cx - 92, y: 206, w: bw, h: bh }, dPlus: { x: cx + 48, y: 206, w: bw, h: bh },
        sign: { x: cx - 100, y: 258, w: 92, h: 34 },
        root: { x: cx + 8, y: 258, w: 92, h: 34 },
        none: mul ? { x: cx - 92, y: 304, w: 184, h: 34 } : null,
      };
    }
    function touch(f) {
      if (locked) return;
      const a = A[cur]; f(a); a.touched = true;
      api.ready(A.every(x => x.touched)); api.sfx?.tap?.();
    }
    function button(b, label, on, col) {
      if (!b) return;
      // Ficha con relieve: crema apagada, de su color cuando está activa; los − / + van en azul.
      drawTile(p5i, C, b, label, { fill: on ? col : label === '−' || label === '+' ? C.sky : C.cream, r: 9, lift: on ? 1 : 3, size: 16 });
    }
    let p5i = null;

    const m = mountSketch(host, (p, size) => {
      p5i = p;
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], a = A[cur], good = okRound(a, r, op);
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound(A[i], R[i], op) ? C.ok : C.bad) : i === cur ? C.brand : A[i].touched ? C.Q : C.line));
        drawKicker(p, C, mul ? 'El gemelo que al multiplicar da 1' : 'El gemelo que al sumar da 0', W / 2, 56, { center: true });
        p.textAlign(p.CENTER, p.CENTER); p.noStroke();
        // La máquina: número ⊕ gemelo = resultado
        const sx = shake > 0 ? Math.sin(shake * 2) * 4 : 0; shake = Math.max(0, shake - 1);
        p.stroke(locked ? (good ? C.ok : C.bad) : C.sun); p.strokeWeight(2.5); p.fill(C.card); p.rect(12 + sx, 74, W - 24, 58, 14);
        const eq = `${r.label}  ${op}  ${a.none ? '?' : `(${txt(a)})`}`;
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); fitText(p, eq, W / 2 + sx, 94, W - 40, 19);
        let res = '';
        if (a.none) res = mul && r.v === 0 ? '0 · lo que sea = 0, nunca 1' : 'sí tiene: búscalo';
        else res = '= ' + show(mul ? r.v * valueOf(a) : r.v + valueOf(a));
        p.fill(locked ? (good ? C.ok : C.bad) : C.mute); p.textStyle(p.NORMAL); fitText(p, res, W / 2 + sx, 117, W - 40, 13);
        // El constructor del gemelo
        const cx = W / 2;
        button(B.sign, a.s < 0 ? 'signo  −' : 'signo  +', a.s < 0, C.Z);
        button(B.root, a.r ? 'con √' : 'sin √', a.r, C.I);
        button(B.nMinus, '−', false); button(B.nPlus, '+', false); button(B.dMinus, '−', false); button(B.dPlus, '+', false);
        p.noStroke(); p.fill(a.none ? C.mute : C.ink); p.textStyle(p.BOLD); p.textSize(24);
        p.text((a.r ? '√' : '') + a.n, cx, 166);
        p.stroke(a.none ? C.line : C.ink); p.strokeWeight(2.5); p.line(cx - 30, 195, cx + 30, 195);
        p.noStroke(); p.text(a.d, cx, 224);
        if (B.none) button(B.none, 'no tiene recíproco', a.none, C.R);
        p.noStroke(); p.textStyle(p.NORMAL); p.textSize(12);
        if (locked && !good) { p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, `Era: ${r.sol}`, W / 2, H - 18, W - 24, 13); }
        else { p.fill(C.mute); fitText(p, mul ? 'Recíproco: a · (1/a) = 1' : 'Opuesto: a + (−a) = 0', W / 2, H - 18, W - 24, 12); }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(B.sign, x, y)) { touch(a => { a.s = -a.s; a.none = false; }); return false; }
        if (hitBox(B.root, x, y)) { touch(a => { a.r = !a.r; a.none = false; }); return false; }
        if (hitBox(B.nMinus, x, y)) { touch(a => { a.n = Math.max(0, a.n - 1); a.none = false; }); return false; }
        if (hitBox(B.nPlus, x, y)) { touch(a => { a.n = Math.min(20, a.n + 1); a.none = false; }); return false; }
        if (hitBox(B.dMinus, x, y)) { touch(a => { a.d = Math.max(1, a.d - 1); a.none = false; }); return false; }
        if (hitBox(B.dPlus, x, y)) { touch(a => { a.d = Math.min(20, a.d + 1); a.none = false; }); return false; }
        if (B.none && hitBox(B.none, x, y)) { touch(a => { a.none = !a.none; }); if (A[cur].none && R[cur].v !== 0) shake = 12; return false; }
      };
    }, 1.48);

    return {
      loaded: m.ready,
      getState: () => ({ ans: A.map(a => (a.touched ? { s: a.s, n: a.n, d: a.d, r: a.r, none: a.none } : null)) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, valueOf };
})();
;
//#archivo js/games/corta-rectangulo.js
// Corta el rectángulo (Álgebra 1.2, propiedad distributiva). Un rectángulo de h × w cuadritos tiene área h · w.
// Se arrastra un corte vertical (salta de cuadrito en cuadrito) para partirlo en dos piezas, y debajo aparece
// h · w = h · k + h · (w − k): la distributiva vista como áreas. La meta de cada ronda es que una de las dos piezas
// tenga el área pedida (una pieza «redonda» que hace fácil la cuenta de cabeza).
// params = { rounds: [{ h, w, piece }] }   state = { cuts: [k | null] }

GAMES['corta-rectangulo'] = (() => {
  const okRound = (k, r) => k != null && k > 0 && k < r.w && (r.h * k === r.piece || r.h * (r.w - k) === r.piece);

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.cuts?.[i], r));
    const solution = params.rounds.map(r => {
      const k = r.piece / r.h;
      return `${r.h} · ${r.w} = ${r.h} · ${k} + ${r.h} · ${r.w - k} = ${r.piece} + ${r.h * (r.w - k)} = ${r.h * r.w}`;
    }).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const cuts = R.map(() => null);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], box = null, drag = false, bm = null, bp = null;

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      const r = R[cur], u = Math.min((w - 48) / r.w, 150 / r.h);
      box = { x: (w - u * r.w) / 2, y: 112, u, w: u * r.w, h: u * r.h };
      bm = { x: w / 2 - 98, y: h - 62, w: 44, h: 36 }; bp = { x: w / 2 + 54, y: h - 62, w: 44, h: 36 };
    }
    function setCut(px) {
      const r = R[cur];
      cuts[cur] = Math.min(r.w - 1, Math.max(1, Math.round((px - box.x) / box.u)));
      api.ready(cuts.every(k => k != null));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], k = cuts[cur], good = okRound(k, r), b = box;
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound(cuts[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : cuts[i] != null ? C.Q : C.line));
        p.textAlign(p.CENTER, p.CENTER); p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
        fitText(p, `Calcula ${r.h} · ${r.w} partiendo el rectángulo`, W / 2, 56, W - 24, 15);
        p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, `Una de las piezas debe tener área ${r.piece}`, W / 2, 78, W - 24, 12);
        // Piezas
        const kx = k == null ? null : b.x + k * b.u;
        p.noStroke();
        if (k == null) { p.fill(C.card); p.rect(b.x, b.y, b.w, b.h); }
        else {
          // Dos piezas rellenas: menta y sol.
          p.fill(C.mint); p.rect(b.x, b.y, kx - b.x, b.h); p.fill(C.sun); p.rect(kx, b.y, b.x + b.w - kx, b.h);
        }
        // Cuadrícula
        p.stroke(k == null ? C.line : C.night + '40'); p.strokeWeight(b.u > 7 ? 1 : 0.5);
        for (let i = 1; i < r.w; i++) p.line(b.x + i * b.u, b.y, b.x + i * b.u, b.y + b.h);
        for (let j = 1; j < r.h; j++) p.line(b.x, b.y + j * b.u, b.x + b.w, b.y + j * b.u);
        p.noFill(); p.stroke(C.ink); p.strokeWeight(2); p.rect(b.x, b.y, b.w, b.h);
        // Medidas
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(13);
        p.text(r.h, b.x - 12, b.y + b.h / 2);
        if (k == null) { p.text(r.w, b.x + b.w / 2, b.y - 12); }
        else {
          p.fill(C.Q); p.text(k, (b.x + kx) / 2, b.y - 12); p.fill(C.N); p.text(r.w - k, (kx + b.x + b.w) / 2, b.y - 12);
          p.stroke(locked ? (good ? C.ok : C.bad) : C.brand); p.strokeWeight(3.5); p.line(kx, b.y - 4, kx, b.y + b.h + 4);
          drawDot(p, C, kx, b.y + b.h + 12, 16, locked ? (good ? C.ok : C.bad) : C.brand);
          // Áreas dentro de cada pieza (si caben)
          p.noStroke(); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); p.textSize(14);
          if (kx - b.x > 26) { p.fill(inkOn(C.mint, C.ink)); p.text(r.h * k, (b.x + kx) / 2, b.y + b.h / 2); }
          if (b.x + b.w - kx > 26) { p.fill(inkOn(C.sun, C.ink)); p.text(r.h * (r.w - k), (kx + b.x + b.w) / 2, b.y + b.h / 2); }
        }
        // La distributiva
        const y0 = b.y + b.h + 40;
        p.noStroke(); p.textStyle(p.BOLD);
        if (k == null) { p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'Toca o arrastra sobre el rectángulo para cortarlo', W / 2, y0, W - 24, 12); }
        else {
          p.fill(C.ink); fitText(p, `${r.h} · ${r.w} = ${r.h} · ${k} + ${r.h} · ${r.w - k}`, W / 2, y0, W - 24, 16);
          p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, `= ${r.h * k} + ${r.h * (r.w - k)} = ${r.h * r.w}`, W / 2, y0 + 24, W - 24, 14);
        }
        if (!locked) for (const [bb, t] of [[bm, '−'], [bp, '+']]) {
          drawTile(p, C, bb, t, { fill: C.sky, r: 9, lift: 2, size: 18 });
        }
        if (!locked) { p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(11); p.text('mover el corte', W / 2, H - 44); }
        if (locked && !good) { p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, `Cortar en ${r.piece / r.h}: pieza de ${r.piece}`, W / 2, H - 30, W - 24, 12); }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(t => hitBox(t, x, y));
        if (tb >= 0) { cur = tb; layout(W, H); api.sfx?.tap?.(); return false; }
        if (locked) return;
        const step = d => { const rr = R[cur]; cuts[cur] = Math.min(rr.w - 1, Math.max(1, (cuts[cur] ?? Math.floor(rr.w / 2)) + d)); api.ready(cuts.every(k => k != null)); api.sfx?.tap?.(); };
        if (hitBox(bm, x, y)) { step(-1); return false; }
        if (hitBox(bp, x, y)) { step(1); return false; }
        if (x > box.x - 10 && x < box.x + box.w + 10 && y > box.y - 24 && y < box.y + box.h + 26) { drag = true; setCut(x); api.sfx?.tap?.(); return false; }
      };
      p.mouseDragged = () => { if (drag && !locked) { setCut(p.mouseX); return false; } };
      p.mouseReleased = () => { drag = false; };
    }, 1.6);

    return {
      loaded: m.ready,
      getState: () => ({ cuts: [...cuts] }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/cancela-balanza.js
// La balanza que cancela (Álgebra 1.2, ley cancelativa). Una igualdad es una balanza en equilibrio: a cada lado hay
// fichas que se suman (o se multiplican). Se toca una ficha de la izquierda y luego una igual de la derecha: las dos
// se van, porque quitar lo mismo de los dos lados mantiene el equilibrio (a + b = a + c ⇒ b = c; con productos,
// ab = ac y a ≠ 0 ⇒ b = c). Un 0 que multiplica no se deja cancelar (0 · 2 = 0 · 5 y 2 ≠ 5). Se gana cuando a la
// izquierda queda la x sola.
// params = { rounds: [{ op: '+' | '·', left: [texto], right: [texto], ans }] }   state = { pairs: [[[i, j], …] por ronda] }

GAMES['cancela-balanza'] = (() => {
  const canCancel = (r, i, j) => r.left[i] != null && r.left[i] !== 'x' && r.left[i] === r.right[j] && !(r.op === '·' && r.left[i] === '0');

  function solved(r, pairs) {
    if (!Array.isArray(pairs)) return false;
    const L = new Set(), Rr = new Set();
    for (const pr of pairs) {
      const [i, j] = pr || [];
      if (L.has(i) || Rr.has(j) || !canCancel(r, i, j)) return false;
      L.add(i); Rr.add(j);
    }
    return r.left.every((t, i) => (t === 'x') !== L.has(i));
  }

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => solved(r, state.pairs?.[i]));
    return { ok, solution: params.rounds.map(r => r.ans).join(' · ') };
  }

  const expr = (tiles, op) => tiles.map((t, k) => (k && t.startsWith('−') ? `(${t})` : t)).join(` ${op} `) || (op === '+' ? '0' : '1');

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const P = R.map(() => []);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], sel = null, msg = '', msgT = 0, boxes = { L: [], R: [] }, reset = null;

    function layout(w, h) { W = w; H = h; tabs = roundTabs(R.length, w); reset = { x: w / 2 - 50, y: h - 46, w: 100, h: 30 }; }
    const goneL = () => new Set(P[cur].map(p => p[0]));
    const goneR = () => new Set(P[cur].map(p => p[1]));
    function say(t) { msg = t; msgT = 150; }

    function placeTiles(side, tiles, gone, x0, x1, y0) {
      const out = [], tw = Math.min(54, (x1 - x0 - 6) / 2), th = 30;
      let col = 0, row = 0;
      tiles.forEach((t, i) => {
        if (gone.has(i)) { out.push(null); return; }
        out.push({ x: x0 + 3 + col * (tw + 6), y: y0 - (row + 1) * (th + 6), w: tw, h: th, t, i });
        if (++col === 2) { col = 0; row++; }
      });
      return out;
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], gL = goneL(), gR = goneR(), done = solved(r, P[cur]);
        drawTabs(p, C, tabs, cur, i => (locked ? (solved(R[i], P[i]) ? C.ok : C.bad) : i === cur ? C.brand : P[i].length ? C.Q : C.line));
        // La igualdad que queda
        const left = r.left.filter((_, i) => !gL.has(i)), right = r.right.filter((_, j) => !gR.has(j));
        p.textAlign(p.CENTER, p.CENTER); p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
        fitText(p, `${expr(left, r.op)} = ${expr(right, r.op)}`, W / 2, 58, W - 24, 18);
        // Balanza en equilibrio
        const beamY = H * 0.6, cx = W / 2;
        p.stroke(C.ink); p.strokeWeight(5); p.line(18, beamY, W - 18, beamY);
        p.noStroke(); p.fill(C.sun); p.triangle(cx, beamY, cx - 20, beamY + 40, cx + 20, beamY + 40);
        p.fill(C.card); p.stroke(C.line); p.strokeWeight(1.5);
        p.rect(14, beamY - 2, cx - 26, 8, 4); p.rect(cx + 12, beamY - 2, cx - 26, 8, 4);
        boxes.L = placeTiles('L', r.left, gL, 14, cx - 12, beamY - 4);
        boxes.R = placeTiles('R', r.right, gR, cx + 12, W - 14, beamY - 4);
        for (const [side, list] of [['L', boxes.L], ['R', boxes.R]]) for (const b of list) {
          if (!b) continue;
          const isX = b.t === 'x', on = side === 'L' && sel === b.i;
          // Fichas crema; la x, color sol; la elegida lleva aro.
          drawTile(p, C, b, b.t, { fill: isX ? C.sun : C.cream, r: 8, lift: 2, size: 15, ring: on ? C.brand : null });
        }
        p.noStroke(); p.textStyle(p.NORMAL); p.fill(C.mute); p.textSize(11);
        p.text(r.op === '+' ? 'fichas que se suman' : 'fichas que se multiplican', W / 2, beamY + 56);
        // Mensajes
        if (msgT > 0) { msgT--; p.fill(C.bad); p.textStyle(p.BOLD); fitText(p, msg, W / 2, 86, W - 24, 12); }
        else if (done) drawPill(p, C, '¡La x quedó sola!', W / 2, 86, locked ? C.ok : C.mint, 13);
        else { p.fill(C.mute); fitText(p, sel == null ? 'Toca una ficha de la izquierda…' : '…y luego su gemela de la derecha', W / 2, 86, W - 24, 12); }
        if (locked && !done) { p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, `Quedaba ${r.ans}`, W / 2, H - 31, W - 24, 13); }
        else if (!locked) {
          drawTile(p, C, reset, 'Reiniciar', { r: 8, lift: 2, size: 12 });
        }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY, r = R[cur];
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; sel = null; msgT = 0; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(reset, x, y)) { P[cur] = []; sel = null; api.ready(R.every((rr, i) => P[i].length > 0)); return false; }
        const bl = boxes.L.find(b => b && hitBox(b, x, y));
        if (bl) {
          if (bl.t === 'x') say('La x es la que queremos dejar sola');
          else if (r.op === '·' && bl.t === '0') say('El 0 no se cancela: 0 · 2 = 0 · 5 y 2 ≠ 5');
          else { sel = bl.i; api.sfx?.tap?.(); }
          return false;
        }
        const br = boxes.R.find(b => b && hitBox(b, x, y));
        if (br) {
          if (sel == null) { say('Empieza por una ficha de la izquierda'); return false; }
          if (canCancel(r, sel, br.i)) { P[cur].push([sel, br.i]); sel = null; api.sfx?.tap?.(); api.ready(R.every((rr, i) => P[i].length > 0)); }
          else say('Solo se quitan dos fichas iguales');
          return false;
        }
      };
    }, 1.2);

    return {
      loaded: m.ready,
      getState: () => ({ pairs: P.map(l => l.map(pr => [...pr])) }),
      lock() { locked = true; sel = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, canCancel };
})();
;
//#archivo js/games/tren-ordenado.js
// El tren ordenado (Álgebra 1.3, axiomas de orden). Cada ronda trae un tren de vagones con números reales
// (enteros, fracciones, decimales, raíces, π) en desorden. Se arrastra cada vagón a su lugar para que el tren
// quede de menor a mayor, de izquierda a derecha como en la recta. a < b quiere decir que b − a es positivo:
// b va más a la derecha. Al comprobar aparecen los signos < entre vagones.
// params = { rounds: [{ items: [{ label, v }] }] }   state = { orders: [[índice de item, …] por ronda] }

GAMES['tren-ordenado'] = (() => {
  const sorted = order => order.every((v, k) => k === 0 || order[k - 1] < v);

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => {
      const o = state.orders?.[i];
      return Array.isArray(o) && o.length === r.items.length && new Set(o).size === o.length && o.every(k => r.items[k]) && sorted(o.map(k => r.items[k].v));
    });
    const solution = params.rounds.map(r => [...r.items].sort((a, b) => a.v - b.v).map(it => it.label).join(' < ')).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const O = R.map((r, i) => shuffledOrder(r.items.length, `tren${i}${r.items.map(t => t.label).join()}`));
    const moved = R.map(() => false);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], drag = null, slot = { w: 0, y: 0 };

    function layout(w, h) { W = w; H = h; tabs = roundTabs(R.length, w); }
    const geo = () => { const n = R[cur].items.length, sw = (W - 20) / n; return { n, sw, ww: sw - 8, y: H * 0.56 }; };
    const slotX = k => { const g = geo(); return 10 + k * g.sw + 4; };

    function wagon(p, x, y, w, label, col, lifted) {
      const h = 40;
      // Vagón: bloque crema con relieve (color sol al levantarlo), techo del color del estado y ruedas con centro sol.
      drawTile(p, C, { x, y: y - h, w, h: h - 3 }, '', { fill: lifted ? C.sun : C.cream, r: 7, lift: 3, ring: lifted ? C.sun : null });
      p.noFill(); p.stroke(col); p.strokeWeight(2); p.rect(x, y - h, w, h - 3, 7);   // borde: en el tema claro el vagón crema casi no se distingue del papel
      p.noStroke(); p.fill(col); p.rect(x, y - h, w, 7, 7, 7, 0, 0);
      p.fill(C.ink); p.circle(x + w * 0.25, y + 5, 13); p.circle(x + w * 0.75, y + 5, 13);
      p.fill(C.sun); p.circle(x + w * 0.25, y + 5, 5); p.circle(x + w * 0.75, y + 5, 5);
      p.fill(inkOn(lifted ? C.sun : C.cream, C.ink)); p.textAlign(p.CENTER, p.CENTER); p.textStyle(p.BOLD); fitText(p, label, x + w / 2, y - h / 2 + 3, w - 6, 16);
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], o = O[cur], g = geo(), good = sorted(o.map(k => r.items[k].v));
        drawTabs(p, C, tabs, cur, i => (locked ? (sorted(O[i].map(k => R[i].items[k].v)) ? C.ok : C.bad) : i === cur ? C.brand : moved[i] ? C.R : C.line));
        drawKicker(p, C, 'Ordena el tren de menor a mayor', W / 2, 58, { center: true });
        p.textAlign(p.CENTER, p.CENTER); p.noStroke();
        p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'Arrastra cada vagón a su lugar', W / 2, 80, W - 24, 12);
        // Riel
        p.stroke(C.mute); p.strokeWeight(3); p.line(6, g.y + 12, W - 6, g.y + 12);
        for (let x = 12; x < W; x += 16) { p.strokeWeight(2); p.line(x, g.y + 12, x - 4, g.y + 18); }
        // Vagones
        o.forEach((k, pos) => {
          if (drag && drag.k === k) return;
          const col = locked ? (good ? C.ok : C.bad) : C.R;
          wagon(p, slotX(pos), g.y, g.ww, r.items[k].label, col, false);
          if (pos > 0) {
            p.noStroke(); p.fill(locked ? (good ? C.ok : C.mute) : C.line); p.textStyle(p.BOLD); p.textSize(14);
            p.text(locked && good ? '<' : '•', slotX(pos) - 4, g.y - 20);
          }
        });
        if (drag) wagon(p, drag.x - g.ww / 2, g.y - 18, g.ww, r.items[drag.k].label, C.brand, true);
        // Recta-guía: menor a la izquierda, mayor a la derecha
        const yy = g.y + 52;
        p.stroke(C.mute); p.strokeWeight(1.5); p.line(30, yy, W - 30, yy);
        p.noStroke(); p.fill(C.mute); p.triangle(W - 30, yy, W - 38, yy - 4, W - 38, yy + 4); p.triangle(30, yy, 38, yy - 4, 38, yy + 4);
        p.textStyle(p.NORMAL); p.textSize(11); p.text('menor', 52, yy + 14); p.text('mayor', W - 52, yy + 14);
        if (locked && !good) { p.fill(C.ok); p.textStyle(p.BOLD); fitText(p, [...r.items].sort((a, b) => a.v - b.v).map(t => t.label).join(' < '), W / 2, H - 20, W - 20, 13); }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY, g = geo();
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; drag = null; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (y < g.y - 60 || y > g.y + 24) return;
        const pos = Math.floor((x - 10) / g.sw);
        if (pos < 0 || pos >= g.n) return;
        drag = { k: O[cur][pos], x }; api.sfx?.tap?.(); return false;
      };
      p.mouseDragged = () => { if (drag) { drag.x = p.mouseX; return false; } };
      p.mouseReleased = () => {
        if (!drag) return;
        const g = geo(), o = O[cur].filter(k => k !== drag.k);
        const pos = Math.min(g.n - 1, Math.max(0, Math.floor((drag.x - 10) / g.sw)));
        o.splice(pos, 0, drag.k); O[cur] = o; moved[cur] = true; drag = null;
        api.ready(moved.every(Boolean));
      };
    }, 1.1);

    return {
      loaded: m.ready,
      getState: () => ({ orders: O.map(o => [...o]) }),
      lock() { locked = true; drag = null; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/bolsa-razon.js
// La bolsa de la razón (Álgebra, razones). Una bolsa transparente con bolas rojas y azules: con − / + se ponen o se
// quitan bolas de cada color. Cada ronda pide una bolsa con una condición de razón: parte-parte («por cada 3 rojas
// hay 2 azules»), parte-todo («2 de cada 5 son azules») con un total o con un dato fijo. Se ven las cantidades sin
// simplificar: el estudiante decide cuándo la razón es la pedida.
// params = { rounds: [{ text, red, blue }], max }   state = { counts: [[rojas, azules] | null por ronda] }

GAMES['bolsa-razon'] = (() => {
  const okRound = (c, r) => Array.isArray(c) && c[0] === r.red && c[1] === r.blue;

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.counts?.[i], r));
    const solution = params.rounds.map(r => `${r.red} rojas y ${r.blue} azules`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds, MAX = params.max || 20;
    const S = R.map(() => ({ red: 0, blue: 0, touched: false }));
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], B = {};

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      const bw = Math.min(44, (w - 48) / 6), y = h - 48, gap = w / 2;
      B = {
        rMinus: { x: 12, y, w: bw, h: 36 }, rPlus: { x: gap - 8 - bw, y, w: bw, h: 36 },
        bMinus: { x: gap + 8, y, w: bw, h: 36 }, bPlus: { x: w - 12 - bw, y, w: bw, h: 36 },
      };
    }
    function change(f) {
      if (locked) return;
      const s = S[cur]; f(s); s.touched = true;
      api.ready(S.every(x => x.touched)); api.sfx?.tap?.();
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function button(b, label, col) {
        drawTile(p, C, b, label, { fill: col === C.bad ? C.coral : C.sky, r: 9, lift: 2, size: 20 });
      }

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], s = S[cur], good = okRound([s.red, s.blue], r);
        const v = locked && !good ? { red: r.red, blue: r.blue } : s;   // al fallar se ve la bolsa correcta en verde
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound([S[i].red, S[i].blue], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : S[i].touched ? C.Q : C.line));
        // Enunciado (hasta tres líneas)
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(W < 300 ? 13 : 14); p.textAlign(p.CENTER, p.TOP); p.textLeading(17);
        p.text(r.text, 14, 46, W - 28, 56);
        // La bolsa
        const top = 106, bot = H - 106, bx = 26, bwid = W - 52;
        p.textAlign(p.CENTER, p.CENTER);
        p.stroke(locked && !good ? C.ok : C.line); p.strokeWeight(2); p.fill(C.card);
        p.rect(bx, top + 10, bwid, bot - top - 10, 18);
        p.noFill(); p.stroke(C.mute); p.strokeWeight(2.5);
        p.line(W / 2 - 22, top + 10, W / 2 - 8, top); p.line(W / 2 + 22, top + 10, W / 2 + 8, top);
        const balls = [...Array(v.red).fill("r"), ...Array(v.blue).fill("b")];
        const perRow = 10, d = Math.min(20, (bwid - 16) / perRow - 3), rows = Math.ceil(balls.length / perRow);
        const step = Math.min(d + 3, (bot - top - 26) / Math.max(rows, 1));
        balls.forEach((c, k) => {
          const row = Math.floor(k / perRow), col = k % perRow;
          const x = bx + 8 + (col + 0.5) * ((bwid - 16) / perRow), y = bot - 8 - (row + 0.5) * step;
          p.noStroke(); p.fill(c === 'r' ? C.coral : C.sky); p.circle(x, y, Math.min(d, step - 2));
        });
        if (!balls.length) { p.noStroke(); p.fill(C.mute); p.textStyle(p.NORMAL); p.textSize(12); p.text('bolsa vacía', W / 2, (top + bot) / 2); }
        // Cuentas
        p.noStroke(); p.textStyle(p.BOLD);
        const ly = H - 72;
        p.fill(C.bad); fitText(p, `rojas: ${v.red}`, W / 4, ly, W / 2 - 16, 14);
        p.fill(C.Z); fitText(p, `azules: ${v.blue}`, (3 * W) / 4, ly, W / 2 - 16, 14);
        p.fill(locked ? C.ok : C.mute); p.textStyle(p.NORMAL);
        fitText(p, locked && !good ? `Era: ${r.red} rojas y ${r.blue} azules` : `en total: ${s.red + s.blue}`, W / 2, H - 90, W - 24, 12);
        button(B.rMinus, '−', C.bad); button(B.rPlus, '+', C.bad); button(B.bMinus, '−', C.Z); button(B.bPlus, '+', C.Z);
        p.noStroke(); p.fill(C.coral); p.circle((B.rMinus.x + B.rMinus.w + B.rPlus.x) / 2, B.rMinus.y + 18, 18);
        p.fill(C.sky); p.circle((B.bMinus.x + B.bMinus.w + B.bPlus.x) / 2, B.bMinus.y + 18, 18);
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(B.rMinus, x, y)) { change(s => { s.red = Math.max(0, s.red - 1); }); return false; }
        if (hitBox(B.rPlus, x, y)) { change(s => { s.red = Math.min(MAX, s.red + 1); }); return false; }
        if (hitBox(B.bMinus, x, y)) { change(s => { s.blue = Math.max(0, s.blue - 1); }); return false; }
        if (hitBox(B.bPlus, x, y)) { change(s => { s.blue = Math.min(MAX, s.blue + 1); }); return false; }
      };
    }, 1.3);

    return {
      loaded: m.ready,
      getState: () => ({ counts: S.map(s => (s.touched ? [s.red, s.blue] : null)) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/estira-foto.js
// Estira la foto (Álgebra, razones). Una foto de w0 × h0 se debe ampliar (o reducir) a un ancho nuevo sin
// deformarla. El ancho ya está puesto; se arrastra el borde de abajo (o − / +) para fijar el alto. El dibujo se
// estira con el marco: solo si ancho : alto es la misma razón que la original el zorrito sale bien; si se suma lo
// mismo a los dos lados, sale aplastado o alargado.
// params = { rounds: [{ w0, h0, w, h }], step, max }   state = { hs: [alto | null por ronda] }

GAMES['estira-foto'] = (() => {
  const okRound = (h, r) => typeof h === 'number' && Math.abs(h - r.h) < 1e-9;

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.hs?.[i], r));
    const solution = params.rounds.map(r => `${String(r.w0)} : ${String(r.h0)} = ${String(r.w)} : ${String(r.h)}`).join(' · ');
    return { ok, solution };
  }

  // El dibujo en las unidades de la foto original (w0 × h0): cielo, colina, sol y una composición de círculo, cuadrado y
  // triángulo (si la foto se deforma, el círculo deja de ser redondo).
  function picture(p, C, w0, h0) {
    const k = Math.min(w0, h0);
    p.noStroke(); p.fill(C.Z); p.rect(0, 0, w0, h0);
    p.fill(C.Q); p.rect(0, h0 * 0.8, w0, h0 * 0.2);
    p.fill(C.N); p.circle(w0 * 0.84, h0 * 0.16, k * 0.22);
    const cx = w0 / 2, cy = h0 * 0.52, r = k * 0.3;
    p.fill(C.coral); p.circle(cx, cy, 2 * r);
    p.fill(C.cream); p.rect(cx - r * 0.5, cy - r * 0.5, r, r);
    p.fill(C.R); p.triangle(cx - r * 0.35, cy + r * 0.3, cx + r * 0.35, cy + r * 0.3, cx, cy - r * 0.32);
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds, STEP = params.step || 0.5, MAX = params.max || 12;
    const hs = R.map(r => r.h0), touched = R.map(() => false);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], B = {}, G = null, drag = false;

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      B = { minus: { x: 12, y: h - 46, w: 44, h: 36 }, plus: { x: w - 56, y: h - 46, w: 44, h: 36 } };
    }
    const geo = () => {
      const r = R[cur], top = 120, room = H - top - 64;
      const u = Math.min((W - 60) / Math.max(r.w, 1), room / MAX);
      return { u, x: (W - r.w * u) / 2, top };
    };
    const snap = v => Math.min(MAX, Math.max(STEP, Math.round(v / STEP) * STEP));
    function setH(v) {
      if (locked) return;
      hs[cur] = snap(v); touched[cur] = true; api.ready(touched.every(Boolean));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], good = okRound(hs[cur], r), h = locked && !good ? r.h : hs[cur];   // al fallar se ve la foto correcta
        G = geo();
        const { u, x, top } = G;
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound(hs[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : touched[i] ? C.Q : C.line));
        // Enunciado y foto original en miniatura
        p.textAlign(p.LEFT, p.CENTER); p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
        fitText(p, `Ampliar a ${String(r.w)} de ancho`, 14, 56, W - 96, 14);
        p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'sin deformar la foto', 14, 76, W - 96, 12);
        const tk = Math.min(60 / r.w0, 44 / r.h0), tw = r.w0 * tk, th = r.h0 * tk, tx = W - 14 - tw, ty = 46;
        p.push(); p.translate(tx, ty); p.scale(tk, tk); picture(p, C, r.w0, r.h0); p.pop();
        p.noFill(); p.stroke(C.line); p.strokeWeight(1); p.rect(tx, ty, tw, th);
        p.noStroke(); p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.textSize(10);
        p.text(`original ${String(r.w0)} × ${String(r.h0)}`, Math.min(tx + tw / 2, W - 50), ty + th + 2);
        // Cuadrícula de unidades y la foto estirada
        p.stroke(C.line); p.strokeWeight(0.6);
        for (let k = 0; k <= r.w; k++) p.line(x + k * u, top, x + k * u, top + MAX * u);
        for (let k = 0; k <= MAX; k++) p.line(x, top + k * u, x + r.w * u, top + k * u);
        p.push(); p.translate(x, top); p.scale((r.w * u) / r.w0, (h * u) / r.h0); picture(p, C, r.w0, r.h0); p.pop();
        p.noFill(); p.stroke(locked ? C.ok : C.coral); p.strokeWeight(3); p.rect(x, top, r.w * u, h * u);
        if (!locked) { p.noStroke(); p.fill(C.coral); p.rect(x + (r.w * u) / 2 - 18, top + h * u - 4, 36, 8, 4); }
        // Medidas
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textAlign(p.CENTER, p.BOTTOM); p.textSize(12);
        p.text(String(r.w), x + (r.w * u) / 2, top - 2);
        p.textAlign(p.RIGHT, p.CENTER); p.text(String(h), x - 4, top + (h * u) / 2);
        // Lectura y botones
        p.textAlign(p.CENTER, p.CENTER);
        const msg = locked && !good ? `Era ${String(r.h)} de alto` : `ancho : alto = ${String(r.w)} : ${String(h)}`;
        p.fill(locked ? C.ok : C.ink); fitText(p, msg, W / 2, H - 28, W - 132, 14);
        for (const [b, t] of [[B.minus, '−'], [B.plus, '+']]) {
          drawTile(p, C, b, t, { fill: C.sky, r: 9, lift: 2, size: 20 });
        }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; drag = false; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(B.minus, x, y)) { setH(hs[cur] - STEP); api.sfx?.tap?.(); return false; }
        if (hitBox(B.plus, x, y)) { setH(hs[cur] + STEP); api.sfx?.tap?.(); return false; }
        // Se arrastra el borde de abajo del marco (no cualquier toque en la cuadrícula).
        if (G && Math.abs(y - (G.top + hs[cur] * G.u)) < 32) { drag = true; setH((y - G.top) / G.u); return false; }
      };
      p.mouseDragged = () => { if (drag && G) { setH((p.mouseY - G.top) / G.u); return false; } };
      p.mouseReleased = () => { drag = false; };
    }, 1.45);

    return {
      loaded: m.ready,
      getState: () => ({ hs: hs.map((h, i) => (touched[i] ? h : null)) }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create };
})();
;
//#archivo js/games/sombra-arbol.js
// La sombra del árbol (Álgebra, proporciones). A la misma hora los rayos del sol llegan paralelos, así que la altura
// de cada cosa y su sombra están en la misma razón: palo / sombra del palo = árbol / sombra del árbol. Se conoce el
// palo y su sombra, y se midió la sombra del árbol (la banderita). Se ajusta la altura del árbol (arrastre o − / +)
// hasta que el rayo que pasa por su copa caiga justo en la banderita.
// params = { rounds: [{ stick, shadow, treeShadow, tree }], step, max }   state = { hs: [altura | null por ronda] }

GAMES['sombra-arbol'] = (() => {
  const okRound = (h, r) => typeof h === 'number' && Math.abs(h - r.tree) < 1e-9;
  const shadowOf = (h, r) => (h * r.shadow) / r.stick;

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.hs?.[i], r));
    const solution = params.rounds.map(r => `${String(r.stick)}/${String(r.shadow)} = h/${String(r.treeShadow)} → h = ${String(r.tree)} m`).join(' · ');
    return { ok, solution };
  }

  function create(host, params, api) {
    const C = api.palette, R = params.rounds, STEP = params.step || 0.5, MAX = params.max || 12;
    const hs = R.map(() => STEP * 4), touched = R.map(() => false);
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], B = {}, G = null, drag = false;

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      B = { minus: { x: 12, y: h - 46, w: 44, h: 36 }, plus: { x: w - 56, y: h - 46, w: 44, h: 36 } };
    }
    const geo = () => {
      const r = R[cur], ground = H - 96, room = ground - 104;
      const u = Math.min((W - 92) / (r.shadow + r.treeShadow), room / MAX);
      const xs = 22, xt = xs + r.shadow * u + 44;   // hueco para el rótulo del árbol, lejos del rayo del palo
      return { u, ground, xs, xt };
    };
    const snap = v => Math.min(MAX, Math.max(STEP, Math.round(v / STEP) * STEP));
    function setH(v) {
      if (locked) return;
      hs[cur] = snap(v); touched[cur] = true; api.ready(touched.every(Boolean));
    }

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function dashed(x1, y1, x2, y2) {
        const n = Math.max(1, Math.floor(Math.hypot(x2 - x1, y2 - y1) / 8));
        for (let k = 0; k < n; k += 2) p.line(x1 + ((x2 - x1) * k) / n, y1 + ((y2 - y1) * k) / n, x1 + ((x2 - x1) * (k + 1)) / n, y1 + ((y2 - y1) * (k + 1)) / n);
      }

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], h = hs[cur], good = okRound(h, r);
        G = geo();
        const { u, ground, xs, xt } = G;
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound(hs[i], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : touched[i] ? C.Q : C.line));
        p.textAlign(p.CENTER, p.CENTER); p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
        fitText(p, '¿Cuánto mide el árbol?', W / 2, 56, W - 24, 15);
        p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'Su sombra termina en la banderita: usa la proporción', W / 2, 76, W - 24, 12);
        // Suelo
        p.stroke(C.mint); p.strokeWeight(4); p.line(8, ground, W - 8, ground);
        // Palo y su sombra
        const sEnd = xs + r.shadow * u;
        p.noStroke(); p.fill(C.mute); p.rect(xs, ground + 2, r.shadow * u, 5, 2);
        p.stroke(C.ink); p.strokeWeight(4); p.line(xs, ground, xs, ground - r.stick * u);
        p.stroke(C.N); p.strokeWeight(2); dashed(xs, ground - r.stick * u, sEnd, ground);
        p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(11);
        p.textAlign(p.CENTER, p.BOTTOM); p.text(`${String(r.stick)} m`, Math.max(xs, 18), ground - r.stick * u - 5);
        p.textAlign(p.CENTER, p.TOP); p.fill(C.mute); p.text(`${String(r.shadow)} m`, xs + (r.shadow * u) / 2, ground + 8);
        // Banderita: donde termina la sombra medida del árbol
        const fx = xt + r.treeShadow * u;
        p.stroke(C.ink); p.strokeWeight(1.5); p.line(fx, ground, fx, ground - 16);
        p.noStroke(); p.fill(C.coral); p.triangle(fx, ground - 18, fx + 12, ground - 13.5, fx, ground - 9);
        p.fill(C.mute); p.textAlign(p.CENTER, p.TOP); p.text(`sombra: ${String(r.treeShadow)} m`, (xt + fx) / 2, ground + 8);
        // Árbol. Mientras se juega solo se ve su altura (hay que calcularla con la proporción); al comprobar
        // aparece el rayo de su copa, y si estaba mal, el árbol correcto en verde con su rayo justo a la banderita.
        const hv = locked && !good ? r.tree : h;
        const top = ground - hv * u, end = xt + shadowOf(hv, r) * u;
        p.stroke('#8a5a2b'); p.strokeWeight(5); p.line(xt, ground, xt, top + Math.min(14, hv * u * 0.35));
        const d = Math.max(16, Math.min(34, hv * u * 0.45));
        p.noStroke(); p.fill(locked ? C.ok : C.mint); p.circle(xt, top + d / 2, d);
        if (locked) {
          p.stroke(C.N); p.strokeWeight(2); const x2 = Math.min(end, W - 6);   // si la sombra se sale del lienzo, el rayo se corta en el borde
          dashed(xt, top, x2, top + ((x2 - xt) * (hv * u)) / Math.max(1e-6, end - xt));
        }
        // Rótulo a la izquierda del tronco: el rayo sale hacia la derecha y no lo tapa.
        p.noStroke(); p.fill(locked ? C.ok : C.ink); p.textStyle(p.BOLD); p.textAlign(p.RIGHT, p.CENTER); p.textSize(12);
        p.text(`${String(hv)} m`, xt - Math.max(9, d / 2 + 3), ground - Math.max(hv * u / 2, 10));
        // Lectura y botones
        p.textAlign(p.CENTER, p.CENTER);
        const msg = locked && !good ? `Medía ${String(r.tree)} m` : `árbol: ${String(h)} m`;
        p.fill(locked ? C.ok : C.ink); fitText(p, msg, W / 2, H - 28, W - 132, 14);
        for (const [b, t] of [[B.minus, '−'], [B.plus, '+']]) {
          drawTile(p, C, b, t, { fill: C.sky, r: 9, lift: 2, size: 20 });
        }
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; drag = false; api.sfx?.tap?.(); return false; }
        if (locked) return;
        if (hitBox(B.minus, x, y)) { setH(hs[cur] - STEP); api.sfx?.tap?.(); return false; }
        if (hitBox(B.plus, x, y)) { setH(hs[cur] + STEP); api.sfx?.tap?.(); return false; }
        if (G && y > 88 && y < G.ground && Math.abs(x - G.xt) < 40) { drag = true; setH((G.ground - y) / G.u); return false; }
      };
      p.mouseDragged = () => { if (drag && G) { setH((G.ground - p.mouseY) / G.u); return false; } };
      p.mouseReleased = () => { drag = false; };
    }, 1.45);

    return {
      loaded: m.ready,
      getState: () => ({ hs: hs.map((h, i) => (touched[i] ? h : null)) }),
      lock() { locked = true; drag = false; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, shadowOf };
})();
;
//#archivo js/games/pisa-huellas.js
// Pisa las huellas (Álgebra, progresiones aritméticas). Un caminante da pasos iguales sobre la recta: el paso 1 cae
// en a₁ y cada paso avanza d (o retrocede, si d es negativo). Dos banderas marcan dónde cayeron dos pasos conocidos.
// Con − / + se fijan a₁ y d; las huellas numeradas se mueven en vivo. Gana cuando las dos huellas pisan sus banderas:
// aₖ = a₁ + (k − 1)d.
// params = { rounds: [{ known: [[k, valor], [k, valor]], a1, d }] }   state = { ans: [[a1, d] | null por ronda] }

GAMES['pisa-huellas'] = (() => {
  const termAt = (a1, d, k) => a1 + (k - 1) * d;
  const okRound = (a, r) => Array.isArray(a) && r.known.every(([k, v]) => termAt(a[0], a[1], k) === v);

  function grade(state, params) {
    const ok = params.rounds.every((r, i) => okRound(state.ans?.[i], r));
    return { ok, solution: params.rounds.map(r => `a₁ = ${r.a1}, d = ${r.d}`.replace(/-/g, '−')).join(' · ') };
  }

  const neg = v => String(v).replace('-', '−');

  function create(host, params, api) {
    const C = api.palette, R = params.rounds;
    const A = R.map(() => ({ a1: 0, d: 1, touched: false }));
    let locked = false, W = 0, H = 0, cur = 0, tabs = [], B = {}, hold = null;

    function layout(w, h) {
      W = w; H = h; tabs = roundTabs(R.length, w);
      const bw = 44, y1 = h - 92, y2 = h - 48;
      B = { aM: { x: w - 2 * bw - 22, y: y1, w: bw, h: 36 }, aP: { x: w - bw - 12, y: y1, w: bw, h: 36 },
        dM: { x: w - 2 * bw - 22, y: y2, w: bw, h: 36 }, dP: { x: w - bw - 12, y: y2, w: bw, h: 36 } };
    }
    function change(f) {
      if (locked) return;
      const a = A[cur]; f(a); a.touched = true;
      api.ready(A.every(x => x.touched)); api.sfx?.tap?.();
    }
    // Recta fija por ronda (las banderas no se mueven): abarca los pasos correctos con margen. Las huellas que caen
    // fuera no se amontonan: se cuentan con una flecha en el borde.
    function range(r) {
      const n = Math.max(...r.known.map(k => k[0])) + 1;
      const vals = Array.from({ length: n }, (_, k) => termAt(r.a1, r.d, k + 1));
      return { n, lo: Math.min(0, ...vals) - 3, hi: Math.max(...vals) + 3 };
    }
    // Cada botón: qué hace al tocarlo (mantenerlo pulsado repite el paso).
    const ACT = {
      aM: a => { a.a1 = Math.max(-30, a.a1 - 1); }, aP: a => { a.a1 = Math.min(40, a.a1 + 1); },
      dM: a => { a.d = Math.max(-10, a.d - 1); }, dP: a => { a.d = Math.min(10, a.d + 1); },
    };

    const m = mountSketch(host, (p, size) => {
      p.setup = () => { p.createCanvas(size.w, size.h); p.textFont('system-ui'); layout(size.w, size.h); };
      p.onResize = () => layout(size.w, size.h);

      function button(b, t) {
        drawTile(p, C, b, t, { fill: C.sky, r: 9, lift: 2, size: 20 });
      }

      p.draw = () => {
        p.background(C.bg);
        const r = R[cur], a = locked && !okRound([A[cur].a1, A[cur].d], r) ? { a1: r.a1, d: r.d } : A[cur];
        const good = okRound([A[cur].a1, A[cur].d], r);
        drawTabs(p, C, tabs, cur, i => (locked ? (okRound([A[i].a1, A[i].d], R[i]) ? C.ok : C.bad) : i === cur ? C.brand : A[i].touched ? C.Q : C.line));
        const [[k1, v1], [k2, v2]] = r.known;
        p.textAlign(p.CENTER, p.CENTER); p.noStroke(); p.fill(C.ink); p.textStyle(p.BOLD);
        fitText(p, `El paso ${k1} cayó en ${neg(v1)} y el paso ${k2} en ${neg(v2)}`, W / 2, 56, W - 24, 14);
        p.fill(C.mute); p.textStyle(p.NORMAL); fitText(p, 'Elige el primer paso y el salto', W / 2, 76, W - 24, 12);
        // Recta
        if (hold && p.mouseIsPressed && !locked && p.frameCount - hold.f > 18 && p.frameCount % 4 === 0) change(ACT[hold.k]);
        const { n, lo, hi } = range(r), x0 = 16, x1 = W - 16, ly = H * 0.47;
        const X = v => x0 + ((v - lo) / (hi - lo)) * (x1 - x0);
        p.stroke(C.ink); p.strokeWeight(3); p.line(x0, ly, x1, ly);
        const every = hi - lo > 60 ? 10 : hi - lo > 30 ? 5 : hi - lo > 14 ? 2 : 1;
        for (let v = Math.ceil(lo); v <= hi; v++) {
          if (v % every) continue;
          p.stroke(C.ink); p.strokeWeight(1.5); p.line(X(v), ly - 5, X(v), ly + 5);
          if (v % (every * 2) === 0 || every >= 5) { p.noStroke(); p.fill(C.mute); p.textSize(10); p.text(neg(v), X(v), ly + 34); }
        }
        // Banderas de los pasos conocidos
        for (const [k, v] of r.known) {
          const fx = X(v);
          p.stroke(C.ink); p.strokeWeight(1.5); p.line(fx, ly, fx, ly - 46);
          p.noStroke(); p.fill(C.coral); p.triangle(fx, ly - 46, fx + 13, ly - 41.5, fx, ly - 37);
          p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(10); p.text(`paso ${k}`, fx, ly - 54);
        }
        // Huellas: arriba y abajo de la recta, alternadas, para que no se tapen
        let left = 0, right = 0;
        for (let k = 1; k <= n; k++) {
          const v = termAt(a.a1, a.d, k);
          if (v < lo) { left++; continue; }
          if (v > hi) { right++; continue; }
          const x = X(v), up = k % 2 === 1, y = up ? ly - 16 : ly + 16;
          const hit = r.known.some(([kk, vv]) => kk === k && vv === v);
          const fc = hit || locked ? C.ok : C.sky;   // huellas azules; verdes cuando pisan una bandera
          p.noStroke(); p.fill(fc); p.ellipse(x, y, 14, 18);
          p.fill(inkOn(fc, C.bg)); p.textStyle(p.BOLD); p.textSize(9); p.text(k, x, y + 1);
        }
        p.noStroke(); p.fill(C.brand); p.textStyle(p.BOLD); p.textSize(11);
        if (left) { p.triangle(x0 - 6, ly, x0 + 2, ly - 5, x0 + 2, ly + 5); p.textAlign(p.LEFT, p.CENTER); p.text(`${left} huellas`, x0, ly + 54); }
        if (right) { p.triangle(x1 + 6, ly, x1 - 2, ly - 5, x1 - 2, ly + 5); p.textAlign(p.RIGHT, p.CENTER); p.text(`${right} huellas`, x1, ly + 54); }
        p.textAlign(p.CENTER, p.CENTER);
        // Controles y lectura
        p.textAlign(p.LEFT, p.CENTER); p.fill(C.ink); p.textStyle(p.BOLD); p.textSize(15);
        p.text(`a₁ = ${neg(a.a1)}`, 16, B.aM.y + 18); p.text(`d = ${neg(a.d)}`, 16, B.dM.y + 18);
        p.textAlign(p.CENTER, p.CENTER);
        button(B.aM, '−'); button(B.aP, '+'); button(B.dM, '−'); button(B.dP, '+');
        const msg = locked ? (good ? '¡Las dos huellas pisan su bandera!' : `Era a₁ = ${neg(r.a1)} y d = ${neg(r.d)}`)
          : `paso ${k2}: ${neg(a.a1)} + ${k2 - 1} · ${a.d < 0 ? `(${neg(a.d)})` : a.d} = ${neg(termAt(a.a1, a.d, k2))}`;
        p.fill(locked ? C.ok : C.mute); p.textStyle(p.NORMAL); fitText(p, msg, W / 2, B.aM.y - 18, W - 24, 12);
      };

      p.mousePressed = () => {
        const x = p.mouseX, y = p.mouseY;
        const tb = tabs.findIndex(b => hitBox(b, x, y));
        if (tb >= 0) { cur = tb; api.sfx?.tap?.(); return false; }
        if (locked) return;
        for (const k of Object.keys(ACT)) if (hitBox(B[k], x, y)) { change(ACT[k]); hold = { k, f: p.frameCount }; return false; }
      };
      p.mouseReleased = () => { hold = null; };
    }, 1.25);

    return {
      loaded: m.ready,
      getState: () => ({ ans: A.map(a => (a.touched ? [a.a1, a.d] : null)) }),
      lock() { locked = true; },
      destroy: () => m.remove(),
    };
  }

  return { grade, create, termAt };
})();
